INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L05_basic#2','math',4,1,'u6','L05','g4_1_math_u6_L05_basic','lesson_basic','M4-1-u6-C9',1,'mc','auto','쌓기나무 배열에서 변하지 않는 부분은 어느 것인가요?',ARRAY['M4-1-u6-X12']::text[],true,'{"seq":2,"concept":"M4-1-u6-C9","difficulty":1,"kind":"mc","stem":"쌓기나무 배열에서 변하지 않는 부분은 어느 것인가요?","options":[{"t":"맨 위의 노란 1개","correct":true},{"t":"맨 아래 줄 전체","mis":"M4-1-u6-X12"},{"t":"왼쪽 끝 한 줄","mis":"M4-1-u6-X12"},{"t":"변하지 않는 부분이 없어요","mis":"M4-1-u6-X12"}],"explanation":["모든 모양에 똑같은 자리에 그대로 있는 것이 변하지 않는 부분이에요.","맨 위의 노란 1개는 어느 모양에서나 그대로 있어요.","나머지가 늘어나는 부분이에요 — 1, 4, 9, 16."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[5,0,0,0],[6,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[4,0,1,0],[5,0,1,0],[2,0,2,0],[3,0,2,0],[4,0,2,0],[3,0,3,"y"]]]},"variant_rule":{"alt":[{"stem":"사각형 배열에서 변하지 않는 부분은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"가운데 색칠한 1개","correct":true},{"t":"맨 오른쪽 끝의 1개","mis":"M4-1-u6-X12"},{"t":"위쪽으로 늘어난 줄 전체","mis":"M4-1-u6-X12"},{"t":"변하지 않는 부분이 없어요","mis":"M4-1-u6-X12"}],"explanation":["모든 모양에 똑같은 자리에 그대로 있는 것이 변하지 않는 부분이에요.","가운데 색칠한 1개는 어느 모양에서나 그대로 있어요.","나머지가 늘어나는 부분이에요 — 5, 9, 13."],"asset":{"type":"tiles","pieces":[{"p":[[1,5],[2,5],[2,6],[1,6]],"hi":true},{"p":[[2,5],[3,5],[3,6],[2,6]]},{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[1,6],[2,6],[2,7],[1,7]]},{"p":[[1,4],[2,4],[2,5],[1,5]]},{"p":[[7,4],[8,4],[8,5],[7,5]],"hi":true},{"p":[[8,4],[9,4],[9,5],[8,5]]},{"p":[[9,4],[10,4],[10,5],[9,5]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[5,4],[6,4],[6,5],[5,5]]},{"p":[[7,5],[8,5],[8,6],[7,6]]},{"p":[[7,6],[8,6],[8,7],[7,7]]},{"p":[[7,3],[8,3],[8,4],[7,4]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":