INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L05_basic#6','math',4,1,'u6','L05','g4_1_math_u6_L05_basic','lesson_basic','M4-1-u6-C10',2,'mc','auto','피라미드 모양 쌓기나무 배열의 셋째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M4-1-u6-X15','M4-1-u6-X13']::text[],true,'{"seq":6,"concept":"M4-1-u6-C10","difficulty":2,"kind":"mc","stem":"피라미드 모양 쌓기나무 배열의 셋째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5","correct":true},{"t":"1+2+3","mis":"M4-1-u6-X15"},{"t":"3+3+3","mis":"M4-1-u6-X15"},{"t":"1+3","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","셋째 모양은 3층 — 1+3+5.","1+3+5 = 9개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]},"variant_rule":{"alt":[{"stem":"피라미드 모양 쌓기나무 배열의 넷째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5+7","correct":true},{"t":"1+2+3+4","mis":"M4-1-u6-X15"},{"t":"4+4+4+4","mis":"M4-1-u6-X15"},{"t":"1+3+5","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","넷째 모양은 4층 — 1+3+5+7.","1+3+5+7 = 16개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}},{"stem":"피라미드 모양 쌓기나무 배열의 다섯째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5+7+9","correct":true},{"t":"1+2+3+4+5","mis":"M4-1-u6-X15"},{"t":"5+5+5+5+5","mis":"M4-1-u6-X15"},{"t":"1+3+5+7","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","다섯째 모양은 5층 — 1+3+5+7+9.","1+3+5+7+9 = 25개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}}]}}'::jsonb) ON CONFLICT (qcode) D