INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L05_challenge#1','math',4,1,'u6','L05','g4_1_math_u6_L05_challenge','lesson_challenge','M4-1-u6-C10',2,'mc','auto','피라미드 모양 쌓기나무 배열에서 「1+3+5+7+9」는 몇째 모양의 쌓기나무 수인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X11']::text[],true,'{"seq":1,"concept":"M4-1-u6-C10","difficulty":2,"kind":"mc","stem":"피라미드 모양 쌓기나무 배열에서 「1+3+5+7+9」는 몇째 모양의 쌓기나무 수인가요?","options":[{"t":"다섯째","correct":true},{"t":"넷째","mis":"M4-1-u6-X13"},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"아홉째","mis":"M4-1-u6-X11"}],"explanation":["첫째는 1, 둘째는 1+3, 셋째는 1+3+5 — 더하는 수가 하나씩 늘어요.","「1+3+5+7+9」에는 수가 5개 있어요.","그래서 다섯째 모양이에요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]},"variant_rule":{"alt":[{"stem":"피라미드 모양 쌓기나무 배열에서 「1+3+5+7」은 몇째 모양의 쌓기나무 수인가요?","options":[{"t":"넷째","correct":true},{"t":"셋째","mis":"M4-1-u6-X13"},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X11"}],"explanation":["첫째는 1, 둘째는 1+3, 셋째는 1+3+5 — 더하는 수가 하나씩 늘어요.","「1+3+5+7」에는 수가 4개 있어요.","그래서 넷째 모양이에요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}},{"stem":"피라미드 모양 쌓기나무 배열에서 「1+3+5+7+9+11」은 몇째 모양의 쌓기나무 수인가요?","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"열한째","mis":"M4-1-u6-X11"}],"explanation":["첫째는 1, 둘째는 1+3, 셋째는 1+3+5 — 더하는 수가 하나씩 늘어요.","「1+3+5+7+9+11」에는 수가 6개 있어요.","그래서 여섯째 모양이에요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}}]}}'::jsonb) ON CONFLICT (qcode) 