INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L05_challenge#2','math',4,1,'u6','L05','g4_1_math_u6_L05_challenge','lesson_challenge','M4-1-u6-C9',2,'mc','auto','사각형 배열에서 변하지 않는 부분은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.',ARRAY['M4-1-u6-X12']::text[],true,'{"seq":2,"concept":"M4-1-u6-C9","difficulty":2,"kind":"mc","stem":"사각형 배열에서 변하지 않는 부분은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"모서리의 색칠한 1개","correct":true},{"t":"위쪽으로 놓인 줄 전체","mis":"M4-1-u6-X12"},{"t":"오른쪽 끝의 1개","mis":"M4-1-u6-X12"},{"t":"변하지 않는 부분이 없어요","mis":"M4-1-u6-X12"}],"explanation":["모든 모양에 똑같은 자리에 그대로 있는 것이 변하지 않는 부분이에요.","모서리의 색칠한 1개는 어느 모양에서나 그대로 있어요.","나머지가 늘어나는 부분이에요 — 3, 5, 7."],"asset":{"type":"tiles","pieces":[{"p":[[0,3],[1,3],[1,4],[0,4]],"hi":true},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[1,3],[2,3],[2,4],[1,4]]},{"p":[[4,3],[5,3],[5,4],[4,4]],"hi":true},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[5,3],[6,3],[6,4],[5,4]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[9,3],[10,3],[10,4],[9,4]],"hi":true},{"p":[[9,2],[10,2],[10,3],[9,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,0],[10,0],[10,1],[9,1]]},{"p":[[10,3],[11,3],[11,4],[10,4]]},{"p":[[11,3],[12,3],[12,4],[11,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]}],"u":16},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 사각형 배열에서 변하지 않는 부분은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"가운데 색칠한 1개","correct":true},{"t":"왼쪽으로 늘어난 줄 전체","mis":"M4-1-u6-X12"},{"t":"맨 위의 1개","mis":"M4-1-u6-X12"},{"t":"변하지 않는 부분이 없어요","mis":"M4-1-u6-X12"}],"explanation":["모든 모양에 똑같은 자리에 그대로 있는 것이 변하지 않는 부분이에요.","가운데 색칠한 1개는 어느 모양에서나 그대로 있어요.","나머지가 늘어나는 부분이에요 — 4, 7, 10."],"asset":{"type":"tiles","pieces":[{"p":[[1,3],[2,3],[2,4],[1,4]],"hi":true},{"p":[[0,3],[1,3],[1,4],[0,4]]},{"p":[[2,3],[3,3],[3,4],[2,4]]},{"p":[[1,2],[2,2],[2,3],[1,3]]},{"p":[[7,3],[8,3],[8,4],[7,4]],"hi":tru