INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_basic#3','math',4,1,'u6','L06','g4_1_math_u6_L06_basic','lesson_basic','M4-1-u6-C12',1,'mc','auto','서윤이와 시우가 만든 사각형 배열이에요(왼쪽 셋은 서윤, 오른쪽 셋은 시우의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?',ARRAY['M4-1-u6-X14','M4-1-u6-X09']::text[],true,'{"seq":3,"concept":"M4-1-u6-C12","difficulty":1,"kind":"mc","stem":"서윤이와 시우가 만든 사각형 배열이에요(왼쪽 셋은 서윤, 오른쪽 셋은 시우의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?","options":[{"t":"개수가 같게 늘어나니 같은 규칙이에요","correct":true},{"t":"모양이 다르니 규칙도 달라요","mis":"M4-1-u6-X14"},{"t":"한 사람은 반드시 틀렸어요","mis":"M4-1-u6-X09"},{"t":"모양이 다르면 견줄 수 없어요","mis":"M4-1-u6-X14"}],"explanation":["두 배열 모두 3, 5, 7 — 2개씩 늘어나요.","모양은 달라도 개수가 같게 변해요.","그래서 같은 규칙으로 만든 다른 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]},{"p":[[13,5],[14,5],[14,6],[13,6]]},{"p":[[13,4],[14,4],[14,5],[13,5]]},{"p":[[13,6],[14,6],[14,7],[13,7]]},{"p":[[16,4],[17,4],[17,5],[16,5]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[16,2],[17,2],[17,3],[16,3]]},{"p":[[16,5],[17,5],[17,6],[16,6]]},{"p":[[16,6],[17,6],[17,7],[16,7]]},{"p":[[19,3],[20,3],[20,4],[19,4]]},{"p":[[19,2],[20,2],[20,3],[19,3]]},{"p":[[19,1],[20,1],[20,2],[19,2]]},{"p":[[19,0],[20,0],[20,1],[19,1]]},{"p":[[19,4],[20,4],[20,5],[19,5]]},{"p":[[19,5],[20,5],[20,6],[19,6]]},{"p":[[19,6],[20,6],[20,7],[19,7]]}],"u":12},"variant_rule":{"alt":[{"stem":"