],[3,5]]},{"p":[[3,3],[4,3],[4,4],[3,4]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[3,5],[4,5],[4,6],[3,6]]},{"p":[[3,6],[4,6],[4,7],[3,7]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[6,2],[7,2],[7,3],[6,3]]},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[6,5],[7,5],[7,6],[6,6]]},{"p":[[6,6],[7,6],[7,7],[6,7]]},{"p":[[10,3],[11,3],[11,4],[10,4]]},{"p":[[10,2],[11,2],[11,3],[10,3]]},{"p":[[11,3],[12,3],[12,4],[11,4]]},{"p":[[14,3],[15,3],[15,4],[14,4]]},{"p":[[14,2],[15,2],[15,3],[14,3]]},{"p":[[14,1],[15,1],[15,2],[14,2]]},{"p":[[15,3],[16,3],[16,4],[15,4]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[19,3],[20,3],[20,4],[19,4]]},{"p":[[19,2],[20,2],[20,3],[19,3]]},{"p":[[19,1],[20,1],[20,2],[19,2]]},{"p":[[19,0],[20,0],[20,1],[19,1]]},{"p":[[20,3],[21,3],[21,4],[20,4]]},{"p":[[21,3],[22,3],[22,4],[21,4]]},{"p":[[22,3],[23,3],[23,4],[22,4]]}],"u":12}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_basic#4','math',4,1,'u6','L06','g4_1_math_u6_L06_basic','lesson_basic','M4-1-u6-C12',1,'sa','auto','종이 빨대로 만든 배열의 개수가 「3, 9, 18, 30」으로 늘어나요. 늘어나는 수가 어떻게 변하는지 살펴 넷째 다음에 늘어날 수를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u6-C12","difficulty":1,"kind":"sa","stem":"종이 빨대로 만든 배열의 개수가 「3, 9, 18, 30」으로 늘어나요. 늘어나는 수가 어떻게 변하는지 살펴 넷째 다음에 늘어날 수를 구하세요. 숫자로 쓰세요.","answer":["15"],"explanation":["늘어난 수를 구하면 6, 9, 12예요.","늘어나는 수가 3씩 커져요.","12 + 3 = 15 — 다음에는 15개가 늘어나요."],"variant_rule":{"alt":[{"stem":"종이 빨대로 만든 배열의 개수가 「1, 4, 9, 16」으로 늘어나요. 늘어나는 수가 어떻게 변하는지 살펴 넷째 다음에 늘어날 수를 구하세요. 숫자로 쓰세요.","answer":["9"],"explanation":["늘어난 수를 구하면 3, 5, 7이에요.","늘어나는 수가 2씩 커져요.","7 + 2 = 9 — 다음에는 9개가 늘어나요."],"asset":null},{"stem":"종이 빨대로 만든 배열의 개수가 「2, 6, 12, 20」으로 늘어나요. 늘어나는 수가 어떻게 변하는지 살펴 넷째 다음에 늘어날 수를 구하세요. 숫자로 쓰세요.","answer":["10"],"explanation":["늘어난 수를 구하면 4, 6, 8이에요.","늘어나는 수가 2씩 커져요.","8 + 2 = 10 — 다음에는 10개가 늘어나요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_basic#5','math',4,1,'u6','L06','g4_1_math_u6_L06_basic','lesson_basic','M4-1-u6-C11',2,'mc','auto','사각형 15개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.',ARRAY['M4-1-u6-X13','M4-1-u6-X11']::text[],true,'{"seq":5,"concept":"M4-1-u6-C11","difficulty":2,"kind":"mc","stem":"사각형 15개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"아홉째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 3개이고 2개씩 늘어나요.","3부터 2씩 세어 봐요 — 3, 5, 7, 9, 11, 13, 15.","15는 7번째에 나오니 일곱째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형 24개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 4개이고 4개씩 늘어나요.","4부터 4씩 세어 봐요 — 4, 8, 12, 16, 20, 24.","24는 6번째에 나오니 여섯째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[2,5],[3,5],[3,6],[2,6]]},{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[1,6],[2,6],[2,7],[1,7]]},{"p":[[1,4],[2,4],[2,5],[1,5]]},{"p":[[8,4],[9,4],[9,5],[8,5]]},{"p":[[9,4],[10,4],[10,5],[9,5]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[5,4],[6,4],[6,5],[5,5]]},{"p":[[7,5],[8,5],[8,6],[7,6]]},{"p":[[7,6],[8,6],[8,7],[7,7]]},{"p":[[7,3],[8,3],[