INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_basic#6','math',4,1,'u6','L06','g4_1_math_u6_L06_basic','lesson_basic','M4-1-u6-C11',2,'mc','auto','사각형 배열에서 왼쪽 위 1개를 변하지 않는 부분으로 보았어요. 셋째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.',ARRAY['M4-1-u6-X13','M4-1-u6-X12','M4-1-u6-X11']::text[],true,'{"seq":6,"concept":"M4-1-u6-C11","difficulty":2,"kind":"mc","stem":"사각형 배열에서 왼쪽 위 1개를 변하지 않는 부분으로 보았어요. 셋째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"1+2+2+2","correct":true},{"t":"1+2+2","mis":"M4-1-u6-X13"},{"t":"3+2+2+2","mis":"M4-1-u6-X12"},{"t":"1+3+3+3","mis":"M4-1-u6-X11"}],"explanation":["왼쪽 위 1개를 그대로 두고 나머지를 2개씩 묶어요.","셋째 모양은 7개 = 1+2+2+2.","기준이 달라지면 식은 달라도 개수는 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형 배열에서 왼쪽 세로 3개를 변하지 않는 부분으로 보았어요. 넷째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"3+2+2+2","correct":true},{"t":"3+2+2+2+2","mis":"M4-1-u6-X13"},{"t":"1+2+2+2","mis":"M4-1-u6-X12"},{"t":"3+3+3+3","mis":"M4-1-u6-X11"}],"explanation":["왼쪽 세로 3개를 그대로 두고 나머지를 2개씩 묶어요.","넷째 모양은 9개 = 3+2+2+2.","기준이 달라지면 식은 달라도 개수는 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}},{"stem":"사각형 배열에서 왼쪽 위 1개를 변하지 않는 부분으로 보았어요. 다섯째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"1+2+2+2+2+2","correct":true},{"t":"1+2+2+2+2","mis":"M4-1-u6-X13"},{"t":"3+2+2+2+2+2","mis":"M4-1-u6-X12"},{"t":"1+3+3+3+3+3","mis":"M4-1-u6-X11"}],"explanation":["왼쪽 위 1개를 그대로 두고 나머지를 2개씩 묶어요.","다섯째 모양은 11개 = 1+2+2+2+2+2.","기준이 달라지면 식은 달라도 개수는 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_basic#7','math',4,1,'u6','L06','g4_1_math_u6_L06_basic','lesson_basic','M4-1-u6-C11',2,'mc','auto','같은 사각형 배열의 셋째 모양을 지아는 「3+2+2」, 준서는 「1+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?',ARRAY['M4-1-u6-X09','M4-1-u6-X12']::text[],true,'{"seq":7,"concept":"M4-1-u6-C11","difficulty":2,"kind":"mc","stem":"같은 사각형 배열의 셋째 모양을 지아는 「3+2+2」, 준서는 「1+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"기준이 달라 식은 달라도 개수가 같아 둘 다 맞아요","correct":true},{"t":"식이 다르니 한 사람은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 많이 쓰인 준서의 식만 맞아요","mis":"M4-1-u6-X09"},{"t":"처음 수가 큰 지아의 식만 맞아요","mis":"M4-1-u6-X12"}],"explanation":["지아는 처음 3개를, 준서는 1개를 변하지 않는 부분으로 봤어요.","3+2+2 = 7, 1+2+2+2 = 7 — 개수가 같아요.","기준이 다르면 식은 달라도 둘 다 맞아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16},"variant_rule":{"alt":[{"stem":"같은 사각형 배열의 넷째 모양을 준서는 「3+2+2+2」, 민서는 「1+2+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"기준이 달라 식은 달라도 개수가 같아 둘 다 맞아요","correct":true},{"t":"식이 다르니 한 사람은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 많이 쓰인 민서의 식만 맞아요","mis":"M4-1-u6-X09"},{"t":"처음 수가 큰 준서의 식만 맞아요","mis":"M4-1-u6-X12"}],"explanation":["준서는 처음 3개를, 민서는 1개를 변하지 않는 부분으로 봤어요.","3+2+2+2 = 9, 1+2+2+2+2 = 9 — 개수가 같아요.","기준이 다르면 식은 달라도 둘 다 맞아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}},{"stem":"같은 사각형 배열의 다섯째 모양을 민서는 「3+2+2+2+2」, 도윤이는 「1+2+2+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"기준이 달라 식은 달라도 개수가 같아 둘 다 맞아요","correct":true},{"t":"식이 다르니 한 사람은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 많이 쓰인 도윤의 식만 맞아요","mis":"M4-1-u6-X09"},{"t":"처음 수가 큰 민서의 식만 맞아요","mis":"M4-1-u6-X12"}],"explanation":["민서는 처음 3개를, 도윤이는 1개를 변하지 않는 부분으로 봤어요.","3+2+2+2+2 = 11, 1+2+2+2+2+2 = 11 — 개수가 같아요.","기준이 다르면 식은 달라도 둘 다 맞아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_basic#8','math',4,1,'u6','L06','g4_1_math_u6_L06_basic','lesson_basic','M4-1-u6-C12',2,'sa','auto','종이 빨대로 만든 배열의 개수가 첫째부터 3, 9, 18, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u6-C12","difficulty":2,"kind":"sa","stem":"종이 빨대로 만든 배열의 개수가 첫째부터 3, 9, 18, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["30"],"explanation":["늘어난 수는 6, 9 — 3씩 커져요.","다음에 늘어날 수는 9 + 3 = 12예요.","18 + 12 = 30 — 30개예요."],"variant_rule":{"alt":[{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 1, 4, 9, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["16"],"explanation":["늘어난 수는 3, 5 — 2씩 커져요.","다음에 늘어날 수는 5 + 2 = 7이에요.","9 + 7 = 16 — 16개예요."],"asset":null},{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 2, 6, 12, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["20"],"explanation":["늘어난 수는 4, 6 — 2씩 커져요.","다음에 늘어날 수는 6 + 2 = 8이에요.","12 + 8 = 20 — 20개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
