INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_basic#10','math',4,1,'u6','L06','g4_1_math_u6_L06_basic','lesson_basic','M4-1-u6-C12',3,'mc','auto','배열의 개수 「3, 9, 18, 30」에서 늘어나는 수의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X15','M4-1-u6-X08','M4-1-u6-X07']::text[],true,'{"seq":10,"concept":"M4-1-u6-C12","difficulty":3,"kind":"mc","stem":"배열의 개수 「3, 9, 18, 30」에서 늘어나는 수의 규칙은 무엇인가요?","options":[{"t":"늘어나는 수가 6, 9, 12로 3씩 커져요","correct":true},{"t":"늘어나는 수가 항상 6이에요","mis":"M4-1-u6-X15"},{"t":"개수가 3배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"늘어나는 수에는 규칙이 없어요","mis":"M4-1-u6-X07"}],"explanation":["이웃한 두 수의 차를 구해요 — 6, 9, 12.","늘어나는 수가 같지 않고 3씩 커져요.","그래서 늘어나는 수가 6, 9, 12로 3씩 커지는 규칙이에요."],"variant_rule":{"alt":[{"stem":"배열의 개수 「1, 4, 9, 16」에서 늘어나는 수의 규칙은 무엇인가요?","options":[{"t":"늘어나는 수가 3, 5, 7로 2씩 커져요","correct":true},{"t":"늘어나는 수가 항상 3이에요","mis":"M4-1-u6-X15"},{"t":"개수가 4배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"늘어나는 수에는 규칙이 없어요","mis":"M4-1-u6-X07"}],"explanation":["이웃한 두 수의 차를 구해요 — 3, 5, 7.","늘어나는 수가 같지 않고 2씩 커져요.","그래서 늘어나는 수가 3, 5, 7로 2씩 커지는 규칙이에요."],"asset":null},{"stem":"배열의 개수 「2, 6, 12, 20」에서 늘어나는 수의 규칙은 무엇인가요?","options":[{"t":"늘어나는 수가 4, 6, 8로 2씩 커져요","correct":true},{"t":"늘어나는 수가 항상 4예요","mis":"M4-1-u6-X15"},{"t":"개수가 3배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"늘어나는 수에는 규칙이 없어요","mis":"M4-1-u6-X07"}],"explanation":["이웃한 두 수의 차를 구해요 — 4, 6, 8.","늘어나는 수가 같지 않고 2씩 커져요.","그래서 늘어나는 수가 4, 6, 8로 2씩 커지는 규칙이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#1','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C12',2,'mc','auto','개수가 「3, 5, 7, 9」로 늘어나는 사각형 배열이 있어요. 이것과 같은 규칙으로 만든 배열은 어느 것인가요?',ARRAY['M4-1-u6-X14','M4-1-u6-X15']::text[],true,'{"seq":1,"concept":"M4-1-u6-C12","difficulty":2,"kind":"mc","stem":"개수가 「3, 5, 7, 9」로 늘어나는 사각형 배열이 있어요. 이것과 같은 규칙으로 만든 배열은 어느 것인가요?","options":[{"t":"모양은 다르지만 개수가 3, 5, 7, 9인 배열","correct":true},{"t":"모양은 같지만 개수가 3, 6, 9, 12인 배열","mis":"M4-1-u6-X14"},{"t":"모양이 같고 개수가 2, 4, 6, 8인 배열","mis":"M4-1-u6-X14"},{"t":"개수가 3, 5, 8, 12인 배열","mis":"M4-1-u6-X15"}],"explanation":["같은 규칙인지는 개수가 같게 변하는지로 판단해요.","모양이 달라도 개수가 3, 5, 7, 9이면 같은 규칙이에요.","모양이 같아도 개수가 다르게 변하면 다른 규칙이에요."],"variant_rule":{"alt":[{"stem":"개수가 「4, 7, 10, 13」으로 늘어나는 사각형 배열이 있어요. 이것과 같은 규칙으로 만든 배열은 어느 것인가요?","options":[{"t":"모양은 다르지만 개수가 4, 7, 10, 13인 배열","correct":true},{"t":"모양은 같지만 개수가 4, 8, 12, 16인 배열","mis":"M4-1-u6-X14"},{"t":"모양이 같고 개수가 3, 6, 9, 12인 배열","mis":"M4-1-u6-X14"},{"t":"개수가 4, 7, 11, 16인 배열","mis":"M4-1-u6-X15"}],"explanation":["같은 규칙인지는 개수가 같게 변하는지로 판단해요.","모양이 달라도 개수가 4, 7, 10, 13이면 같은 규칙이에요.","모양이 같아도 개수가 다르게 변하면 다른 규칙이에요."],"asset":null},{"stem":"개수가 「5, 9, 13, 17」로 늘어나는 사각형 배열이 있어요. 이것과 같은 규칙으로 만든 배열은 어느 것인가요?","options":[{"t":"모양은 다르지만 개수가 5, 9, 13, 17인 배열","correct":true},{"t":"모양은 같지만 개수가 5, 10, 15, 20인 배열","mis":"M4-1-u6-X14"},{"t":"모양이 같고 개수가 4, 8, 12, 16인 배열","mis":"M4-1-u6-X14"},{"t":"개수가 5, 9, 14, 20인 배열","mis":"M4-1-u6-X15"}],"explanation":["같은 규칙인지는 개수가 같게 변하는지로 판단해요.","모양이 달라도 개수가 5, 9, 13, 17이면 같은 규칙이에요.","모양이 같아도 개수가 다르게 변하면 다른 규칙이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=