INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#3','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C11',3,'sa','auto','사각형 19개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u6-C11","difficulty":3,"kind":"sa","stem":"사각형 19개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.","answer":["9"],"explanation":["첫째 3개에서 2개씩 늘어나요.","19 − 3 = 16, 16 ÷ 2 = 8 — 첫째에서 8번 늘어났어요.","첫째에서 8번 늘어났으니 9째 — 아홉째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형 25개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.","answer":["8"],"explanation":["첫째 4개에서 3개씩 늘어나요.","25 − 4 = 21, 21 ÷ 3 = 7 — 첫째에서 7번 늘어났어요.","첫째에서 7번 늘어났으니 8째 — 여덟째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[1,3],[2,3],[2,4],[1,4]]},{"p":[[0,3],[1,3],[1,4],[0,4]]},{"p":[[2,3],[3,3],[3,4],[2,4]]},{"p":[[1,2],[2,2],[2,3],[1,3]]},{"p":[[7,3],[8,3],[8,4],[7,4]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[5,3],[6,3],[6,4],[5,4]]},{"p":[[8,3],[9,3],[9,4],[8,4]]},{"p":[[9,3],[10,3],[10,4],[9,4]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[15,3],[16,3],[16,4],[15,4]]},{"p":[[14,3],[15,3],[15,4],[14,4]]},{"p":[[13,3],[14,3],[14,4],[13,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[17,3],[18,3],[18,4],[17,4]]},{"p":[[18,3],[19,3],[19,4],[18,4]]},{"p":[[15,2],[16,2],[16,3],[15,3]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,0],[16,0],[16,1],[15,1]]}],"u":16}},{"stem":"사각형 28개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.","answer":["7"],"explanation":["첫째 4개에서 4개씩 늘어나요.","28 − 4 = 24, 24 ÷ 4 = 6 — 첫째에서 6번 늘어났어요.","첫째에서 6번 늘어났으니 7째 — 일곱째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[2,5],[3,5],[3,6],[2,6]]},{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[1,6],[2,6],[2,7],[1,7]]},{"p":[[1,4],[2,4],[2,5],[1,5]]},{"p":[[8,4],[9,4],[9,5],[8,5]]},{"p":[[9,4],[10,4],[10,5],[9,5]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[5,4],[6,4],[6,5],[5,5]]},{"p":[[7,5],[8,5],[8,6],[7,6]]},{"p":[[7,6],[8,6],[8,7],[7,7]]},{"p":[[7,3],[8,3],[8,4],[7,4]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[17,3],[18,3],[18,4],[17,4]]},{"p":[[18,3],[19,3],[19,4],[18,4]]},{"p":[[14,3],[15,3],[15,4],[14,4]]},{"p":[[13,3],[14,3],[14,4],[13,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]},{"p":[[15,4],[16,4],[16,5],[15,5]]},{"p":[[15,5],[16,5],[16,6],[15,6]]},{"p":[[15,6],[16,6],[16,7],[15,7]]},{"p":[[15,2],[16,2],[16,3],[15,3]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,0],[16,0],[16,1],[15,1]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#4','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C12',3,'sa','auto','종이 빨대로 만든 배열의 개수가 첫째부터 1, 3, 6, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u6-C12","difficulty":3,"kind":"sa","stem":"종이 빨대로 만든 배열의 개수가 첫째부터 1, 3, 6, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["10"],"explanation":["늘어난 수는 2, 3 — 1씩 커져요.","다음에 늘어날 수는 3 + 1 = 4예요.","6 + 4 = 10 — 10개예요."],"variant_rule":{"alt":[{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 4, 10, 19, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["31"],"explanation":["늘어난 수는 6, 9 — 3씩 커져요.","다음에 늘어날 수는 9 + 3 = 12예요.","19 + 12 = 31 — 31개예요."],"asset":null},{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 5, 9, 15, ?예요. 늘어나는 수를 살펴 넷째 모양은 몇 개인지 구하세요. 숫자로 쓰세요.","answer":["23"],"explanation":["늘어난 수는 4, 6 — 2씩 커져요.","다음에 늘어날 수는 6 + 2 = 8이에요.","15 + 8 = 23 — 23개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#5','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C11',3,'mc','auto','사각형 배열에서 왼쪽 세로 3개를 변하지 않는 부분으로 보았어요. 셋째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.',ARRAY['M4-1-u6-X13','M4-1-u6-X12','M4-1-u6-X11']::text[],true,'{"seq":5,"concept":"M4-1-u6-C11","difficulty":3,"kind":"mc","stem":"사각형 배열에서 왼쪽 세로 3개를 변하지 않는 부분으로 보았어요. 셋째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"3+2+2","correct":true},{"t":"3+2+2+2","mis":"M4-1-u6-X13"},{"t":"1+2+2","mis":"M4-1-u6-X12"},{"t":"3+3+3","mis":"M4-1-u6-X11"}],"explanation":["왼쪽 세로 3개를 그대로 두고 나머지를 2개씩 묶어요.","셋째 모양은 7개 = 3+2+2.","기준이 달라지면 식은 달라도 개수는 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형 배열에서 왼쪽 위 1개를 변하지 않는 부분으로 보았어요. 넷째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"1+2+2+2+2","correct":true},{"t":"1+2+2+2","mis":"M4-1-u6-X13"},{"t":"3+2+2+2+2","mis":"M4-1-u6-X12"},{"t":"1+3+3+3+3","mis":"M4-1-u6-X11"}],"explanation":["왼쪽 위 1개를 그대로 두고 나머지를 2개씩 묶어요.","넷째 모양은 9개 = 1+2+2+2+2.","기준이 달라지면 식은 달라도 개수는 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}},{"stem":"사각형 배열에서 왼쪽 세로 3개를 변하지 않는 부분으로 보았어요. 다섯째 모양의 사각형 수를 나타낸 식은 어느 것인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"3+2+2+2+2","correct":true},{"t":"3+2+2+2+2+2","mis":"M4-1-u6-X13"},{"t":"1+2+2+2+2","mis":"M4-1-u6-X12"},{"t":"3+3+3+3+3","mis":"M4-1-u6-X11"}],"explanation":["왼쪽 세로 3개를 그대로 두고 나머지를 2개씩 묶어요.","다섯째 모양은 11개 = 3+2+2+2+2.","기준이 달라지면 식은 달라도 개수는 같아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#6','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C12',3,'mc','auto','배열의 개수 「1, 3, 6, 10」에서 늘어나는 수의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X15','M4-1-u6-X08','M4-1-u6-X07']::text[],true,'{"seq":6,"concept":"M4-1-u6-C12","difficulty":3,"kind":"mc","stem":"배열의 개수 「1, 3, 6, 10」에서 늘어나는 수의 규칙은 무엇인가요?","options":[{"t":"늘어나는 수가 2, 3, 4로 1씩 커져요","correct":true},{"t":"늘어나는 수가 항상 2예요","mis":"M4-1-u6-X15"},{"t":"개수가 3배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"늘어나는 수에는 규칙이 없어요","mis":"M4-1-u6-X07"}],"explanation":["이웃한 두 수의 차를 구해요 — 2, 3, 4.","늘어나는 수가 같지 않고 1씩 커져요.","그래서 늘어나는 수가 2, 3, 4로 1씩 커지는 규칙이에요."],"variant_rule":{"alt":[{"stem":"배열의 개수 「4, 10, 19, 31」에서 늘어나는 수의 규칙은 무엇인가요?","options":[{"t":"늘어나는 수가 6, 9, 12로 3씩 커져요","correct":true},{"t":"늘어나는 수가 항상 6이에요","mis":"M4-1-u6-X15"},{"t":"개수가 2배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"늘어나는 수에는 규칙이 없어요","mis":"M4-1-u6-X07"}],"explanation":["이웃한 두 수의 차를 구해요 — 6, 9, 12.","늘어나는 수가 같지 않고 3씩 커져요.","그래서 늘어나는 수가 6, 9, 12로 3씩 커지는 규칙이에요."],"asset":null},{"stem":"배열의 개수 「5, 9, 15, 23」에서 늘어나는 수의 규칙은 무엇인가요?","options":[{"t":"늘어나는 수가 4, 6, 8로 2씩 커져요","correct":true},{"t":"늘어나는 수가 항상 4예요","mis":"M4-1-u6-X15"},{"t":"개수가 2배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"늘어나는 수에는 규칙이 없어요","mis":"M4-1-u6-X07"}],"explanation":["이웃한 두 수의 차를 구해요 — 4, 6, 8.","늘어나는 수가 같지 않고 2씩 커져요.","그래서 늘어나는 수가 4, 6, 8로 2씩 커지는 규칙이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#7','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C11',3,'mc','auto','같은 사각형 배열의 셋째 모양을 도윤이는 「3+2+2」, 서윤이는 「1+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?',ARRAY['M4-1-u6-X09','M4-1-u6-X12']::text[],true,'{"seq":7,"concept":"M4-1-u6-C11","difficulty":3,"kind":"mc","stem":"같은 사각형 배열의 셋째 모양을 도윤이는 「3+2+2」, 서윤이는 「1+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"기준이 달라 식은 달라도 개수가 같아 둘 다 맞아요","correct":true},{"t":"식이 다르니 한 사람은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 많이 쓰인 서윤의 식만 맞아요","mis":"M4-1-u6-X09"},{"t":"처음 수가 큰 도윤의 식만 맞아요","mis":"M4-1-u6-X12"}],"explanation":["도윤이는 처음 3개를, 서윤이는 1개를 변하지 않는 부분으로 봤어요.","3+2+2 = 7, 1+2+2+2 = 7 — 개수가 같아요.","기준이 다르면 식은 달라도 둘 다 맞아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16},"variant_rule":{"alt":[{"stem":"같은 사각형 배열의 넷째 모양을 서윤이는 「3+2+2+2」, 시우는 「1+2+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"기준이 달라 식은 달라도 개수가 같아 둘 다 맞아요","correct":true},{"t":"식이 다르니 한 사람은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 많이 쓰인 시우의 식만 맞아요","mis":"M4-1-u6-X09"},{"t":"처음 수가 큰 서윤의 식만 맞아요","mis":"M4-1-u6-X12"}],"explanation":["서윤이는 처음 3개를, 시우는 1개를 변하지 않는 부분으로 봤어요.","3+2+2+2 = 9, 1+2+2+2+2 = 9 — 개수가 같아요.","기준이 다르면 식은 달라도 둘 다 맞아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}},{"stem":"같은 사각형 배열의 다섯째 모양을 시우는 「3+2+2+2+2」, 은우는 「1+2+2+2+2+2」로 나타냈어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"기준이 달라 식은 달라도 개수가 같아 둘 다 맞아요","correct":true},{"t":"식이 다르니 한 사람은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 많이 쓰인 은우의 식만 맞아요","mis":"M4-1-u6-X09"},{"t":"처음 수가 큰 시우의 식만 맞아요","mis":"M4-1-u6-X12"}],"explanation":["시우는 처음 3개를, 은우는 1개를 변하지 않는 부분으로 봤어요.","3+2+2+2+2 = 11, 1+2+2+2+2+2 = 11 — 개수가 같아요.","기준이 다르면 식은 달라도 둘 다 맞아요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#8','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C11',4,'sa','auto','사각형 23개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u6-C11","difficulty":4,"kind":"sa","stem":"사각형 23개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.","answer":["11"],"explanation":["첫째 3개에서 2개씩 늘어나요.","23 − 3 = 20, 20 ÷ 2 = 10 — 첫째에서 10번 늘어났어요.","첫째에서 10번 늘어났으니 11째 — 열한째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,3],[1,3],[1,4],[0,4]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[1,3],[2,3],[2,4],[1,4]]},{"p":[[4,3],[5,3],[5,4],[4,4]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[5,3],[6,3],[6,4],[5,4]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[9,3],[10,3],[10,4],[9,4]]},{"p":[[9,2],[10,2],[10,3],[9,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,0],[10,0],[10,1],[9,1]]},{"p":[[10,3],[11,3],[11,4],[10,4]]},{"p":[[11,3],[12,3],[12,4],[11,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형 41개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.","answer":["10"],"explanation":["첫째 5개에서 4개씩 늘어나요.","41 − 5 = 36, 36 ÷ 4 = 9 — 첫째에서 9번 늘어났어요.","첫째에서 9번 늘어났으니 10째 — 열째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[1,5],[2,5],[2,6],[1,6]]},{"p":[[2,5],[3,5],[3,6],[2,6]]},{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[1,6],[2,6],[2,7],[1,7]]},{"p":[[1,4],[2,4],[2,5],[1,5]]},{"p":[[7,4],[8,4],[8,5],[7,5]]},{"p":[[8,4],[9,4],[9,5],[8,5]]},{"p":[[9,4],[10,4],[10,5],[9,5]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[5,4],[6,4],[6,5],[5,5]]},{"p":[[7,5],[8,5],[8,6],[7,6]]},{"p":[[7,6],[8,6],[8,7],[7,7]]},{"p":[[7,3],[8,3],[8,4],[7,4]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[15,3],[16,3],[16,4],[15,4]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[17,3],[18,3],[18,4],[17,4]]},{"p":[[18,3],[19,3],[19,4],[18,4]]},{"p":[[14,3],[15,3],[15,4],[14,4]]},{"p":[[13,3],[14,3],[14,4],[13,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]},{"p":[[15,4],[16,4],[16,5],[15,5]]},{"p":[[15,5],[16,5],[16,6],[15,6]]},{"p":[[15,6],[16,6],[16,7],[15,7]]},{"p":[[15,2],[16,2],[16,3],[15,3]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,0],[16,0],[16,1],[15,1]]}],"u":16}},{"stem":"사각형 25개로 만든 모양은 몇째 모양인가요? 몇째인지 수로 쓰세요(예: 다섯째 → 5). 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요. 숫자로 쓰세요.","answer":["12"],"explanation":["첫째 3개에서 2개씩 늘어나요.","25 − 3 = 22, 22 ÷ 2 = 11 — 첫째에서 11번 늘어났어요.","첫째에서 11번 늘어났으니 12째 — 열두째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#9','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C12',4,'sa','auto','종이 빨대로 만든 배열의 개수가 첫째부터 2, 6, 12, 20…로 늘어나요. 이렇게 계속 늘어나면 다섯째 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u6-C12","difficulty":4,"kind":"sa","stem":"종이 빨대로 만든 배열의 개수가 첫째부터 2, 6, 12, 20…로 늘어나요. 이렇게 계속 늘어나면 다섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["늘어난 수는 4, 6, 8 — 2씩 커져요.","이어서 10만큼 늘어나요.","다섯째 모양은 30개예요."],"variant_rule":{"alt":[{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 1, 3, 6, 10…로 늘어나요. 이렇게 계속 늘어나면 여섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["늘어난 수는 2, 3, 4 — 1씩 커져요.","이어서 5, 6만큼 늘어나요.","여섯째 모양은 21개예요."],"asset":null},{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 4, 10, 19, 31…로 늘어나요. 이렇게 계속 늘어나면 다섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["46"],"explanation":["늘어난 수는 6, 9, 12 — 3씩 커져요.","이어서 15만큼 늘어나요.","다섯째 모양은 46개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L06_challenge#10','math',4,1,'u6','L06','g4_1_math_u6_L06_challenge','lesson_challenge','M4-1-u6-C12',4,'essay','teacher','종이 빨대 배열의 개수가 첫째부터 3, 9, 18, 30이에요. 한 친구는 「처음에 6개 늘었으니 다섯째는 36개야.」라고 했어요. 이 친구의 생각이 맞는지 판단하고, 다섯째 모양의 개수를 바르게 구하는 과정을 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u6-C12","difficulty":4,"kind":"essay","stem":"종이 빨대 배열의 개수가 첫째부터 3, 9, 18, 30이에요. 한 친구는 「처음에 6개 늘었으니 다섯째는 36개야.」라고 했어요. 이 친구의 생각이 맞는지 판단하고, 다섯째 모양의 개수를 바르게 구하는 과정을 써 보세요.","answer_guide":{"answer":"예: 틀렸다. 늘어나는 수가 6, 9, 12로 3씩 커지므로 늘어나는 수가 늘 6인 것이 아니다. 다음에는 12+3=15개가 늘어나므로 다섯째는 30+15=45개이다.","scoring_points":["친구의 생각이 틀렸다고 판단했는가","늘어나는 수가 6, 9, 12로 3씩 커진다고 썼는가","다섯째를 30+15=45개로 구했는가"]},"explanation":["늘어나는 수: 6, 9, 12 — 3씩 커져요.","다음 늘어날 수: 15.","다섯째 = 30 + 15 = 45개."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#1','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',1,'mc','auto','곱셈식 배열의 규칙으로 보아 다섯째 식 「1222221×4」의 결과는 어느 것인가요?',ARRAY['M4-1-u6-X16','M4-1-u6-X07']::text[],true,'{"seq":1,"concept":"M4-1-u6-C13","difficulty":1,"kind":"mc","stem":"곱셈식 배열의 규칙으로 보아 다섯째 식 「1222221×4」의 결과는 어느 것인가요?","options":[{"t":"4888884","correct":true},{"t":"488884","mis":"M4-1-u6-X16"},{"t":"48888884","mis":"M4-1-u6-X16"},{"t":"444484","mis":"M4-1-u6-X07"}],"explanation":["곱해지는 수는 1과 1 사이에 2가 1개씩 늘어나요.","결과는 4와 4 사이에 8이 1개씩 늘어나요 — 다섯째 식은 8이 5개예요.","그래서 1222221×4 = 4888884 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"],["넷째","122221×4","=","488884"]]},"variant_rule":{"alt":[{"stem":"곱셈식 배열의 규칙으로 보아 다섯째 식 「1222221×3」의 결과는 어느 것인가요?","options":[{"t":"3666663","correct":true},{"t":"366663","mis":"M4-1-u6-X16"},{"t":"36666663","mis":"M4-1-u6-X16"},{"t":"333363","mis":"M4-1-u6-X07"}],"explanation":["곱해지는 수는 1과 1 사이에 2가 1개씩 늘어나요.","결과는 3과 3 사이에 6이 1개씩 늘어나요 — 다섯째 식은 6이 5개예요.","그래서 1222221×3 = 3666663 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","121×3","=","363"],["둘째","1221×3","=","3663"],["셋째","12221×3","=","36663"],["넷째","122221×3","=","366663"]]}},{"stem":"곱셈식 배열의 규칙으로 보아 다섯째 식 「1222221×2」의 결과는 어느 것인가요?","options":[{"t":"2444442","correct":true},{"t":"244442","mis":"M4-1-u6-X16"},{"t":"24444442","mis":"M4-1-u6-X16"},{"t":"222242","mis":"M4-1-u6-X07"}],"explanation":["곱해지는 수는 1과 1 사이에 2가 1개씩 늘어나요.","결과는 2와 2 사이에 4가 1개씩 늘어나요 — 다섯째 식은 4가 5개예요.","그래서 1222221×2 = 2444442 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","121×2","=","242"],["둘째","1221×2","=","2442"],["셋째","12221×2","=","24442"],["넷째","122221×2","=","244442"]]}}]}}'::jsonb) ON CONFLICT (qcode)