INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#2','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',1,'mc','auto','곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X08','M4-1-u6-X07','M4-1-u6-X17']::text[],true,'{"seq":2,"concept":"M4-1-u6-C13","difficulty":1,"kind":"mc","stem":"곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"4와 4 사이에 8이 1개씩 늘어나요","correct":true},{"t":"결과가 4배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 4400씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 484, 4884, 48884, 488884.","4와 4 사이의 8이 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"],["넷째","122221×4","=","488884"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"3과 3 사이에 6이 1개씩 늘어나요","correct":true},{"t":"결과가 3배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 3300씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 363, 3663, 36663, 366663.","3과 3 사이의 6이 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×3","=","363"],["둘째","1221×3","=","3663"],["셋째","12221×3","=","36663"],["넷째","122221×3","=","366663"]]}},{"stem":"이번에는 다른 그림이에요. 곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"2와 2 사이에 4가 1개씩 늘어나요","correct":true},{"t":"결과가 2배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 2200씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 242, 2442, 24442, 244442.","2와 2 사이의 4가 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×2","=","242"],["둘째","1221×2","=","2442"],["셋째","12221×2","=","24442"],["넷째","122221×2","=","244442"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#3','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',1,'sa','auto','나눗셈식 배열의 규칙으로 보아 다섯째 식 「5555÷55」의 결과는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u6-C13","difficulty":1,"kind":"sa","stem":"나눗셈식 배열의 규칙으로 보아 다섯째 식 「5555÷55」의 결과는 얼마인가요? 숫자로 쓰세요.","answer":["101"],"explanation":["나누어지는 수와 나누는 수가 똑같이 2배, 3배…로 커져요.","그래서 결과는 늘 101로 같아요.","다섯째 식도 5555÷55 = 101 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","1111÷11","=","101"],["둘째","2222÷22","=","101"],["셋째","3333÷33","=","101"],["넷째","4444÷44","=","101"]]},"variant_rule":{"alt":[{"stem":"나눗셈식 배열의 규칙으로 보아 다섯째 식 「555÷15」의 결과는 얼마인가요? 숫자로 쓰세요.","answer":["37"],"explanation":["나누어지는 수와 나누는 수가 똑같이 2배, 3배…로 커져요.","그래서 결과는 늘 37로 같아요.","다섯째 식도 555÷15 = 37 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","111÷3","=","37"],["둘째","222÷6","=","37"],["셋째","333÷9","=","37"],["넷째","444÷12","=","37"]]}},{"stem":"나눗셈식 배열의 규칙으로 보아 여섯째 식 「6666÷66」의 결과는 얼마인가요? 숫자로 쓰세요.","answer":["101"],"explanation":["나누어지는 수와 나누는 수가 똑같이 2배, 3배…로 커져요.","그래서 결과는 늘 101로 같아요.","여섯째 식도 6666÷66 = 101 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","1111÷11","=","101"],["둘째","2222÷22","=","101"],["셋째","3333÷33","=","101"],["넷째","4444÷44","=","101"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#4','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',1,'mc','auto','시우가 「1222221×4」를 만났어요. 이 단원에서 배운 가장 좋은 방법은 어느 것인가요?',ARRAY['M4-1-u6-X18']::text[],true,'{"seq":4,"concept":"M4-1-u6-C13","difficulty":1,"kind":"mc","stem":"시우가 「1222221×4」를 만났어요. 이 단원에서 배운 가장 좋은 방법은 어느 것인가요?","options":[{"t":"배열의 규칙으로 결과를 추측하고 계산기로 확인해요.","correct":true},{"t":"규칙은 보지 않고 무조건 세로셈으로 직접 계산해요.","mis":"M4-1-u6-X18"},{"t":"너무 크니까 아무 수나 쓰고 넘어가요.","mis":"M4-1-u6-X18"},{"t":"규칙으로 추측만 하고 확인은 하지 않아요.","mis":"M4-1-u6-X18"}],"explanation":["계산식의 배열은 큰 수를 직접 계산하는 것이 목표가 아니에요.","먼저 규칙을 찾고, 규칙으로 결과를 추측해요.","추측한 결과는 계산기로 확인해요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"]]},"variant_rule":{"alt":[{"stem":"계산식의 배열을 공부하는 순서로 알맞은 것은 어느 것인가요?","options":[{"t":"규칙 찾기 → 결과 추측 → 계산기로 확인","correct":true},{"t":"계산기로 결과 확인 → 규칙 찾기 → 결과 추측","mis":"M4-1-u6-X18"},{"t":"결과 추측 → 확인 없이 끝내기","mis":"M4-1-u6-X18"},{"t":"처음 식 하나만 보고 결과 쓰기","mis":"M4-1-u6-X07"}],"explanation":["계산식의 배열은 큰 수를 직접 계산하는 것이 목표가 아니에요.","먼저 규칙을 찾고, 규칙으로 결과를 추측해요.","추측한 결과는 계산기로 확인해요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"]]}},{"stem":"「12221×4」의 결과를 알아보려고 해요. 알맞은 방법은 어느 것인가요?","options":[{"t":"앞의 식들에서 규칙을 찾아 추측하고 계산기로 확인해요.","correct":true},{"t":"규칙은 보지 않고 무조건 세로셈으로 직접 계산해요.","mis":"M4-1-u6-X18"},{"t":"너무 크니까 아무 수나 쓰고 넘어가요.","mis":"M4-1-u6-X18"},{"t":"규칙으로 추측만 하고 확인은 하지 않아요.","mis":"M4-1-u6-X18"}],"explanation":["계산식의 배열은 큰 수를 직접 계산하는 것이 목표가 아니에요.","먼저 규칙을 찾고, 규칙으로 결과를 추측해요.","추측한 결과는 계산기로 확인해요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE 