INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#5','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',2,'mc','auto','뺄셈식 배열 100−1, 101−2, 102−3…에서 계산 결과가 늘 99인 까닭은 무엇인가요?',ARRAY['M4-1-u6-X07','M4-1-u6-X18','M4-1-u6-X17']::text[],true,'{"seq":5,"concept":"M4-1-u6-C13","difficulty":2,"kind":"mc","stem":"뺄셈식 배열 100−1, 101−2, 102−3…에서 계산 결과가 늘 99인 까닭은 무엇인가요?","options":[{"t":"빼어지는 수와 빼는 수가 똑같이 1씩 커져서","correct":true},{"t":"빼는 수가 항상 1이라서","mis":"M4-1-u6-X07"},{"t":"100에서 시작해서 우연히 그런 것이라서","mis":"M4-1-u6-X18"},{"t":"빼어지는 수만 1씩 커져서","mis":"M4-1-u6-X17"}],"explanation":["빼어지는 수는 100, 101, 102…로 1씩 커져요.","빼는 수도 1, 2, 3…으로 1씩 커져요.","둘이 똑같이 커지면 차는 그대로 — 늘 99예요."],"asset":{"type":"expr_grid","rows":[["첫째","100−1","=","99"],["둘째","101−2","=","99"],["셋째","102−3","=","99"],["넷째","103−4","=","99"]]},"variant_rule":{"alt":[{"stem":"뺄셈식 배열 200−1, 201−2, 202−3…에서 계산 결과가 늘 199인 까닭은 무엇인가요?","options":[{"t":"빼어지는 수와 빼는 수가 똑같이 1씩 커져서","correct":true},{"t":"빼는 수가 항상 1이라서","mis":"M4-1-u6-X07"},{"t":"200에서 시작해서 우연히 그런 것이라서","mis":"M4-1-u6-X18"},{"t":"빼어지는 수만 1씩 커져서","mis":"M4-1-u6-X17"}],"explanation":["빼어지는 수는 200, 201, 202…로 1씩 커져요.","빼는 수도 1, 2, 3…으로 1씩 커져요.","둘이 똑같이 커지면 차는 그대로 — 늘 199예요."],"asset":{"type":"expr_grid","rows":[["첫째","200−1","=","199"],["둘째","201−2","=","199"],["셋째","202−3","=","199"],["넷째","203−4","=","199"]]}},{"stem":"뺄셈식 배열 50−1, 51−2, 52−3…에서 계산 결과가 늘 49인 까닭은 무엇인가요?","options":[{"t":"빼어지는 수와 빼는 수가 똑같이 1씩 커져서","correct":true},{"t":"빼는 수가 항상 1이라서","mis":"M4-1-u6-X07"},{"t":"50에서 시작해서 우연히 그런 것이라서","mis":"M4-1-u6-X18"},{"t":"빼어지는 수만 1씩 커져서","mis":"M4-1-u6-X17"}],"explanation":["빼어지는 수는 50, 51, 52…로 1씩 커져요.","빼는 수도 1, 2, 3…으로 1씩 커져요.","둘이 똑같이 커지면 차는 그대로 — 늘 49예요."],"asset":{"type":"expr_grid","rows":[["첫째","50−1","=","49"],["둘째","51−2","=","49"],["셋째","52−3","=","49"],["넷째","53−4","=