INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#6','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',2,'mc','auto','뺄셈식 배열의 다섯째 식으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X17','M4-1-u6-X13']::text[],true,'{"seq":6,"concept":"M4-1-u6-C13","difficulty":2,"kind":"mc","stem":"뺄셈식 배열의 다섯째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"104−5=99","correct":true},{"t":"105−5=100","mis":"M4-1-u6-X17"},{"t":"104−4=100","mis":"M4-1-u6-X17"},{"t":"105−6=99","mis":"M4-1-u6-X13"}],"explanation":["빼어지는 수와 빼는 수가 1씩 커지고 결과는 늘 99예요.","다섯째 식의 빼는 수는 5, 빼어지는 수는 104예요.","그래서 「104−5=99」예요 — 계산은 맞아도 배열의 규칙과 다른 식은 답이 아니에요."],"asset":{"type":"expr_grid","rows":[["첫째","100−1","=","99"],["둘째","101−2","=","99"],["셋째","102−3","=","99"],["넷째","103−4","=","99"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 뺄셈식 배열의 다섯째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"204−5=199","correct":true},{"t":"205−5=200","mis":"M4-1-u6-X17"},{"t":"204−4=200","mis":"M4-1-u6-X17"},{"t":"205−6=199","mis":"M4-1-u6-X13"}],"explanation":["빼어지는 수와 빼는 수가 1씩 커지고 결과는 늘 199예요.","다섯째 식의 빼는 수는 5, 빼어지는 수는 204예요.","그래서 「204−5=199」예요 — 계산은 맞아도 배열의 규칙과 다른 식은 답이 아니에요."],"asset":{"type":"expr_grid","rows":[["첫째","200−1","=","199"],["둘째","201−2","=","199"],["셋째","202−3","=","199"],["넷째","203−4","=","199"]]}},{"stem":"이번에는 다른 그림이에요. 뺄셈식 배열의 다섯째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"54−5=49","correct":true},{"t":"55−5=50","mis":"M4-1-u6-X17"},{"t":"54−4=50","mis":"M4-1-u6-X17"},{"t":"55−6=49","mis":"M4-1-u6-X13"}],"explanation":["빼어지는 수와 빼는 수가 1씩 커지고 결과는 늘 49예요.","다섯째 식의 빼는 수는 5, 빼어지는 수는 54예요.","그래서 「54−5=49」예요 — 계산은 맞아도 배열의 규칙과 다른 식은 답이 아니에요."],"asset":{"type":"expr_grid","rows":[["첫째","50−1","=","49"],["둘째","51−2","=","49"],["셋째","52−3","=","49"],["넷째","53−4","=","49"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#7','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',2,'mc','auto','나눗셈식 배열의 규칙을 바르게 말한 것은 어느 것인가요?',ARRAY['M4-1-u6-X17','M4-1-u6-X07']::text[],true,'{"seq":7,"concept":"M4-1-u6-C13","difficulty":2,"kind":"mc","stem":"나눗셈식 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"나누어지는 수와 나누는 수가 똑같이 커져서 결과는 늘 101이에요","correct":true},{"t":"결과도 2배, 3배…로 커져요","mis":"M4-1-u6-X17"},{"t":"결과가 1씩 커져요","mis":"M4-1-u6-X17"},{"t":"나누는 수만 커지고 나누어지는 수는 그대로예요","mis":"M4-1-u6-X07"}],"explanation":["나누어지는 수: 1111, 2222, 3333, 4444.","나누는 수: 11, 22, 33, 44 — 둘 다 똑같이 2배, 3배, 4배.","그래서 결과는 커지지 않고 늘 101이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1111÷11","=","101"],["둘째","2222÷22","=","101"],["셋째","3333÷33","=","101"],["넷째","4444÷44","=","101"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 나눗셈식 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"나누어지는 수와 나누는 수가 똑같이 커져서 결과는 늘 37이에요","correct":true},{"t":"결과도 2배, 3배…로 커져요","mis":"M4-1-u6-X17"},{"t":"결과가 1씩 커져요","mis":"M4-1-u6-X17"},{"t":"나누는 수만 커지고 나누어지는 수는 그대로예요","mis":"M4-1-u6-X07"}],"explanation":["나누어지는 수: 111, 222, 333, 444.","나누는 수: 3, 6, 9, 12 — 둘 다 똑같이 2배, 3배, 4배.","그래서 결과는 커지지 않고 늘 37이에요."],"asset":{"type":"expr_grid","rows":[["첫째","111÷3","=","37"],["둘째","222÷6","=","37"],["셋째","333÷9","=","37"],["넷째","444÷12","=","37"]]}},{"stem":"이번에는 다른 그림이에요. 나눗셈식 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"나누어지는 수와 나누는 수가 똑같이 커져서 결과는 늘 101이에요","correct":true},{"t":"결과도 2배, 3배…로 커져요","mis":"M4-1-u6-X17"},{"t":"결과가 1씩 커져요","mis":"M4-1-u6-X17"},{"t":"나누는 수만 커지고 나누어지는 수는 그대로예요","mis":"M4-1-u6-X07"}],"explanation":["나누어지는 수: 1111, 2222, 3333, 4444.","나누는 수: 11, 22, 33, 44 — 둘 다 똑같이 2배, 3배, 4배.","그래서 결과는 커지지 않고 늘 101이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1111÷11","=","101"],["둘째","2222÷22","=","101"],["셋째","3333÷33","=","101"],["넷째","4444÷44","=","101"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#8','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',2,'sa','auto','뺄셈식 배열의 여덟째 식은 「□−8=99」예요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u6-C13","difficulty":2,"kind":"sa","stem":"뺄셈식 배열의 여덟째 식은 「□−8=99」예요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["107"],"explanation":["빼어지는 수는 100, 101, 102…로 99에 몇째를 더한 수예요.","여덟째는 99 + 8 = 107이에요.","확인: 107 − 8 = 99."],"asset":{"type":"expr_grid","rows":[["첫째","100−1","=","99"],["둘째","101−2","=","99"],["셋째","102−3","=","99"],["넷째","103−4","=","99"]]},"variant_rule":{"alt":[{"stem":"뺄셈식 배열의 일곱째 식은 「□−7=99」예요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["106"],"explanation":["빼어지는 수는 100, 101, 102…로 99에 몇째를 더한 수예요.","일곱째는 99 + 7 = 106이에요.","확인: 106 − 7 = 99."],"asset":{"type":"expr_grid","rows":[["첫째","100−1","=","99"],["둘째","101−2","=","99"],["셋째","102−3","=","99"],["넷째","103−4","=","99"]]}},{"stem":"뺄셈식 배열의 아홉째 식은 「□−9=99」예요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["108"],"explanation":["빼어지는 수는 100, 101, 102…로 99에 몇째를 더한 수예요.","아홉째는 99 + 9 = 108이에요.","확인: 108 − 9 = 99."],"asset":{"type":"expr_grid","rows":[["첫째","100−1","=","99"],["둘째","101−2","=","99"],["셋째","102−3","=","99"],["넷째","103−4","=","99"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_basic#9','math',4,1,'u6','L07','g4_1_math_u6_L07_basic','lesson_basic','M4-1-u6-C13',2,'mc','auto','「9999÷99=101」은 나눗셈식 배열의 몇째 식인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X16']::text[],true,'{"seq":9,"concept":"M4-1-u6-C13","difficulty":2,"kind":"mc","stem":"「9999÷99=101」은 나눗셈식 배열의 몇째 식인가요?","options":[{"t":"아홉째","correct":true},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"열째","mis":"M4-1-u6-X13"},{"t":"넷째","mis":"M4-1-u6-X16"}],"explanation":["첫째 식은 1111÷11, 둘째 식은 2222÷22예요.","9999는 1111의 9배예요.","그래서 아홉째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1111÷11","=","101"],["둘째","2222÷22","=","101"]]},"variant_rule":{"alt":[{"stem":"「666÷18=37」은 나눗셈식 배열의 몇째 식인가요?","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"셋째","mis":"M4-1-u6-X16"}],"explanation":["첫째 식은 111÷3, 둘째 식은 222÷6이에요.","666은 111의 6배예요.","그래서 여섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","111÷3","=","37"],["둘째","222÷6","=","37"]]}},{"stem":"「8888÷88=101」은 나눗셈식 배열의 몇째 식인가요?","options":[{"t":"여덟째","correct":true},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"아홉째","mis":"M4-1-u6-X13"},{"t":"넷째","mis":"M4-1-u6-X16"}],"explanation":["첫째 식은 1111÷11, 둘째 식은 2222÷22예요.","8888은 1111의 8배예요.","그래서 여덟째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1111÷11","=","101"],["둘째","2222÷22","=","101"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
