INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_challenge#9','math',4,1,'u6','L07','g4_1_math_u6_L07_challenge','lesson_challenge','M4-1-u6-C13',4,'sa','auto','뺄셈식 배열에서 결과가 161이 되는 식의 빼는 수는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u6-C13","difficulty":4,"kind":"sa","stem":"뺄셈식 배열에서 결과가 161이 되는 식의 빼는 수는 얼마인가요? 숫자로 쓰세요.","answer":["622"],"explanation":["빼는 수는 22부터 100씩 커지고 결과는 761부터 100씩 작아져요.","결과 161은 일곱째 식이에요.","일곱째 식의 빼는 수는 622 — 783 − 622 = 161."],"asset":{"type":"expr_grid","rows":[["첫째","783−22","=","761"],["둘째","783−122","=","661"],["셋째","783−222","=","561"]]},"variant_rule":{"alt":[{"stem":"뺄셈식 배열에서 결과가 434가 되는 식의 빼는 수는 얼마인가요? 숫자로 쓰세요.","answer":["531"],"explanation":["빼는 수는 31부터 100씩 커지고 결과는 934부터 100씩 작아져요.","결과 434는 여섯째 식이에요.","여섯째 식의 빼는 수는 531 — 965 − 531 = 434."],"asset":{"type":"expr_grid","rows":[["첫째","965−31","=","934"],["둘째","965−131","=","834"],["셋째","965−231","=","734"]]}},{"stem":"뺄셈식 배열에서 결과가 431이 되는 식의 빼는 수는 얼마인가요? 숫자로 쓰세요.","answer":["443"],"explanation":["빼는 수는 43부터 100씩 커지고 결과는 831부터 100씩 작아져요.","결과 431은 다섯째 식이에요.","다섯째 식의 빼는 수는 443 — 874 − 443 = 431."],"asset":{"type":"expr_grid","rows":[["첫째","874−43","=","831"],["둘째","874−143","=","731"],["셋째","874−243","=","631"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L07_challenge#10','math',4,1,'u6','L07','g4_1_math_u6_L07_challenge','lesson_challenge','M4-1-u6-C13',4,'essay','teacher','곱셈식 배열 「121×4=484, 1221×4=4884, 12221×4=48884, 122221×4=488884」를 보고 다섯째 식 「1222221×4」의 결과를 계산하지 않고 구하려고 해요. 찾은 규칙과 추측한 결과를 쓰고, 추측이 맞는지 어떻게 확인하는지도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u6-C13","difficulty":4,"kind":"essay","stem":"곱셈식 배열 「121×4=484, 1221×4=4884, 12221×4=48884, 122221×4=488884」를 보고 다섯째 식 「1222221×4」의 결과를 계산하지 않고 구하려고 해요. 찾은 규칙과 추측한 결과를 쓰고, 추측이 맞는지 어떻게 확인하는지도 써 보세요.","answer_guide":{"answer":"예: 곱해지는 수는 1과 1 사이에 2가 1개씩 늘고, 결과는 4와 4 사이에 8이 1개씩 늘어난다. 다섯째는 8이 5개이므로 4888884라고 추측한다. 계산기로 1222221×4를 눌러 4888884가 나오는지 확인한다.","scoring_points":["곱해지는 수와 결과의 규칙(2·8이 1개씩)을 썼는가","4888884로 추측했는가","계산기로 확인한다고 썼는가"]},"explanation":["결과: 484 → 4884 → 48884 → 488884.","다섯째는 8이 5개 — 4888884.","추측은 계산기로 확인해요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"],["넷째","122221×4","=","488884"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#1','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',1,'mc','auto','덧셈식 배열의 여섯째 식으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X15']::text[],true,'{"seq":1,"concept":"M4-1-u6-C14","difficulty":1,"kind":"mc","stem":"덧셈식 배열의 여섯째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"11+13=24","correct":true},{"t":"9+11=20","mis":"M4-1-u6-X13"},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"11+12=23","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","여섯째 식의 더해지는 수는 11, 더하는 수는 13이에요.","그래서 「11+13=24」예요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 여섯째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"13+15=28","correct":true},{"t":"11+13=24","mis":"M4-1-u6-X13"},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"13+14=27","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","여섯째 식의 더해지는 수는 13, 더하는 수는 15예요.","그래서 「13+15=28」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"],["다섯째","11+13","=","24"]]}},{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 여섯째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","여섯째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"],["다섯째","13+15","=","28"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#2','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',1,'mc','auto','덧셈식 배열에서 계산 결과의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X15','M4-1-u6-X17','M4-1-u6-X08']::text[],true,'{"seq":2,"concept":"M4-1-u6-C14","difficulty":1,"kind":"mc","stem":"덧셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"결과가 4씩 커져요","correct":true},{"t":"결과가 2씩 커져요","mis":"M4-1-u6-X15"},{"t":"결과가 늘 같아요","mis":"M4-1-u6-X17"},{"t":"결과가 2배씩 커져요","mis":"M4-1-u6-X08"}],"explanation":["결과: 4, 8, 12, 16, 20.","더하는 두 수가 각각 2씩 커지니 합은 2 + 2 = 4씩 커져요.","그래서 결과는 4씩 커지는 규칙이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"결과가 4씩 커져요","correct":true},{"t":"결과가 2씩 커져요","mis":"M4-1-u6-X15"},{"t":"결과가 늘 같아요","mis":"M4-1-u6-X17"},{"t":"결과가 2배씩 커져요","mis":"M4-1-u6-X08"}],"explanation":["결과: 8, 12, 16, 20, 24.","더하는 두 수가 각각 2씩 커지니 합은 2 + 2 = 4씩 커져요.","그래서 결과는 4씩 커지는 규칙이에요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"],["다섯째","11+13","=","24"]]}},{"stem":"이번에는 다른 그림이에요. 덧셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"결과가 4씩 커져요","correct":true},{"t":"결과가 2씩 커져요","mis":"M4-1-u6-X15"},{"t":"결과가 늘 같아요","mis":"M4-1-u6-X17"},{"t":"결과가 2배씩 커져요","mis":"M4-1-u6-X08"}],"explanation":["결과: 12, 16, 20, 24, 28.","더하는 두 수가 각각 2씩 커지니 합은 2 + 2 = 4씩 커져요.","그래서 결과는 4씩 커지는 규칙이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"],["다섯째","13+15","=","28"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#3','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',1,'sa','auto','덧셈식 배열의 규칙으로 보아 일곱째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":3,"concept":"M4-1-u6-C14","difficulty":1,"kind":"sa","stem":"덧셈식 배열의 규칙으로 보아 일곱째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.","answer":["28"],"explanation":["결과는 4부터 4씩 커져요.","일곱째 식은 첫째보다 6번 더 커져요.","4 + 4 × 6 = 28이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 규칙으로 보아 일곱째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.","answer":["32"],"explanation":["결과는 8부터 4씩 커져요.","일곱째 식은 첫째보다 6번 더 커져요.","8 + 4 × 6 = 32예요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"]]}},{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 규칙으로 보아 일곱째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["결과는 12부터 4씩 커져요.","일곱째 식은 첫째보다 6번 더 커져요.","12 + 4 × 6 = 36이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#4','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',1,'sa','auto','양쪽에 연산이 있는 배열의 다섯째 식은 「55×6=□×30」이에요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u6-C14","difficulty":1,"kind":"sa","stem":"양쪽에 연산이 있는 배열의 다섯째 식은 「55×6=□×30」이에요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["11"],"explanation":["왼쪽은 15부터 10씩 커지는 수에 6을 곱해요.","오른쪽은 3부터 2씩 커지는 수에 30을 곱해요.","다섯째는 11 — 55×6 = 330 = 11×30."],"asset":{"type":"expr_grid","rows":[["첫째","15×6","=","3×30"],["둘째","25×6","=","5×30"],["셋째","35×6","=","7×30"],["넷째","45×6","=","9×30"]]},"variant_rule":{"alt":[{"stem":"양쪽에 연산이 있는 배열의 다섯째 식은 「36×5=□×15」예요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["왼쪽은 12부터 6씩 커지는 수에 5를 곱해요.","오른쪽은 4부터 2씩 커지는 수에 15를 곱해요.","다섯째는 12 — 36×5 = 180 = 12×15."],"asset":{"type":"expr_grid","rows":[["첫째","12×5","=","4×15"],["둘째","18×5","=","6×15"],["셋째","24×5","=","8×15"],["넷째","30×5","=","10×15"]]}},{"stem":"양쪽에 연산이 있는 배열의 다섯째 식은 「60×4=□×20」이에요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["왼쪽은 20부터 10씩 커지는 수에 4를 곱해요.","오른쪽은 4부터 2씩 커지는 수에 20을 곱해요.","다섯째는 12 — 60×4 = 240 = 12×20."],"asset":{"type":"expr_grid","rows":[["첫째","20×4","=","4×20"],["둘째","30×4","=","6×20"],["셋째","40×4","=","8×20"],["넷째","50×4","=","10×20"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#5','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',2,'mc','auto','덧셈식 배열의 아홉째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.',ARRAY['M4-1-u6-X19','M4-1-u6-X18']::text[],true,'{"seq":5,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"덧셈식 배열의 아홉째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.","options":[{"t":"짝수 — 홀수끼리 더하면 짝수라서","correct":true},{"t":"홀수 — 홀수를 더했으니까","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전엔 알 수 없어요","mis":"M4-1-u6-X18"},{"t":"홀수 — 아홉째 식이고 9가 홀수라서","mis":"M4-1-u6-X19"}],"explanation":["더하는 두 수는 언제나 홀수와 홀수예요.","홀수끼리 더하면 항상 짝수예요.","그래서 계산 전에 짝수라고 추측할 수 있어요 — 17+19 = 36."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"]]},"variant_rule":{"alt":[{"stem":"덧셈식 배열의 일곱째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.","options":[{"t":"짝수 — 홀수끼리 더하면 짝수라서","correct":true},{"t":"홀수 — 홀수를 더했으니까","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전엔 알 수 없어요","mis":"M4-1-u6-X18"},{"t":"홀수 — 일곱째 식이고 7이 홀수라서","mis":"M4-1-u6-X19"}],"explanation":["더하는 두 수는 언제나 홀수와 홀수예요.","홀수끼리 더하면 항상 짝수예요.","그래서 계산 전에 짝수라고 추측할 수 있어요 — 15+17 = 32."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"]]}},{"stem":"덧셈식 배열의 열한째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.","options":[{"t":"짝수 — 홀수끼리 더하면 짝수라서","correct":true},{"t":"홀수 — 홀수를 더했으니까","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전엔 알 수 없어요","mis":"M4-1-u6-X18"},{"t":"홀수 — 열한째 식이고 11이 홀수라서","mis":"M4-1-u6-X19"}],"explanation":["더하는 두 수는 언제나 홀수와 홀수예요.","홀수끼리 더하면 항상 짝수예요.","그래서 계산 전에 짝수라고 추측할 수 있어요 — 25+27 = 52."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#6','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',2,'ox','auto','「55×6=11×30」은 옳은 식이에요.',ARRAY['M4-1-u6-X04']::text[],true,'{"seq":6,"concept":"M4-1-u6-C14","difficulty":2,"kind":"ox","stem":"「55×6=11×30」은 옳은 식이에요.","answer":"O","reason_options":[{"t":"양쪽이 모두 330으로 같아서","correct":true},{"t":"양쪽에 같은 수가 하나도 없어서","mis":"M4-1-u6-X04"}],"mis":"M4-1-u6-X04","explanation":["양쪽을 계산하거나 배열의 규칙을 살펴요.","홀수 + 홀수 = 짝수, 두 수가 2씩 커지면 합은 4씩 커져요.","양쪽 값이 같을 때만 등호로 이어요."],"variant_rule":{"alt":[{"stem":"덧셈식 배열 1+3, 3+5, 5+7…의 결과는 모두 짝수예요.","answer":"O","reason_options":[{"t":"홀수끼리 더하면 짝수라서","correct":true},{"t":"아홉째처럼 홀수 번째 식은 홀수라서","mis":"M4-1-u6-X19"}],"explanation":["양쪽을 계산하거나 배열의 규칙을 살펴요.","홀수 + 홀수 = 짝수, 두 수가 2씩 커지면 합은 4씩 커져요.","양쪽 값이 같을 때만 등호로 이어요."],"asset":null},{"stem":"덧셈식 배열 1+3, 3+5, 5+7…에서 결과는 2씩 커져요.","answer":"X","reason_options":[{"t":"더하는 두 수가 각각 2씩 커져 합은 4씩 커져서","correct":true},{"t":"더하는 수가 2씩 커지니까","mis":"M4-1-u6-X15"}],"explanation":["양쪽을 계산하거나 배열의 규칙을 살펴요.","홀수 + 홀수 = 짝수, 두 수가 2씩 커지면 합은 4씩 커져요.","양쪽 값이 같을 때만 등호로 이어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#7','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',2,'mc','auto','덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X15']::text[],true,'{"seq":7,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"13+15=28","correct":true},{"t":"11+13=24","mis":"M4-1-u6-X13"},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"13+14=27","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 13, 더하는 수는 15예요.","그래서 「13+15=28」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"],["다섯째","11+13","=","24"]]}},{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"17+19=36","correct":true},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"19+21=40","mis":"M4-1-u6-X13"},{"t":"17+18=35","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 17, 더하는 수는 19예요.","그래서 「17+19=36」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"],["다섯째","13+15","=","28"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#8','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',2,'sa','auto','배열의 규칙으로 「90×11」의 계산 결과를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u6-C14","difficulty":2,"kind":"sa","stem":"배열의 규칙으로 「90×11」의 계산 결과를 구하세요. 숫자로 쓰세요.","answer":["990"],"explanation":["10×11 = 100+10, 20×11 = 200+20 — 곱을 두 수의 합으로 나타낸 배열이에요.","규칙대로라면 90×11 = 900+90이에요.","900 + 90 = 990 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","10×11","=","100+10"],["둘째","20×11","=","200+20"],["셋째","30×11","=","300+30"],["넷째","40×11","=","400+40"]]},"variant_rule":{"alt":[{"stem":"배열의 규칙으로 「70×11」의 계산 결과를 구하세요. 숫자로 쓰세요.","answer":["770"],"explanation":["10×11 = 100+10, 20×11 = 200+20 — 곱을 두 수의 합으로 나타낸 배열이에요.","규칙대로라면 70×11 = 700+70이에요.","700 + 70 = 770 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","10×11","=","100+10"],["둘째","20×11","=","200+20"],["셋째","30×11","=","300+30"],["넷째","40×11","=","400+40"]]}},{"stem":"배열의 규칙으로 「60×21」의 계산 결과를 구하세요. 숫자로 쓰세요.","answer":["1260"],"explanation":["10×21 = 200+10, 20×21 = 400+20 — 곱을 두 수의 합으로 나타낸 배열이에요.","규칙대로라면 60×21 = 1200+60이에요.","1200 + 60 = 1260 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","10×21","=","200+10"],["둘째","20×21","=","400+20"],["셋째","30×21","=","600+30"],["넷째","40×21","=","800+40"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#9','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',2,'mc','auto','양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?',ARRAY['M4-1-u6-X17','M4-1-u6-X01','M4-1-u6-X07']::text[],true,'{"seq":9,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"15부터 10씩 커지는 수에 6을 곱하면, 3부터 2씩 커지는 수에 30을 곱한 것과 같아요","correct":true},{"t":"왼쪽 식만 커지고 오른쪽 식은 그대로예요","mis":"M4-1-u6-X17"},{"t":"양쪽 값이 달라도 등호를 쓸 수 있어요","mis":"M4-1-u6-X01"},{"t":"곱하는 수 6과 30이 매번 바뀌어요","mis":"M4-1-u6-X07"}],"explanation":["왼쪽: 15×6, 25×6, 35×6.","오른쪽: 3×30, 5×30, 7×30.","양쪽 값이 늘 같아서 등호로 이어져 있어요 — 곱하는 수는 그대로예요."],"asset":{"type":"expr_grid","rows":[["첫째","15×6","=","3×30"],["둘째","25×6","=","5×30"],["셋째","35×6","=","7×30"],["넷째","45×6","=","9×30"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"12부터 6씩 커지는 수에 5를 곱하면, 4부터 2씩 커지는 수에 15를 곱한 것과 같아요","correct":true},{"t":"왼쪽 식만 커지고 오른쪽 식은 그대로예요","mis":"M4-1-u6-X17"},{"t":"양쪽 값이 달라도 등호를 쓸 수 있어요","mis":"M4-1-u6-X01"},{"t":"곱하는 수 5와 15가 매번 바뀌어요","mis":"M4-1-u6-X07"}],"explanation":["왼쪽: 12×5, 18×5, 24×5.","오른쪽: 4×15, 6×15, 8×15.","양쪽 값이 늘 같아서 등호로 이어져 있어요 — 곱하는 수는 그대로예요."],"asset":{"type":"expr_grid","rows":[["첫째","12×5","=","4×15"],["둘째","18×5","=","6×15"],["셋째","24×5","=","8×15"],["넷째","30×5","=","10×15"]]}},{"stem":"이번에는 다른 그림이에요. 양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"20부터 10씩 커지는 수에 4를 곱하면, 4부터 2씩 커지는 수에 20을 곱한 것과 같아요","correct":true},{"t":"왼쪽 식만 커지고 오른쪽 식은 그대로예요","mis":"M4-1-u6-X17"},{"t":"양쪽 값이 달라도 등호를 쓸 수 있어요","mis":"M4-1-u6-X01"},{"t":"곱하는 수 4와 20이 매번 바뀌어요","mis":"M4-1-u6-X07"}],"explanation":["왼쪽: 20×4, 30×4, 40×4.","오른쪽: 4×20, 6×20, 8×20.","양쪽 값이 늘 같아서 등호로 이어져 있어요 — 곱하는 수는 그대로예요."],"asset":{"type":"expr_grid","rows":[["첫째","20×4","=","4×20"],["둘째","30×4","=","6×20"],["셋째","40×4","=","8×20"],["넷째","50×4","=","10×20"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_basic#10','math',4,1,'u6','L08','g4_1_math_u6_L08_basic','lesson_basic','M4-1-u6-C14',3,'mc','auto','덧셈식 배열에서 계산 결과가 40이 되는 식은 몇째 식인가요?',ARRAY['M4-1-u6-X13']::text[],true,'{"seq":10,"concept":"M4-1-u6-C14","difficulty":3,"kind":"mc","stem":"덧셈식 배열에서 계산 결과가 40이 되는 식은 몇째 식인가요?","options":[{"t":"열째","correct":true},{"t":"아홉째","mis":"M4-1-u6-X13"},{"t":"열한째","mis":"M4-1-u6-X13"},{"t":"열두째","mis":"M4-1-u6-X13"}],"explanation":["결과는 4부터 4씩 커져요.","4, 8, 12, 16, 20, 24, 28, 32, 36, 40 — 차례로 세어 봐요.","40은 10번째이니 열째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열에서 계산 결과가 40이 되는 식은 몇째 식인가요?","options":[{"t":"아홉째","correct":true},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"열째","mis":"M4-1-u6-X13"},{"t":"열한째","mis":"M4-1-u6-X13"}],"explanation":["결과는 8부터 4씩 커져요.","8, 12, 16, 20, 24, 28, 32, 36, 40 — 차례로 세어 봐요.","40은 9번째이니 아홉째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"]]}},{"stem":"덧셈식 배열에서 계산 결과가 56이 되는 식은 몇째 식인가요?","options":[{"t":"열두째","correct":true},{"t":"열한째","mis":"M4-1-u6-X13"},{"t":"열셋째","mis":"M4-1-u6-X13"},{"t":"열넷째","mis":"M4-1-u6-X13"}],"explanation":["결과는 12부터 4씩 커져요.","12, 16, 20, 24, 28, 32, 36, 40, 44, 48, 52, 56 — 차례로 세어 봐요.","56은 12번째이니 열두째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#1','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',2,'mc','auto','덧셈식 배열의 열셋째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.',ARRAY['M4-1-u6-X19','M4-1-u6-X18']::text[],true,'{"seq":1,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"덧셈식 배열의 열셋째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.","options":[{"t":"짝수 — 홀수끼리 더하면 짝수라서","correct":true},{"t":"홀수 — 홀수를 더했으니까","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전엔 알 수 없어요","mis":"M4-1-u6-X18"},{"t":"홀수 — 열셋째 식이고 13이 홀수라서","mis":"M4-1-u6-X19"}],"explanation":["더하는 두 수는 언제나 홀수와 홀수예요.","홀수끼리 더하면 항상 짝수예요.","그래서 계산 전에 짝수라고 추측할 수 있어요 — 25+27 = 52."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"]]},"variant_rule":{"alt":[{"stem":"덧셈식 배열의 아홉째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.","options":[{"t":"짝수 — 홀수끼리 더하면 짝수라서","correct":true},{"t":"홀수 — 홀수를 더했으니까","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전엔 알 수 없어요","mis":"M4-1-u6-X18"},{"t":"홀수 — 아홉째 식이고 9가 홀수라서","mis":"M4-1-u6-X19"}],"explanation":["더하는 두 수는 언제나 홀수와 홀수예요.","홀수끼리 더하면 항상 짝수예요.","그래서 계산 전에 짝수라고 추측할 수 있어요 — 19+21 = 40."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"]]}},{"stem":"덧셈식 배열의 열다섯째 계산 결과는 홀수일까요, 짝수일까요? 까닭까지 고르세요.","options":[{"t":"짝수 — 홀수끼리 더하면 짝수라서","correct":true},{"t":"홀수 — 홀수를 더했으니까","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전엔 알 수 없어요","mis":"M4-1-u6-X18"},{"t":"홀수 — 열다섯째 식이고 15가 홀수라서","mis":"M4-1-u6-X19"}],"explanation":["더하는 두 수는 언제나 홀수와 홀수예요.","홀수끼리 더하면 항상 짝수예요.","그래서 계산 전에 짝수라고 추측할 수 있어요 — 33+35 = 68."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#2','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',2,'sa','auto','양쪽에 연산이 있는 배열의 다섯째 식은 「49×4=□×28」이에요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":2,"concept":"M4-1-u6-C14","difficulty":2,"kind":"sa","stem":"양쪽에 연산이 있는 배열의 다섯째 식은 「49×4=□×28」이에요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["7"],"explanation":["왼쪽은 21부터 7씩 커지는 수에 4를 곱해요.","오른쪽은 3부터 1씩 커지는 수에 28을 곱해요.","다섯째는 7 — 49×4 = 196 = 7×28."],"asset":{"type":"expr_grid","rows":[["첫째","21×4","=","3×28"],["둘째","28×4","=","4×28"],["셋째","35×4","=","5×28"],["넷째","42×4","=","6×28"]]},"variant_rule":{"alt":[{"stem":"양쪽에 연산이 있는 배열의 다섯째 식은 「48×5=□×20」이에요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["왼쪽은 16부터 8씩 커지는 수에 5를 곱해요.","오른쪽은 4부터 2씩 커지는 수에 20을 곱해요.","다섯째는 12 — 48×5 = 240 = 12×20."],"asset":{"type":"expr_grid","rows":[["첫째","16×5","=","4×20"],["둘째","24×5","=","6×20"],["셋째","32×5","=","8×20"],["넷째","40×5","=","10×20"]]}},{"stem":"양쪽에 연산이 있는 배열의 다섯째 식은 「54×4=□×12」예요. □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["왼쪽은 18부터 9씩 커지는 수에 4를 곱해요.","오른쪽은 6부터 3씩 커지는 수에 12를 곱해요.","다섯째는 18 — 54×4 = 216 = 18×12."],"asset":{"type":"expr_grid","rows":[["첫째","18×4","=","6×12"],["둘째","27×4","=","9×12"],["셋째","36×4","=","12×12"],["넷째","45×4","=","15×12"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#3','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',3,'mc','auto','「75×6=15×30」은 양쪽에 연산이 있는 배열의 몇째 식인가요?',ARRAY['M4-1-u6-X13']::text[],true,'{"seq":3,"concept":"M4-1-u6-C14","difficulty":3,"kind":"mc","stem":"「75×6=15×30」은 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"다섯째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 15부터 10씩 커져요.","15에서 75가 되려면 10씩 6번 커져야 해요.","첫째에서 6번 커졌으니 일곱째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","15×6","=","3×30"],["둘째","25×6","=","5×30"]]},"variant_rule":{"alt":[{"stem":"「48×5=16×15」는 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"다섯째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 12부터 6씩 커져요.","12에서 48이 되려면 6씩 6번 커져야 해요.","첫째에서 6번 커졌으니 일곱째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","12×5","=","4×15"],["둘째","18×5","=","6×15"]]}},{"stem":"「80×4=16×20」은 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"다섯째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 20부터 10씩 커져요.","20에서 80이 되려면 10씩 6번 커져야 해요.","첫째에서 6번 커졌으니 일곱째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","20×4","=","4×20"],["둘째","30×4","=","6×20"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
