INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#5','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',3,'sa','auto','배열의 규칙으로 「80×11」의 계산 결과를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u6-C14","difficulty":3,"kind":"sa","stem":"배열의 규칙으로 「80×11」의 계산 결과를 구하세요. 숫자로 쓰세요.","answer":["880"],"explanation":["10×11 = 100+10, 20×11 = 200+20 — 곱을 두 수의 합으로 나타낸 배열이에요.","규칙대로라면 80×11 = 800+80이에요.","800 + 80 = 880 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","10×11","=","100+10"],["둘째","20×11","=","200+20"],["셋째","30×11","=","300+30"],["넷째","40×11","=","400+40"]]},"variant_rule":{"alt":[{"stem":"배열의 규칙으로 「50×31」의 계산 결과를 구하세요. 숫자로 쓰세요.","answer":["1550"],"explanation":["10×31 = 300+10, 20×31 = 600+20 — 곱을 두 수의 합으로 나타낸 배열이에요.","규칙대로라면 50×31 = 1500+50이에요.","1500 + 50 = 1550 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","10×31","=","300+10"],["둘째","20×31","=","600+20"],["셋째","30×31","=","900+30"],["넷째","40×31","=","1200+40"]]}},{"stem":"배열의 규칙으로 「90×21」의 계산 결과를 구하세요. 숫자로 쓰세요.","answer":["1890"],"explanation":["10×21 = 200+10, 20×21 = 400+20 — 곱을 두 수의 합으로 나타낸 배열이에요.","규칙대로라면 90×21 = 1800+90이에요.","1800 + 90 = 1890 — 계산기로 확인해 봐요."],"asset":{"type":"expr_grid","rows":[["첫째","10×21","=","200+10"],["둘째","20×21","=","400+20"],["셋째","30×21","=","600+30"],["넷째","40×21","=","800+40"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#6','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',3,'mc','auto','양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?',ARRAY['M4-1-u6-X17','M4-1-u6-X01','M4-1-u6-X07']::text[],true,'{"seq":6,"concept":"M4-1-u6-C14","difficulty":3,"kind":"mc","stem":"양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"21부터 7씩 커지는 수에 4를 곱하면, 3부터 1씩 커지는 수에 28을 곱한 것과 같아요","correct":true},{"t":"왼쪽 식만 커지고 오른쪽 식은 그대로예요","mis":"M4-1-u6-X17"},{"t":"양쪽 값이 달라도 등호를 쓸 수 있어요","mis":"M4-1-u6-X01"},{"t":"곱하는 수 4와 28이 매번 바뀌어요","mis":"M4-1-u6-X07"}],"explanation":["왼쪽: 21×4, 28×4, 35×4.","오른쪽: 3×28, 4×28, 5×28.","양쪽 값이 늘 같아서 등호로 이어져 있어요 — 곱하는 수는 그대로예요."],"asset":{"type":"expr_grid","rows":[["첫째","21×4","=","3×28"],["둘째","28×4","=","4×28"],["셋째","35×4","=","5×28"],["넷째","42×4","=","6×28"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"16부터 8씩 커지는 수에 5를 곱하면, 4부터 2씩 커지는 수에 20을 곱한 것과 같아요","correct":true},{"t":"왼쪽 식만 커지고 오른쪽 식은 그대로예요","mis":"M4-1-u6-X17"},{"t":"양쪽 값이 달라도 등호를 쓸 수 있어요","mis":"M4-1-u6-X01"},{"t":"곱하는 수 5와 20이 매번 바뀌어요","mis":"M4-1-u6-X07"}],"explanation":["왼쪽: 16×5, 24×5, 32×5.","오른쪽: 4×20, 6×20, 8×20.","양쪽 값이 늘 같아서 등호로 이어져 있어요 — 곱하는 수는 그대로예요."],"asset":{"type":"expr_grid","rows":[["첫째","16×5","=","4×20"],["둘째","24×5","=","6×20"],["셋째","32×5","=","8×20"],["넷째","40×5","=","10×20"]]}},{"stem":"이번에는 다른 그림이에요. 양쪽에 연산이 있는 배열의 규칙을 바르게 말한 것은 어느 것인가요?","options":[{"t":"18부터 9씩 커지는 수에 4를 곱하면, 6부터 3씩 커지는 수에 12를 곱한 것과 같아요","correct":true},{"t":"왼쪽 식만 커지고 오른쪽 식은 그대로예요","mis":"M4-1-u6-X17"},{"t":"양쪽 값이 달라도 등호를 쓸 수 있어요","mis":"M4-1-u6-X01"},{"t":"곱하는 수 4와 12가 매번 바뀌어요","mis":"M4-1-u6-X07"}],"explanation":["왼쪽: 18×4, 27×4, 36×4.","오른쪽: 6×12, 9×12, 12×12.","양쪽 값이 늘 같아서 등호로 이어져 있어요 — 곱하는 수는 그대로예요."],"asset":{"type":"expr_grid","rows":[["첫째","18×4","=","6×12"],["둘째","27×4","=","9×12"],["셋째","36×4","=","12×12"],["넷째","45×4","=","15×12"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#7','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',3,'sa','auto','덧셈식 배열의 규칙으로 보아 열째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u6-C14","difficulty":3,"kind":"sa","stem":"덧셈식 배열의 규칙으로 보아 열째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["결과는 4부터 4씩 커져요.","열째 식은 첫째보다 9번 더 커져요.","4 + 4 × 9 = 40이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 규칙으로 보아 열째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["결과는 8부터 4씩 커져요.","열째 식은 첫째보다 9번 더 커져요.","8 + 4 × 9 = 44예요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"]]}},{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 규칙으로 보아 열째 식의 계산 결과는 얼마인가요? 숫자로 쓰세요.","answer":["48"],"explanation":["결과는 12부터 4씩 커져요.","열째 식은 첫째보다 9번 더 커져요.","12 + 4 × 9 = 48이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#8','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',4,'mc','auto','「65×6=13×30」은 양쪽에 연산이 있는 배열의 몇째 식인가요?',ARRAY['M4-1-u6-X13']::text[],true,'{"seq":8,"concept":"M4-1-u6-C14","difficulty":4,"kind":"mc","stem":"「65×6=13×30」은 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"넷째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 15부터 10씩 커져요.","15에서 65가 되려면 10씩 5번 커져야 해요.","첫째에서 5번 커졌으니 여섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","15×6","=","3×30"],["둘째","25×6","=","5×30"]]},"variant_rule":{"alt":[{"stem":"「42×5=14×15」는 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"넷째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 12부터 6씩 커져요.","12에서 42가 되려면 6씩 5번 커져야 해요.","첫째에서 5번 커졌으니 여섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","12×5","=","4×15"],["둘째","18×5","=","6×15"]]}},{"stem":"「70×4=14×20」은 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"넷째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 20부터 10씩 커져요.","20에서 70이 되려면 10씩 5번 커져야 해요.","첫째에서 5번 커졌으니 여섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","20×4","=","4×20"],["둘째","30×4","=","6×20"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#9','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',4,'mc','auto','덧셈식 배열 1+3, 3+5, 5+7…에서 계산 결과가 50인 식이 있을까요?',ARRAY['M4-1-u6-X13','M4-1-u6-X19','M4-1-u6-X18']::text[],true,'{"seq":9,"concept":"M4-1-u6-C14","difficulty":4,"kind":"mc","stem":"덧셈식 배열 1+3, 3+5, 5+7…에서 계산 결과가 50인 식이 있을까요?","options":[{"t":"없어요 — 결과는 4씩 커져 4로 나누어떨어지는 수만 나와요","correct":true},{"t":"열두째 식이에요","mis":"M4-1-u6-X13"},{"t":"있어요 — 짝수이니까 언젠가 나와요","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M4-1-u6-X18"}],"explanation":["결과는 4, 8, 12, 16… — 4씩 커져요.","50 ÷ 4는 나누어떨어지지 않아요.","50은 결과로 나올 수 없어요 — 짝수라고 다 나오는 것은 아니에요."],"variant_rule":{"alt":[{"stem":"덧셈식 배열 3+5, 5+7, 7+9…에서 계산 결과가 42인 식이 있을까요?","options":[{"t":"없어요 — 결과는 4씩 커져 4로 나누어떨어지는 수만 나와요","correct":true},{"t":"열째 식이에요","mis":"M4-1-u6-X13"},{"t":"있어요 — 짝수이니까 언젠가 나와요","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M4-1-u6-X18"}],"explanation":["결과는 8, 12, 16, 20… — 4씩 커져요.","42 ÷ 4는 나누어떨어지지 않아요.","42는 결과로 나올 수 없어요 — 짝수라고 다 나오는 것은 아니에요."],"asset":null},{"stem":"덧셈식 배열 5+7, 7+9, 9+11…에서 계산 결과가 30인 식이 있을까요?","options":[{"t":"없어요 — 결과는 4씩 커져 4로 나누어떨어지는 수만 나와요","correct":true},{"t":"일곱째 식이에요","mis":"M4-1-u6-X13"},{"t":"있어요 — 짝수이니까 언젠가 나와요","mis":"M4-1-u6-X19"},{"t":"계산해 보기 전에는 알 수 없어요","mis":"M4-1-u6-X18"}],"explanation":["결과는 12, 16, 20, 24… — 4씩 커져요.","30 ÷ 4는 나누어떨어지지 않아요.","30은 결과로 나올 수 없어요 — 짝수라고 다 나오는 것은 아니에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L08_challenge#10','math',4,1,'u6','L08','g4_1_math_u6_L08_challenge','lesson_challenge','M4-1-u6-C14',4,'essay','teacher','덧셈식 배열 「1+3=4, 3+5=8, 5+7=12, 7+9=16, 9+11=20」을 보고, 계산하지 않고 아홉째 식의 결과가 홀수인지 짝수인지 판단해 까닭을 쓰세요. 또 결과가 40인 식은 몇째 식인지 구하는 과정도 써 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u6-C14","difficulty":4,"kind":"essay","stem":"덧셈식 배열 「1+3=4, 3+5=8, 5+7=12, 7+9=16, 9+11=20」을 보고, 계산하지 않고 아홉째 식의 결과가 홀수인지 짝수인지 판단해 까닭을 쓰세요. 또 결과가 40인 식은 몇째 식인지 구하는 과정도 써 보세요.","answer_guide":{"answer":"예: 더하는 두 수가 언제나 홀수이고 홀수끼리 더하면 짝수이므로 아홉째 결과도 짝수이다. 결과는 4부터 4씩 커지므로 4, 8, 12, …, 40에서 40은 열 번째 수이다. 그래서 열째 식이다.","scoring_points":["홀수 + 홀수 = 짝수를 까닭으로 썼는가","결과가 4씩 커진다는 규칙을 썼는가","결과 40이 열째 식임을 구했는가"]},"explanation":["홀수 + 홀수 = 짝수.","결과: 4, 8, 12 … 4씩 커져요.","40 = 4 × 10 — 열째 식."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#1','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',1,'mc','auto','팔 한 개는 10g이에요. 팔 3개와 바퀴 2개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":1,"concept":"M4-1-u6-C15","difficulty":1,"kind":"mc","stem":"팔 한 개는 10g이에요. 팔 3개와 바퀴 2개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"15g","correct":true},{"t":"30g","mis":"M4-1-u6-X20"},{"t":"10g","mis":"M4-1-u6-X20"},{"t":"20g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 3개는 10+10+10 = 30g이에요.","바퀴 2개가 30g이니 바퀴 1개는 30 ÷ 2 = 15g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 2개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 한 개는 12g이에요. 팔 2개와 바퀴 3개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"8g","correct":true},{"t":"24g","mis":"M4-1-u6-X20"},{"t":"12g","mis":"M4-1-u6-X20"},{"t":"16g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 2개는 12+12 = 24g이에요.","바퀴 3개가 24g이니 바퀴 1개는 24 ÷ 3 = 8g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 한 개는 20g이에요. 팔 3개와 바퀴 4개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"15g","correct":true},{"t":"60g","mis":"M4-1-u6-X20"},{"t":"20g","mis":"M4-1-u6-X20"},{"t":"30g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 3개는 20+20+20 = 60g이에요.","바퀴 4개가 60g이니 바퀴 1개는 60 ÷ 4 = 15g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 4개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#2','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',1,'mc','auto','팔 3개와 바퀴 2개가 수평이에요. 양쪽에 팔 1개씩 똑같이 더 올리면 저울은 어떻게 되나요?',ARRAY['M4-1-u6-X21']::text[],true,'{"seq":2,"concept":"M4-1-u6-C15","difficulty":1,"kind":"mc","stem":"팔 3개와 바퀴 2개가 수평이에요. 양쪽에 팔 1개씩 똑같이 더 올리면 저울은 어떻게 되나요?","options":[{"t":"계속 수평이에요","correct":true},{"t":"왼쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"오른쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"올려 보기 전엔 알 수 없어요","mis":"M4-1-u6-X21"}],"explanation":["양쪽 무게가 같았어요 — 둘 다 30g.","같은 무게(팔 1개 10g)를 양쪽에 더하면 둘 다 40g.","그래서 계속 수평이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 2개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 2개와 바퀴 3개가 수평이에요. 양쪽에 팔 1개씩 똑같이 더 올리면 저울은 어떻게 되나요?","options":[{"t":"계속 수평이에요","correct":true},{"t":"왼쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"오른쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"올려 보기 전엔 알 수 없어요","mis":"M4-1-u6-X21"}],"explanation":["양쪽 무게가 같았어요 — 둘 다 24g.","같은 무게(팔 1개 12g)를 양쪽에 더하면 둘 다 36g.","그래서 계속 수평이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 4개와 바퀴 3개가 수평이에요. 양쪽에 팔 1개씩 똑같이 더 올리면 저울은 어떻게 되나요?","options":[{"t":"계속 수평이에요","correct":true},{"t":"왼쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"오른쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"올려 보기 전엔 알 수 없어요","mis":"M4-1-u6-X21"}],"explanation":["양쪽 무게가 같았어요 — 둘 다 24g.","같은 무게(팔 1개 6g)를 양쪽에 더하면 둘 다 30g.","그래서 계속 수평이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 4개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#3','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',1,'mc','auto','로봇 날개 모양의 배열에서 날개 수가 「2, 4, 6, 8…」이에요. 규칙은 무엇인가요?',ARRAY['M4-1-u6-X08','M4-1-u6-X15','M4-1-u6-X12']::text[],true,'{"seq":3,"concept":"M4-1-u6-C15","difficulty":1,"kind":"mc","stem":"로봇 날개 모양의 배열에서 날개 수가 「2, 4, 6, 8…」이에요. 규칙은 무엇인가요?","options":[{"t":"날개가 2개씩 늘어나요","correct":true},{"t":"날개가 2배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"날개가 3개씩 늘어나요","mis":"M4-1-u6-X15"},{"t":"날개 수가 그대로예요","mis":"M4-1-u6-X12"}],"explanation":["이웃한 두 수의 차를 구해요.","2→4, 4→6, 6→8 — 모두 2씩 차이가 나요.","그래서 날개가 2개씩 늘어나는 규칙이에요."],"variant_rule":{"alt":[{"stem":"로봇 날개 모양의 배열에서 날개 수가 「3, 6, 9, 12…」예요. 규칙은 무엇인가요?","options":[{"t":"날개가 3개씩 늘어나요","correct":true},{"t":"날개가 2배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"날개가 4개씩 늘어나요","mis":"M4-1-u6-X15"},{"t":"날개 수가 그대로예요","mis":"M4-1-u6-X12"}],"explanation":["이웃한 두 수의 차를 구해요.","3→6, 6→9, 9→12 — 모두 3씩 차이가 나요.","그래서 날개가 3개씩 늘어나는 규칙이에요."],"asset":null},{"stem":"로봇 날개 모양의 배열에서 날개 수가 「2, 6, 10, 14…」예요. 규칙은 무엇인가요?","options":[{"t":"날개가 4개씩 늘어나요","correct":true},{"t":"날개가 3배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"날개가 5개씩 늘어나요","mis":"M4-1-u6-X15"},{"t":"날개 수가 그대로예요","mis":"M4-1-u6-X12"}],"explanation":["이웃한 두 수의 차를 구해요.","2→6, 6→10, 10→14 — 모두 4씩 차이가 나요.","그래서 날개가 4개씩 늘어나는 규칙이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#4','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',1,'ox','auto','수평인 저울의 한쪽에만 팔을 하나 더 올려도 저울은 수평이에요.',ARRAY['M4-1-u6-X21']::text[],true,'{"seq":4,"concept":"M4-1-u6-C15","difficulty":1,"kind":"ox","stem":"수평인 저울의 한쪽에만 팔을 하나 더 올려도 저울은 수평이에요.","answer":"X","reason_options":[{"t":"같은 양을 양쪽에 더해야 수평이 유지되어서","correct":true},{"t":"팔 하나는 가벼워서","mis":"M4-1-u6-X21"}],"mis":"M4-1-u6-X21","explanation":["저울이 수평이면 양쪽 무게가 같아요.","같은 양을 양쪽에 더하면 계속 수평, 한쪽에만 더하면 기울어요.","여러 개의 무게에서 1개의 무게는 개수로 나누어 구해요."],"variant_rule":{"alt":[{"stem":"수평인 저울의 양쪽에 날개를 1개씩 더 올리면 저울은 계속 수평이에요.","answer":"O","reason_options":[{"t":"같은 양에 같은 양을 더하면 여전히 같아서","correct":true},{"t":"날개를 올리면 무거운 쪽으로 기울어서","mis":"M4-1-u6-X21"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","같은 양을 양쪽에 더하면 계속 수평, 한쪽에만 더하면 기울어요.","여러 개의 무게에서 1개의 무게는 개수로 나누어 구해요."],"asset":null},{"stem":"바퀴 2개가 30g이면 바퀴 1개도 30g이에요.","answer":"X","reason_options":[{"t":"30g은 바퀴 2개의 무게라 1개는 30 ÷ 2 = 15g이라서","correct":true},{"t":"바퀴는 모두 같은 무게라서","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","같은 양을 양쪽에 더하면 계속 수평, 한쪽에만 더하면 기울어요.","여러 개의 무게에서 1개의 무게는 개수로 나누어 구해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#5','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',2,'sa','auto','바퀴 1개는 15g이에요. 날개 3개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":5,"concept":"M4-1-u6-C15","difficulty":2,"kind":"sa","stem":"바퀴 1개는 15g이에요. 날개 3개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["수평이면 날개 3개의 무게 = 바퀴 1개의 무게예요.","날개 3개가 15g이에요.","15 ÷ 3 = 5 — 날개 1개는 5g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"날개 3개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"바퀴 1개는 8g이에요. 날개 4개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["수평이면 날개 4개의 무게 = 바퀴 1개의 무게예요.","날개 4개가 8g이에요.","8 ÷ 4 = 2 — 날개 1개는 2g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"날개 4개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]}},{"stem":"바퀴 1개는 15g이에요. 날개 5개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["수평이면 날개 5개의 무게 = 바퀴 1개의 무게예요.","날개 5개가 15g이에요.","15 ÷ 5 = 3 — 날개 1개는 3g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"날개 5개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#6','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',2,'sa','auto','날개 수가 첫째부터 「2, 4, 6, 8…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":6,"concept":"M4-1-u6-C15","difficulty":2,"kind":"sa","stem":"날개 수가 첫째부터 「2, 4, 6, 8…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["날개가 2개씩 늘어나요.","넷째 8개에서 1번 더 늘어나요.","8 + 2 × 1 = 10 — 10개예요."],"variant_rule":{"alt":[{"stem":"날개 수가 첫째부터 「3, 6, 9, 12…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["15"],"explanation":["날개가 3개씩 늘어나요.","넷째 12개에서 1번 더 늘어나요.","12 + 3 × 1 = 15 — 15개예요."],"asset":null},{"stem":"날개 수가 첫째부터 「2, 6, 10, 14…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["날개가 4개씩 늘어나요.","넷째 14개에서 1번 더 늘어나요.","14 + 4 × 1 = 18 — 18개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#7','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',2,'mc','auto','팔 1개는 10g, 바퀴 1개는 15g이에요. 팔 2개와 바퀴 2개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":7,"concept":"M4-1-u6-C15","difficulty":2,"kind":"mc","stem":"팔 1개는 10g, 바퀴 1개는 15g이에요. 팔 2개와 바퀴 2개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"20+30=50","correct":true},{"t":"10+15=25","mis":"M4-1-u6-X20"},{"t":"20+15=35","mis":"M4-1-u6-X20"},{"t":"10+30=40","mis":"M4-1-u6-X20"}],"explanation":["팔 2개는 10 × 2 = 20g이에요.","바퀴 2개는 15 × 2 = 30g이에요.","20 + 30 = 50 — 개수만큼 곱한 무게를 더해요."],"variant_rule":{"alt":[{"stem":"팔 1개는 12g, 바퀴 1개는 8g이에요. 팔 3개와 바퀴 1개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"36+8=44","correct":true},{"t":"12+8=20","mis":"M4-1-u6-X20"},{"t":"12+24=36","mis":"M4-1-u6-X20"},{"t":"48+8=56","mis":"M4-1-u6-X20"}],"explanation":["팔 3개는 12 × 3 = 36g이에요.","바퀴 1개는 8 × 1 = 8g이에요.","36 + 8 = 44 — 개수만큼 곱한 무게를 더해요."],"asset":null},{"stem":"팔 1개는 20g, 바퀴 1개는 15g이에요. 팔 1개와 바퀴 3개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"20+45=65","correct":true},{"t":"20+15=35","mis":"M4-1-u6-X20"},{"t":"60+15=75","mis":"M4-1-u6-X20"},{"t":"40+45=85","mis":"M4-1-u6-X20"}],"explanation":["팔 1개는 20 × 1 = 20g이에요.","바퀴 3개는 15 × 3 = 45g이에요.","20 + 45 = 65 — 개수만큼 곱한 무게를 더해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#8','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',2,'mc','auto','팔 1개는 10g, 바퀴 1개는 15g이에요. 「팔 3개와 바퀴 2개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":8,"concept":"M4-1-u6-C15","difficulty":2,"kind":"mc","stem":"팔 1개는 10g, 바퀴 1개는 15g이에요. 「팔 3개와 바퀴 2개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"10+10+10=15+15","correct":true},{"t":"10+10+10=15","mis":"M4-1-u6-X20"},{"t":"10=15+15","mis":"M4-1-u6-X20"},{"t":"10×2=15×3","mis":"M4-1-u6-X20"}],"explanation":["팔 3개의 무게는 10+10+10.","바퀴 2개의 무게는 15+15.","둘 다 30g이라 등호로 이어요 — 「10+10+10=15+15」."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 2개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 1개는 12g, 바퀴 1개는 8g이에요. 「팔 2개와 바퀴 3개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"12+12=8+8+8","correct":true},{"t":"12+12=8","mis":"M4-1-u6-X20"},{"t":"12=8+8+8","mis":"M4-1-u6-X20"},{"t":"12×3=8×2","mis":"M4-1-u6-X20"}],"explanation":["팔 2개의 무게는 12+12.","바퀴 3개의 무게는 8+8+8.","둘 다 24g이라 등호로 이어요 — 「12+12=8+8+8」."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 1개는 20g, 바퀴 1개는 15g이에요. 「팔 3개와 바퀴 4개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"20+20+20=15+15+15+15","correct":true},{"t":"20+20+20=15","mis":"M4-1-u6-X20"},{"t":"20=15+15+15+15","mis":"M4-1-u6-X20"},{"t":"20×4=15×3","mis":"M4-1-u6-X20"}],"explanation":["팔 3개의 무게는 20+20+20.","바퀴 4개의 무게는 15+15+15+15.","둘 다 60g이라 등호로 이어요 — 「20+20+20=15+15+15+15」."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 4개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#9','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',2,'mc','auto','팔 한 개는 6g이에요. 팔 4개와 바퀴 3개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":9,"concept":"M4-1-u6-C15","difficulty":2,"kind":"mc","stem":"팔 한 개는 6g이에요. 팔 4개와 바퀴 3개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"8g","correct":true},{"t":"24g","mis":"M4-1-u6-X20"},{"t":"6g","mis":"M4-1-u6-X20"},{"t":"16g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 4개는 6+6+6+6 = 24g이에요.","바퀴 3개가 24g이니 바퀴 1개는 24 ÷ 3 = 8g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 4개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 한 개는 10g이에요. 팔 4개와 바퀴 5개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"8g","correct":true},{"t":"40g","mis":"M4-1-u6-X20"},{"t":"10g","mis":"M4-1-u6-X20"},{"t":"16g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 4개는 10+10+10+10 = 40g이에요.","바퀴 5개가 40g이니 바퀴 1개는 40 ÷ 5 = 8g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 4개","icon":"🔧"},"r":{"name":"바퀴 5개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 한 개는 15g이에요. 팔 2개와 바퀴 3개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"10g","correct":true},{"t":"30g","mis":"M4-1-u6-X20"},{"t":"15g","mis":"M4-1-u6-X20"},{"t":"20g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 2개는 15+15 = 30g이에요.","바퀴 3개가 30g이니 바퀴 1개는 30 ÷ 3 = 10g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_basic#10','math',4,1,'u6','L09','g4_1_math_u6_L09_basic','lesson_basic','M4-1-u6-C15',3,'sa','auto','날개 1개는 5g이에요. 날개 수가 「3, 6, 9…」로 늘어나는 배열에서 다섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":10,"concept":"M4-1-u6-C15","difficulty":3,"kind":"sa","stem":"날개 1개는 5g이에요. 날개 수가 「3, 6, 9…」로 늘어나는 배열에서 다섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["75"],"explanation":["날개가 3개씩 늘어나니 다섯째 모양의 날개는 15개예요.","날개 1개가 5g이에요.","5 × 15 = 75 — 75g이에요."],"variant_rule":{"alt":[{"stem":"날개 1개는 2g이에요. 날개 수가 「2, 6, 10…」으로 늘어나는 배열에서 여섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["날개가 4개씩 늘어나니 여섯째 모양의 날개는 22개예요.","날개 1개가 2g이에요.","2 × 22 = 44 — 44g이에요."],"asset":null},{"stem":"날개 1개는 3g이에요. 날개 수가 「4, 8, 12…」로 늘어나는 배열에서 다섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["날개가 4개씩 늘어나니 다섯째 모양의 날개는 20개예요.","날개 1개가 3g이에요.","3 × 20 = 60 — 60g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#1','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',2,'sa','auto','바퀴 1개는 8g이에요. 날개 2개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":1,"concept":"M4-1-u6-C15","difficulty":2,"kind":"sa","stem":"바퀴 1개는 8g이에요. 날개 2개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수평이면 날개 2개의 무게 = 바퀴 1개의 무게예요.","날개 2개가 8g이에요.","8 ÷ 2 = 4 — 날개 1개는 4g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"날개 2개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 바퀴 1개는 8g이에요. 날개 2개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["4"],"explanation":["수평이면 날개 2개의 무게 = 바퀴 1개의 무게예요.","날개 2개가 8g이에요.","8 ÷ 2 = 4 — 날개 1개는 4g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"날개 2개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]}},{"stem":"바퀴 1개는 10g이에요. 날개 2개와 바퀴 1개가 수평이에요. 날개 1개의 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["수평이면 날개 2개의 무게 = 바퀴 1개의 무게예요.","날개 2개가 10g이에요.","10 ÷ 2 = 5 — 날개 1개는 5g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"날개 2개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#2','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',2,'mc','auto','팔 3개와 바퀴 4개가 수평이에요. 팔 쪽에만 팔 1개를 더 올리면 저울은 어떻게 되나요?',ARRAY['M4-1-u6-X21']::text[],true,'{"seq":2,"concept":"M4-1-u6-C15","difficulty":2,"kind":"mc","stem":"팔 3개와 바퀴 4개가 수평이에요. 팔 쪽에만 팔 1개를 더 올리면 저울은 어떻게 되나요?","options":[{"t":"팔을 올린 쪽으로 기울어요","correct":true},{"t":"계속 수평이에요","mis":"M4-1-u6-X21"},{"t":"팔을 올리지 않은 쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"올려 보기 전엔 알 수 없어요","mis":"M4-1-u6-X21"}],"explanation":["양쪽 무게가 같았어요 — 둘 다 60g.","한쪽에만 20g을 더하면 그쪽이 20g 더 무거워요.","그래서 팔을 올린 쪽으로 기울어요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 4개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 2개와 바퀴 3개가 수평이에요. 팔 쪽에만 팔 1개를 더 올리면 저울은 어떻게 되나요?","options":[{"t":"팔을 올린 쪽으로 기울어요","correct":true},{"t":"계속 수평이에요","mis":"M4-1-u6-X21"},{"t":"팔을 올리지 않은 쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"올려 보기 전엔 알 수 없어요","mis":"M4-1-u6-X21"}],"explanation":["양쪽 무게가 같았어요 — 둘 다 30g.","한쪽에만 15g을 더하면 그쪽이 15g 더 무거워요.","그래서 팔을 올린 쪽으로 기울어요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 4개와 바퀴 5개가 수평이에요. 양쪽에 팔 1개씩 똑같이 더 올리면 저울은 어떻게 되나요?","options":[{"t":"계속 수평이에요","correct":true},{"t":"왼쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"오른쪽으로 기울어요","mis":"M4-1-u6-X21"},{"t":"올려 보기 전엔 알 수 없어요","mis":"M4-1-u6-X21"}],"explanation":["양쪽 무게가 같았어요 — 둘 다 40g.","같은 무게(팔 1개 10g)를 양쪽에 더하면 둘 다 50g.","그래서 계속 수평이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 4개","icon":"🔧"},"r":{"name":"바퀴 5개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#3','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',3,'mc','auto','날개 전체 무게가 50g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 10g · 바퀴 15g · 안테나 5g)',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":3,"concept":"M4-1-u6-C15","difficulty":3,"kind":"mc","stem":"날개 전체 무게가 50g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 10g · 바퀴 15g · 안테나 5g)","options":[{"t":"바퀴 3개와 안테나 1개","correct":true},{"t":"바퀴 3개와 안테나 4개","mis":"M4-1-u6-X20"},{"t":"바퀴 2개와 안테나 5개","mis":"M4-1-u6-X20"},{"t":"팔 4개와 안테나 5개","mis":"M4-1-u6-X20"}],"explanation":["조합마다 개수만큼 곱해 더해요.","바퀴 3개와 안테나 1개 = 50g.","무게가 50g으로 같은 조합이에요 — 다른 조합은 65g, 55g, 65g."],"variant_rule":{"alt":[{"stem":"날개 전체 무게가 40g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 12g · 바퀴 8g · 안테나 2g)","options":[{"t":"팔 2개와 바퀴 2개","correct":true},{"t":"팔 2개와 안테나 4개","mis":"M4-1-u6-X20"},{"t":"팔 4개와 안테나 2개","mis":"M4-1-u6-X20"},{"t":"바퀴 3개와 안테나 4개","mis":"M4-1-u6-X20"}],"explanation":["조합마다 개수만큼 곱해 더해요.","팔 2개와 바퀴 2개 = 40g.","무게가 40g으로 같은 조합이에요 — 다른 조합은 32g, 52g, 32g."],"asset":null},{"stem":"날개 전체 무게가 45g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 20g · 바퀴 15g · 안테나 3g)","options":[{"t":"바퀴 3개","correct":true},{"t":"바퀴 2개와 안테나 4개","mis":"M4-1-u6-X20"},{"t":"팔 1개와 바퀴 2개","mis":"M4-1-u6-X20"},{"t":"팔 2개와 안테나 3개","mis":"M4-1-u6-X20"}],"explanation":["조합마다 개수만큼 곱해 더해요.","바퀴 3개 = 45g.","무게가 45g으로 같은 조합이에요 — 다른 조합은 42g, 50g, 49g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#4','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',3,'sa','auto','날개 1개는 4g이에요. 날개 수가 「3, 9, 15…」로 늘어나는 배열에서 여섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":4,"concept":"M4-1-u6-C15","difficulty":3,"kind":"sa","stem":"날개 1개는 4g이에요. 날개 수가 「3, 9, 15…」로 늘어나는 배열에서 여섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["132"],"explanation":["날개가 6개씩 늘어나니 여섯째 모양의 날개는 33개예요.","날개 1개가 4g이에요.","4 × 33 = 132 — 132g이에요."],"variant_rule":{"alt":[{"stem":"날개 1개는 4g이에요. 날개 수가 「2, 8, 14…」로 늘어나는 배열에서 다섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["104"],"explanation":["날개가 6개씩 늘어나니 다섯째 모양의 날개는 26개예요.","날개 1개가 4g이에요.","4 × 26 = 104 — 104g이에요."],"asset":null},{"stem":"날개 1개는 5g이에요. 날개 수가 「2, 4, 6…」으로 늘어나는 배열에서 여섯째 모양의 날개 전체 무게는 몇 g인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["날개가 2개씩 늘어나니 여섯째 모양의 날개는 12개예요.","날개 1개가 5g이에요.","5 × 12 = 60 — 60g이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#5','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',3,'mc','auto','팔 1개는 6g, 바퀴 1개는 8g이에요. 팔 2개와 바퀴 3개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":5,"concept":"M4-1-u6-C15","difficulty":3,"kind":"mc","stem":"팔 1개는 6g, 바퀴 1개는 8g이에요. 팔 2개와 바퀴 3개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"12+24=36","correct":true},{"t":"6+8=14","mis":"M4-1-u6-X20"},{"t":"12+8=20","mis":"M4-1-u6-X20"},{"t":"6+24=30","mis":"M4-1-u6-X20"}],"explanation":["팔 2개는 6 × 2 = 12g이에요.","바퀴 3개는 8 × 3 = 24g이에요.","12 + 24 = 36 — 개수만큼 곱한 무게를 더해요."],"variant_rule":{"alt":[{"stem":"팔 1개는 10g, 바퀴 1개는 8g이에요. 팔 2개와 바퀴 2개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"20+16=36","correct":true},{"t":"10+8=18","mis":"M4-1-u6-X20"},{"t":"20+8=28","mis":"M4-1-u6-X20"},{"t":"10+16=26","mis":"M4-1-u6-X20"}],"explanation":["팔 2개는 10 × 2 = 20g이에요.","바퀴 2개는 8 × 2 = 16g이에요.","20 + 16 = 36 — 개수만큼 곱한 무게를 더해요."],"asset":null},{"stem":"팔 1개는 15g, 바퀴 1개는 10g이에요. 팔 3개와 바퀴 1개로 만든 로봇의 무게를 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"45+10=55","correct":true},{"t":"15+10=25","mis":"M4-1-u6-X20"},{"t":"15+30=45","mis":"M4-1-u6-X20"},{"t":"60+10=70","mis":"M4-1-u6-X20"}],"explanation":["팔 3개는 15 × 3 = 45g이에요.","바퀴 1개는 10 × 1 = 10g이에요.","45 + 10 = 55 — 개수만큼 곱한 무게를 더해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#6','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',3,'mc','auto','팔 1개는 6g, 바퀴 1개는 8g이에요. 「팔 4개와 바퀴 3개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":6,"concept":"M4-1-u6-C15","difficulty":3,"kind":"mc","stem":"팔 1개는 6g, 바퀴 1개는 8g이에요. 「팔 4개와 바퀴 3개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"6+6+6+6=8+8+8","correct":true},{"t":"6+6+6+6=8","mis":"M4-1-u6-X20"},{"t":"6=8+8+8","mis":"M4-1-u6-X20"},{"t":"6×3=8×4","mis":"M4-1-u6-X20"}],"explanation":["팔 4개의 무게는 6+6+6+6.","바퀴 3개의 무게는 8+8+8.","둘 다 24g이라 등호로 이어요 — 「6+6+6+6=8+8+8」."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 4개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 1개는 10g, 바퀴 1개는 8g이에요. 「팔 4개와 바퀴 5개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"10+10+10+10=8+8+8+8+8","correct":true},{"t":"10+10+10+10=8","mis":"M4-1-u6-X20"},{"t":"10=8+8+8+8+8","mis":"M4-1-u6-X20"},{"t":"10×5=8×4","mis":"M4-1-u6-X20"}],"explanation":["팔 4개의 무게는 10+10+10+10.","바퀴 5개의 무게는 8+8+8+8+8.","둘 다 40g이라 등호로 이어요 — 「10+10+10+10=8+8+8+8+8」."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 4개","icon":"🔧"},"r":{"name":"바퀴 5개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 1개는 15g, 바퀴 1개는 10g이에요. 「팔 2개와 바퀴 3개가 수평」인 것을 바르게 나타낸 식은 어느 것인가요?","options":[{"t":"15+15=10+10+10","correct":true},{"t":"15+15=10","mis":"M4-1-u6-X20"},{"t":"15=10+10+10","mis":"M4-1-u6-X20"},{"t":"15×3=10×2","mis":"M4-1-u6-X20"}],"explanation":["팔 2개의 무게는 15+15.","바퀴 3개의 무게는 10+10+10.","둘 다 30g이라 등호로 이어요 — 「15+15=10+10+10」."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#7','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',3,'sa','auto','날개 수가 첫째부터 「2, 4, 6, 8…」로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":7,"concept":"M4-1-u6-C15","difficulty":3,"kind":"sa","stem":"날개 수가 첫째부터 「2, 4, 6, 8…」로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["12"],"explanation":["날개가 2개씩 늘어나요.","넷째 8개에서 2번 더 늘어나요.","8 + 2 × 2 = 12 — 12개예요."],"variant_rule":{"alt":[{"stem":"날개 수가 첫째부터 「3, 6, 9, 12…」로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["날개가 3개씩 늘어나요.","넷째 12개에서 2번 더 늘어나요.","12 + 3 × 2 = 18 — 18개예요."],"asset":null},{"stem":"날개 수가 첫째부터 「2, 6, 10, 14…」로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["22"],"explanation":["날개가 4개씩 늘어나요.","넷째 14개에서 2번 더 늘어나요.","14 + 4 × 2 = 22 — 22개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#8','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',4,'sa','auto','팔 1개는 10g이에요. 팔 3개와 바퀴 2개가 수평이고, 날개 3개와 바퀴 1개가 수평이에요. 날개 1개는 몇 g인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"M4-1-u6-C15","difficulty":4,"kind":"sa","stem":"팔 1개는 10g이에요. 팔 3개와 바퀴 2개가 수평이고, 날개 3개와 바퀴 1개가 수평이에요. 날개 1개는 몇 g인가요? 숫자로 쓰세요.","answer":["5"],"explanation":["첫째 저울: 바퀴 2개 = 팔 3개 = 30(g) → 바퀴 1개 15g.","둘째 저울: 날개 3개 = 바퀴 1개 = 15g.","날개 1개 = 15 ÷ 3 = 5g."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 2개","icon":"⚙️"},"down":"eq"},{"l":{"name":"날개 3개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 1개는 12g이에요. 팔 2개와 바퀴 3개가 수평이고, 날개 4개와 바퀴 1개가 수평이에요. 날개 1개는 몇 g인가요? 숫자로 쓰세요.","answer":["2"],"explanation":["첫째 저울: 바퀴 3개 = 팔 2개 = 24(g) → 바퀴 1개 8g.","둘째 저울: 날개 4개 = 바퀴 1개 = 8g.","날개 1개 = 8 ÷ 4 = 2g."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"},{"l":{"name":"날개 4개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 1개는 20g이에요. 팔 3개와 바퀴 4개가 수평이고, 날개 5개와 바퀴 1개가 수평이에요. 날개 1개는 몇 g인가요? 숫자로 쓰세요.","answer":["3"],"explanation":["첫째 저울: 바퀴 4개 = 팔 3개 = 60(g) → 바퀴 1개 15g.","둘째 저울: 날개 5개 = 바퀴 1개 = 15g.","날개 1개 = 15 ÷ 5 = 3g."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 4개","icon":"⚙️"},"down":"eq"},{"l":{"name":"날개 5개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#9','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',4,'mc','auto','날개 전체 무게가 28g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 6g · 바퀴 8g · 안테나 4g)',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":9,"concept":"M4-1-u6-C15","difficulty":4,"kind":"mc","stem":"날개 전체 무게가 28g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 6g · 바퀴 8g · 안테나 4g)","options":[{"t":"팔 2개와 안테나 4개","correct":true},{"t":"팔 2개와 바퀴 1개","mis":"M4-1-u6-X20"},{"t":"바퀴 3개와 안테나 3개","mis":"M4-1-u6-X20"},{"t":"팔 2개와 안테나 2개","mis":"M4-1-u6-X20"}],"explanation":["조합마다 개수만큼 곱해 더해요.","팔 2개와 안테나 4개 = 28g.","무게가 28g으로 같은 조합이에요 — 다른 조합은 20g, 36g, 20g."],"variant_rule":{"alt":[{"stem":"날개 전체 무게가 46g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 10g · 바퀴 8g · 안테나 4g)","options":[{"t":"팔 3개와 바퀴 2개","correct":true},{"t":"팔 2개와 바퀴 3개","mis":"M4-1-u6-X20"},{"t":"팔 4개와 안테나 4개","mis":"M4-1-u6-X20"},{"t":"팔 4개와 바퀴 2개","mis":"M4-1-u6-X20"}],"explanation":["조합마다 개수만큼 곱해 더해요.","팔 3개와 바퀴 2개 = 46g.","무게가 46g으로 같은 조합이에요 — 다른 조합은 44g, 56g, 56g."],"asset":null},{"stem":"날개 전체 무게가 50g이에요. 이와 무게가 같은 부품 조합은 어느 것인가요? (팔 15g · 바퀴 10g · 안테나 5g)","options":[{"t":"팔 2개와 바퀴 2개","correct":true},{"t":"바퀴 1개와 안테나 5개","mis":"M4-1-u6-X20"},{"t":"바퀴 3개와 안테나 5개","mis":"M4-1-u6-X20"},{"t":"팔 2개와 안테나 3개","mis":"M4-1-u6-X20"}],"explanation":["조합마다 개수만큼 곱해 더해요.","팔 2개와 바퀴 2개 = 50g.","무게가 50g으로 같은 조합이에요 — 다른 조합은 35g, 55g, 45g."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_L09_challenge#10','math',4,1,'u6','L09','g4_1_math_u6_L09_challenge','lesson_challenge','M4-1-u6-C15',4,'essay','teacher','팔 1개는 10g이에요. 팔 3개와 바퀴 2개가 수평이고, 날개 3개와 바퀴 1개가 수평이에요. 바퀴 1개와 날개 1개의 무게를 구하는 과정을 쓰고, 날개 수가 2, 4, 6, 8…로 늘어나는 배열에서 다섯째 모양의 날개 전체 무게도 구해 보세요.','{}'::text[],false,'{"seq":10,"concept":"M4-1-u6-C15","difficulty":4,"kind":"essay","stem":"팔 1개는 10g이에요. 팔 3개와 바퀴 2개가 수평이고, 날개 3개와 바퀴 1개가 수평이에요. 바퀴 1개와 날개 1개의 무게를 구하는 과정을 쓰고, 날개 수가 2, 4, 6, 8…로 늘어나는 배열에서 다섯째 모양의 날개 전체 무게도 구해 보세요.","answer_guide":{"answer":"예: 팔 3개는 30g이고 바퀴 2개와 같으므로 바퀴 1개는 30÷2=15g이다. 날개 3개는 바퀴 1개 15g과 같으므로 날개 1개는 15÷3=5g이다. 날개가 2개씩 늘어나므로 다섯째는 10개이고 전체 무게는 5×10=50g이다.","scoring_points":["바퀴 1개 15g을 저울의 같음으로 구했는가","날개 1개 5g을 구했는가","다섯째 날개 10개, 전체 50g을 구했는가"]},"explanation":["팔 3개 = 30g = 바퀴 2개 → 바퀴 15g.","날개 3개 = 바퀴 1개 = 15g → 날개 5g.","다섯째 날개 10개 × 5g = 50g."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 2개","icon":"⚙️"},"down":"eq"},{"l":{"name":"날개 3개","icon":"✈️"},"r":{"name":"바퀴 1개","icon":"⚙️"},"down":"eq"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#1','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C3',1,'mc','auto','등호(=)의 뜻으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X01','M4-1-u6-X04']::text[],true,'{"seq":1,"concept":"M4-1-u6-C3","difficulty":1,"kind":"mc","stem":"등호(=)의 뜻으로 알맞은 것은 어느 것인가요?","options":[{"t":"크기가 같은 두 양의 관계를 나타내는 기호","correct":true},{"t":"답을 쓰라는 표시","mis":"M4-1-u6-X01"},{"t":"더 큰 쪽을 가리키는 기호","mis":"M4-1-u6-X04"},{"t":"계산을 시작하라는 표시","mis":"M4-1-u6-X01"}],"explanation":["등호(=)는 >, < 처럼 두 양의 크기를 비교하는 기호예요.","등호는 양쪽의 크기가 같다는 뜻이에요.","답이 어느 쪽에 있든, 양쪽이 모두 식이든 크기만 같으면 옳은 식이에요."],"variant_rule":{"alt":[{"stem":"「60=20×3」에서 등호(=)가 나타내는 것은 무엇인가요?","options":[{"t":"60과 20×3의 크기가 같다는 것","correct":true},{"t":"20×3의 답을 왼쪽에 썼다는 것","mis":"M4-1-u6-X01"},{"t":"60이 20×3보다 크다는 것","mis":"M4-1-u6-X04"},{"t":"60을 20×3으로 바꾸어 계산하라는 것","mis":"M4-1-u6-X01"}],"explanation":["등호(=)는 >, < 처럼 두 양의 크기를 비교하는 기호예요.","등호는 양쪽의 크기가 같다는 뜻이에요.","답이 어느 쪽에 있든, 양쪽이 모두 식이든 크기만 같으면 옳은 식이에요."],"asset":null},{"stem":"등호(=)와 같은 무리의 기호, 곧 두 양의 크기를 비교하는 기호는 어느 것인가요?","options":[{"t":">","correct":true},{"t":"+","mis":"M4-1-u6-X01"},{"t":"×","mis":"M4-1-u6-X01"},{"t":"÷","mis":"M4-1-u6-X01"}],"explanation":["등호(=)는 >, < 처럼 두 양의 크기를 비교하는 기호예요.","등호는 양쪽의 크기가 같다는 뜻이에요.","답이 어느 쪽에 있든, 양쪽이 모두 식이든 크기만 같으면 옳은 식이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#2','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C1',1,'mc','auto','수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X10','M4-1-u6-X08']::text[],true,'{"seq":2,"concept":"M4-1-u6-C1","difficulty":1,"kind":"mc","stem":"수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"50씩 커져요","correct":true},{"t":"10씩 커져요","mis":"M4-1-u6-X10"},{"t":"50배씩 커져요","mis":"M4-1-u6-X08"},{"t":"50씩 작아져요","mis":"M4-1-u6-X08"}],"explanation":["가로줄을 따라 이웃한 두 수의 차를 구해 봐요.","300에서 350 — 50만큼 커졌어요.","다른 줄에서도 똑같으니 오른쪽으로 50씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[300,350,400,450,500],[310,360,410,460,510],[320,370,420,470,520],[330,380,430,480,530]]},"variant_rule":{"alt":[{"stem":"수 배열표에서 아래쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"1씩 커져요","correct":true},{"t":"10씩 커져요","mis":"M4-1-u6-X10"},{"t":"1배씩 커져요","mis":"M4-1-u6-X08"},{"t":"1씩 작아져요","mis":"M4-1-u6-X08"}],"explanation":["세로줄을 따라 이웃한 두 수의 차를 구해 봐요.","1에서 2 — 1만큼 커졌어요.","다른 줄에서도 똑같으니 아래쪽으로 1씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[1,11,21,31,41],[2,12,22,32,42],[3,13,23,33,43],[4,14,24,34,44]]}},{"stem":"이번에는 다른 그림이에요. 수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"20씩 커져요","correct":true},{"t":"2씩 커져요","mis":"M4-1-u6-X10"},{"t":"20배씩 커져요","mis":"M4-1-u6-X08"},{"t":"20씩 작아져요","mis":"M4-1-u6-X08"}],"explanation":["가로줄을 따라 이웃한 두 수의 차를 구해 봐요.","40에서 60 — 20만큼 커졌어요.","다른 줄에서도 똑같으니 오른쪽으로 20씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[40,60,80,100,120],[42,62,82,102,122],[44,64,84,104,124],[46,66,86,106,126]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#3','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C4',1,'mc','auto','식이 옳은지 판단하는 방법으로 알맞지 않은 것은 어느 것인가요?',ARRAY['M4-1-u6-X22']::text[],true,'{"seq":3,"concept":"M4-1-u6-C4","difficulty":1,"kind":"mc","stem":"식이 옳은지 판단하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"등호 왼쪽만 계산해 보면 돼요.","correct":true},{"t":"양쪽을 각각 계산해서 비교해요.","mis":"M4-1-u6-X22"},{"t":"양쪽 수의 관계를 비교해요.","mis":"M4-1-u6-X22"},{"t":"수 모형으로 양쪽 크기를 비교해요.","mis":"M4-1-u6-X22"}],"explanation":["식이 옳은지는 등호 양쪽의 크기가 같은지로 판단해요.","양쪽을 각각 계산하거나, 양쪽 수의 관계를 비교하거나, 수 모형으로 견줄 수 있어요.","한쪽만 계산하거나 겉모양만 보면 알 수 없어요."],"variant_rule":{"alt":[{"stem":"식이 옳은지 판단하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"등호 양쪽을 각각 계산해서 크기를 비교해요.","correct":true},{"t":"등호 왼쪽만 계산해 보면 돼요.","mis":"M4-1-u6-X04"},{"t":"양쪽에 같은 수가 들어 있는지만 봐요.","mis":"M4-1-u6-X04"},{"t":"답이 오른쪽에 있는지 봐요.","mis":"M4-1-u6-X01"}],"explanation":["식이 옳은지는 등호 양쪽의 크기가 같은지로 판단해요.","양쪽을 각각 계산하거나, 양쪽 수의 관계를 비교하거나, 수 모형으로 견줄 수 있어요.","한쪽만 계산하거나 겉모양만 보면 알 수 없어요."],"asset":null},{"stem":"계산하지 않고 식이 옳은지 판단하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"양쪽 수의 관계를 비교해요.","correct":true},{"t":"수가 더 큰 쪽이 옳다고 해요.","mis":"M4-1-u6-X04"},{"t":"등호가 가운데 있으면 옳다고 해요.","mis":"M4-1-u6-X01"},{"t":"양쪽 수의 개수가 같으면 옳다고 해요.","mis":"M4-1-u6-X04"}],"explanation":["식이 옳은지는 등호 양쪽의 크기가 같은지로 판단해요.","양쪽을 각각 계산하거나, 양쪽 수의 관계를 비교하거나, 수 모형으로 견줄 수 있어요.","한쪽만 계산하거나 겉모양만 보면 알 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#4','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C7',1,'mc','auto','수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X10','M4-1-u6-X08','M4-1-u6-X07']::text[],true,'{"seq":4,"concept":"M4-1-u6-C7","difficulty":1,"kind":"mc","stem":"수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"25씩 커져요","correct":true},{"t":"100씩 커져요","mis":"M4-1-u6-X10"},{"t":"25씩 작아져요","mis":"M4-1-u6-X08"},{"t":"250씩 커져요","mis":"M4-1-u6-X07"}],"explanation":["가로줄에서 이웃한 수의 차를 구해요.","300 → 325 — 25 커졌어요.","모든 줄에서 같으니 25씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[175,200,225,250,275],[275,300,325,350,375],[375,400,425,450,475],[475,500,525,550,575]]},"variant_rule":{"alt":[{"stem":"수 배열표에서 아래쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"1000씩 커져요","correct":true},{"t":"50씩 커져요","mis":"M4-1-u6-X10"},{"t":"1000씩 작아져요","mis":"M4-1-u6-X08"},{"t":"10000씩 커져요","mis":"M4-1-u6-X07"}],"explanation":["세로줄에서 이웃한 수의 차를 구해요.","2250 → 3250 — 1000 커졌어요.","모든 줄에서 같으니 1000씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[1200,1250,1300,1350,1400],[2200,2250,2300,2350,2400],[3200,3250,3300,3350,3400],[4200,4250,4300,4350,4400]]}},{"stem":"이번에는 다른 그림이에요. 수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"2씩 커져요","correct":true},{"t":"10씩 커져요","mis":"M4-1-u6-X10"},{"t":"2씩 작아져요","mis":"M4-1-u6-X08"},{"t":"2배씩 커져요","mis":"M4-1-u6-X08"}],"explanation":["가로줄에서 이웃한 수의 차를 구해요.","42 → 44 — 2 커졌어요.","모든 줄에서 같으니 2씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[30,32,34,36,38],[40,42,44,46,48],[50,52,54,56,58],[60,62,64,66,68]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXC