INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#7','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C13',1,'mc','auto','곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X08','M4-1-u6-X07','M4-1-u6-X17']::text[],true,'{"seq":7,"concept":"M4-1-u6-C13","difficulty":1,"kind":"mc","stem":"곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"2와 2 사이에 4가 1개씩 늘어나요","correct":true},{"t":"결과가 2배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 2200씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 242, 2442, 24442, 244442.","2와 2 사이의 4가 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×2","=","242"],["둘째","1221×2","=","2442"],["셋째","12221×2","=","24442"],["넷째","122221×2","=","244442"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"4와 4 사이에 8이 1개씩 늘어나요","correct":true},{"t":"결과가 4배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 4400씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 484, 4884, 48884, 488884.","4와 4 사이의 8이 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"]]}},{"stem":"이번에는 다른 그림이에요. 곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"3과 3 사이에 6이 1개씩 늘어나요","correct":true},{"t":"결과가 3배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 3300씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 363, 3663, 36663, 366663.","3과 3 사이의 6이 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×3","=","363"],["둘째","1221×3","=","3663"],["셋째","12221×3","=","36663"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#8','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C15',1,'mc','auto','팔 한 개는 10g이에요. 팔 4개와 바퀴 5개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":8,"concept":"M4-1-u6-C15","difficulty":1,"kind":"mc","stem":"팔 한 개는 10g이에요. 팔 4개와 바퀴 5개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"8g","correct":true},{"t":"40g","mis":"M4-1-u6-X20"},{"t":"10g","mis":"M4-1-u6-X20"},{"t":"16g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 4개는 10+10+10+10 = 40g이에요.","바퀴 5개가 40g이니 바퀴 1개는 40 ÷ 5 = 8g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 4개","icon":"🔧"},"r":{"name":"바퀴 5개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 한 개는 15g이에요. 팔 2개와 바퀴 3개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"10g","correct":true},{"t":"30g","mis":"M4-1-u6-X20"},{"t":"15g","mis":"M4-1-u6-X20"},{"t":"20g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 2개는 15+15 = 30g이에요.","바퀴 3개가 30g이니 바퀴 1개는 30 ÷ 3 = 10g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 한 개는 8g이에요. 팔 3개와 바퀴 4개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"6g","correct":true},{"t":"24g","mis":"M4-1-u6-X20"},{"t":"8g","mis":"M4-1-u6-X20"},{"t":"12g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 3개는 8+8+8 = 24g이에요.","바퀴 4개가 24g이니 바퀴 1개는 24 ÷ 4 = 6g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 4개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#9','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C2',2,'sa','auto','저울이 수평을 이루고 있어요. 「35+□=100−20」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u6-C2","difficulty":2,"kind":"sa","stem":"저울이 수평을 이루고 있어요. 「35+□=100−20」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["수평이면 양쪽의 크기가 같아요.","오른쪽 100−20 = 80이에요.","35+□ 전체가 80이 되려면 □ = 80 − 35 = 45예요."],"asset":{"type":"balance","scales":[{"l":{"name":"35+□","icon":"⚖️"},"r":{"name":"100−20","icon":"⚖️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"저울이 수평을 이루고 있어요. 「□+48=30×3」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["42"],"explanation":["수평이면 양쪽의 크기가 같아요.","오른쪽 30×3 = 90이에요.","□+48 전체가 90이 되려면 □ = 90 − 48 = 42예요."],"asset":{"type":"balance","scales":[{"l":{"name":"□+48","icon":"⚖️"},"r":{"name":"30×3","icon":"⚖️"},"down":"eq"}]}},{"stem":"저울이 수평을 이루고 있어요. 「60+□=25×4」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["40"],"explanation":["수평이면 양쪽의 크기가 같아요.","오른쪽 25×4 = 100이에요.","60+□ 전체가 100이 되려면 □ = 100 − 60 = 40이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"60+□","icon":"⚖️"},"r":{"name":"25×4","icon":"⚖️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#10','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C5',2,'mc','auto','「22+86=18+90」에서 22는 18보다 4 크고 86은 90보다 4 작아요. 이 식은 어떨까요?',ARRAY['M4-1-u6-X04','M4-1-u6-X05']::text[],true,'{"seq":10,"concept":"M4-1-u6-C5","difficulty":2,"kind":"mc","stem":"「22+86=18+90」에서 22는 18보다 4 크고 86은 90보다 4 작아요. 이 식은 어떨까요?","options":[{"t":"옳아요 — 한쪽이 4 큰 만큼 다른 쪽이 4 작아서 크기가 같아요","correct":true},{"t":"옳지 않아요 — 양쪽의 수가 서로 달라요","mis":"M4-1-u6-X04"},{"t":"옳지 않아요 — 4만큼 차이가 나요","mis":"M4-1-u6-X05"},{"t":"계산해 보기 전에는 절대 알 수 없어요","mis":"M4-1-u6-X04"}],"explanation":["짝이 되는 두 수의 변화를 함께 봐요.","22와 18은 4 차이, 86과 90도 4 차이인데 방향이 반대예요.","커진 만큼 작아졌으니 양쪽 크기가 같아요 — 옳은 식이에요."],"variant_rule":{"alt":[{"stem":"「39+83=42+80」에서 39는 42보다 3 작고 83은 80보다 3 커요. 이 식은 어떨까요?","options":[{"t":"옳아요 — 한쪽이 3 큰 만큼 다른 쪽이 3 작아서 크기가 같아요","correct":true},{"t":"옳지 않아요 — 양쪽의 수가 서로 달라요","mis":"M4-1-u6-X04"},{"t":"옳지 않아요 — 3만큼 차이가 나요","mis":"M4-1-u6-X05"},{"t":"계산해 보기 전에는 절대 알 수 없어요","mis":"M4-1-u6-X04"}],"explanation":["짝이 되는 두 수의 변화를 함께 봐요.","39와 42는 3 차이, 83과 80도 3 차이인데 방향이 반대예요.","커진 만큼 작아졌으니 양쪽 크기가 같아요 — 옳은 식이에요."],"asset":null},{"stem":"「27+46=23+50」에서 27은 23보다 4 크고 46은 50보다 4 작아요. 이 식은 어떨까요?","options":[{"t":"옳아요 — 한쪽이 4 큰 만큼 다른 쪽이 4 작아서 크기가 같아요","correct":true},{"t":"옳지 않아요 — 양쪽의 수가 서로 달라요","mis":"M4-1-u6-X04"},{"t":"옳지 않아요 — 4만큼 차이가 나요","mis":"M4-1-u6-X05"},{"t":"계산해 보기 전에는 절대 알 수 없어요","mis":"M4-1-u6-X04"}],"explanation":["짝이 되는 두 수의 변화를 함께 봐요.","27과 23은 4 차이, 46과 50도 4 차이인데 방향이 반대예요.","커진 만큼 작아졌으니 양쪽 크기가 같아요 — 옳은 식이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#11','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C6',2,'sa','auto','「□+11=54+52」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M4-1-u6-C6","difficulty":2,"kind":"sa","stem":"「□+11=54+52」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["95"],"explanation":["54+52 = 106이에요.","□가 든 쪽 전체가 106이 되어야 해요.","□ = 106 − 11 = 95예요."],"variant_rule":{"alt":[{"stem":"「34+37=□+11」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["60"],"explanation":["34+37 = 71이에요.","□가 든 쪽 전체가 71이 되어야 해요.","□ = 71 − 11 = 60이에요."],"asset":null},{"stem":"「45+44=19+□」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["70"],"explanation":["45+44 = 89예요.","□가 든 쪽 전체가 89가 되어야 해요.","□ = 89 − 19 = 70이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#12','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C7',2,'sa','auto','수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-1-u6-C7","difficulty":2,"kind":"sa","stem":"수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["30"],"explanation":["750 → 150 처럼 앞의 수를 5로 나눈 몫이 다음 수예요.","750, 150, 6은 모두 5로 나누면 다음 수가 돼요.","150 ÷ 5 = 30 — ?는 30이에요."],"asset":{"type":"numgrid","rows":[["첫째","둘째","셋째","넷째"],[750,150,null,6]],"q":[1,2]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["80"],"explanation":["160 → … → 40 — 얼마씩 빼는 게 아니라 나누는 규칙이에요.","160, 40, 20, 10은 모두 2로 나누면 다음 수가 돼요.","160 ÷ 2 = 80 — ?는 80이에요."],"asset":{"type":"numgrid","rows":[["첫째","둘째","셋째","넷째","다섯째"],[160,null,40,20,10]],"q":[1,1]}},{"stem":"이번에는 다른 그림이에요. 수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["3"],"explanation":["192 → 48 처럼 앞의 수를 4로 나눈 몫이 다음 수예요.","192, 48, 12는 모두 4로 나누면 다음 수가 돼요.","12 ÷ 4 = 3 — ?는 3이에요."],"asset":{"type":"numgrid","rows":[["첫째","둘째","셋째","넷째"],[192,48,12,null]],"q":[1,3]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#13','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C10',2,'mc','auto','피라미드 모양 쌓기나무 배열의 셋째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M4-1-u6-X15','M4-1-u6-X13']::text[],true,'{"seq":13,"concept":"M4-1-u6-C10","difficulty":2,"kind":"mc","stem":"피라미드 모양 쌓기나무 배열의 셋째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5","correct":true},{"t":"1+2+3","mis":"M4-1-u6-X15"},{"t":"3+3+3","mis":"M4-1-u6-X15"},{"t":"1+3","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","셋째 모양은 3층 — 1+3+5.","1+3+5 = 9개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]},"variant_rule":{"alt":[{"stem":"피라미드 모양 쌓기나무 배열의 넷째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5+7","correct":true},{"t":"1+2+3+4","mis":"M4-1-u6-X15"},{"t":"4+4+4+4","mis":"M4-1-u6-X15"},{"t":"1+3+5","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","넷째 모양은 4층 — 1+3+5+7.","1+3+5+7 = 16개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}},{"stem":"피라미드 모양 쌓기나무 배열의 다섯째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5+7+9","correct":true},{"t":"1+2+3+4+5","mis":"M4-1-u6-X15"},{"t":"5+5+5+5+5","mis":"M4-1-u6-X15"},{"t":"1+3+5+7","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","다섯째 모양은 5층 — 1+3+5+7+9.","1+3+5+7+9 = 25개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#14','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C12',2,'mc','auto','지아와 준서가 만든 사각형 배열이에요(왼쪽 셋은 지아, 오른쪽 셋은 준서의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?',ARRAY['M4-1-u6-X14','M4-1-u6-X09']::text[],true,'{"seq":14,"concept":"M4-1-u6-C12","difficulty":2,"kind":"mc","stem":"지아와 준서가 만든 사각형 배열이에요(왼쪽 셋은 지아, 오른쪽 셋은 준서의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?","options":[{"t":"개수가 같게 늘어나니 같은 규칙이에요","correct":true},{"t":"모양이 다르니 규칙도 달라요","mis":"M4-1-u6-X14"},{"t":"한 사람은 반드시 틀렸어요","mis":"M4-1-u6-X09"},{"t":"모양이 다르면 견줄 수 없어요","mis":"M4-1-u6-X14"}],"explanation":["두 배열 모두 3, 5, 7 — 2개씩 늘어나요.","모양은 달라도 개수가 같게 변해요.","그래서 같은 규칙으로 만든 다른 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[0,4],[1,4],[1,5],[0,5]]},{"p":[[0,6],[1,6],[1,7],[0,7]]},{"p":[[3,4],[4,4],[4,5],[3,5]]},{"p":[[3,3],[4,3],[4,4],[3,4]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[3,5],[4,5],[4,6],[3,6]]},{"p":[[3,6],[4,6],[4,7],[3,7]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[6,2],[7,2],[7,3],[6,3]]},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[6,5],[7,5],[7,6],[6,6]]},{"p":[[6,6],[7,6],[7,7],[6,7]]},{"p":[[10,3],[11,3],[11,4],[10,4]]},{"p":[[10,2],[11,2],[11,3],[10,3]]},{"p":[[11,3],[12,3],[12,4],[11,4]]},{"p":[[14,3],[15,3],[15,4],[14,4]]},{"p":[[14,2],[15,2],[15,3],[14,3]]},{"p":[[14,1],[15,1],[15,2],[14,2]]},{"p":[[15,3],[16,3],[16,4],[15,4]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[19,3],[20,3],[20,4],[19,4]]},{"p":[[19,2],[20,2],[20,3],[19,3]]},{"p":[[19,1],[20,1],[20,2],[19,2]]},{"p":[[19,0],[20,0],[20,1],[19,1]]},{"p":[[20,3],[21,3],[21,4],[20,4]]},{"p":[[21,3],[22,3],[22,4],[21,4]]},{"p":[[22,3],[23,3],[23,4],[22,4]]}],"u":12},"variant_rule":{"alt":[{"stem":"준서와 민서가 만든 사각형 배열이에요(왼쪽 셋은 준서, 오른쪽 셋은 민서의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?","options":[{"t":"개수가 같게 늘어나니 같은 규칙이에요","correct":true},{"t":"모양이 다르니 규칙도 달라요","mis":"M4-1-u6-X14"},{"t":"한 사람은 반드시 틀렸어요","mis":"M4-1-u6-X09"},{"t":"모양이 다르면 견줄 수 없어요","mis":"M4-1-u6-X14"}],"explanation":["두 배열 모두 3, 5, 7 — 2개씩 늘어나요.","모양은 달라도 개수가 같게 변해요.","그래서 같은 규칙으로 만든 다른 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[0,4],[1,4],[1,5],[0,5]]},{"p":[[0,6],[1,6],[1,7],[0,7]]},{"p":[[3,4],[4,4],[4,5],[3,5]]},{"p":[[3,3],[4,3],[4,4],[3,4]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[3,5],[4,5],[4,6],[3,6]]},{"p":[[3,6],[4,6],[4,7],[3,7]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[6,2],[7,2],[7,3],[6,3]]},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[6,5],[7,5],[7,6],[6,6]]},{"p":[[6,6],[7,6],[7,7],[6,7]]},{"p":[[10,0],[11,0],[11,1],[10,1]]},{"p":[[10,1],[11,1],[11,2],[10,2]]},{"p":[[10,2],[11,2],[11,3],[10,3]]},{"p":[[13,0],[14,0],[14,1],[13,1]]},{"p":[[13,1],[14,1],[14,2],[13,2]]},{"p":[[13,2],[14,2],[14,3],[13,3]]},{"p":[[14,1],[15,1],[15,2],[14,2]]},{"p":[[14,2],[15,2],[15,3],[14,3]]},{"p":[[17,0],[18,0],[18,1],[17,1]]},{"p":[[17,1],[18,1],[18,2],[17,2]]},{"p":[[17,2],[18,2],[18,3],[17,3]]},{"p":[[18,1],[19,1],[19,2],[18,2]]},{"p":[[18,2],[19,2],[19,3],[18,3]]},{"p":[[19,1],[20,1],[20,2],[19,2]]},{"p":[[19,2],[20,2],[20,3],[19,3]]}],"u":12}},{"stem":"민서와 도윤이가 만든 사각형 배열이에요(왼쪽 셋은 민서, 오른쪽 셋은 도윤의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?","options":[{"t":"개수가 같게 늘어나니 같은 규칙이에요","correct":true},{"t":"모양이 다르니 규칙도 달라요","mis":"M4-1-u6-X14"},{"t":"한 사람은 반드시 틀렸어요","mis":"M4-1-u6-X09"},{"t":"모양이 다르면 견줄 수 없어요","mis":"M4-1-u6-X14"}],"explanation":["두 배열 모두 3, 5, 7 — 2개씩 늘어나요.","모양은 달라도 개수가 같게 변해요.","그래서 같은 규칙으로 만든 다른 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4