INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#15','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C14',2,'mc','auto','덧셈식 배열의 여섯째 식으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X15']::text[],true,'{"seq":15,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"덧셈식 배열의 여섯째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","여섯째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"],["다섯째","13+15","=","28"]]},"variant_rule":{"alt":[{"stem":"덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"13+15=28","correct":true},{"t":"11+13=24","mis":"M4-1-u6-X13"},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"13+14=27","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 13, 더하는 수는 15예요.","그래서 「13+15=28」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]}},{"stem":"덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"],["다섯째","11+13","=","24"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#16','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C15',2,'sa','auto','날개 수가 첫째부터 「2, 6, 10, 14…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u6-C15","difficulty":2,"kind":"sa","stem":"날개 수가 첫째부터 「2, 6, 10, 14…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["날개가 4개씩 늘어나요.","넷째 14개에서 1번 더 늘어나요.","14 + 4 × 1 = 18 — 18개예요."],"variant_rule":{"alt":[{"stem":"날개 수가 첫째부터 「4, 8, 12, 16…」으로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["날개가 4개씩 늘어나요.","넷째 16개에서 2번 더 늘어나요.","16 + 4 × 2 = 24 — 24개예요."],"asset":null},{"stem":"날개 수가 첫째부터 「3, 9, 15, 21…」로 늘어나는 배열이에요. 일곱째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["날개가 6개씩 늘어나요.","넷째 21개에서 3번 더 늘어나요.","21 + 6 × 3 = 39 — 39개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#17','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C4',3,'mc','auto','도윤이가 계산한 차례대로 「42+27=69+7=76」이라고 썼어요. 이 식은 옳을까요?',ARRAY['M4-1-u6-X02','M4-1-u6-X04']::text[],true,'{"seq":17,"concept":"M4-1-u6-C4","difficulty":3,"kind":"mc","stem":"도윤이가 계산한 차례대로 「42+27=69+7=76」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 42+27은 69인데, 69+7인 76과는 크기가 달라서","correct":true},{"t":"옳아요 — 42+27을 계산하면 69이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 69+7을 계산하면 76이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","42+27 = 69이고 69+7 = 76 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「42+27=69」, 「69+7=76」처럼 따로 써요."],"variant_rule":{"alt":[{"stem":"서윤이가 계산한 차례대로 「46+20=66+2=68」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 46+20은 66인데, 66+2인 68과는 크기가 달라서","correct":true},{"t":"옳아요 — 46+20을 계산하면 66이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 66+2를 계산하면 68이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","46+20 = 66이고 66+2 = 68 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「46+20=66」, 「66+2=68」처럼 따로 써요."],"asset":null},{"stem":"시우가 계산한 차례대로 「27+24=51+5=56」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 27+24는 51인데, 51+5인 56과는 크기가 달라서","correct":true},{"t":"옳아요 — 27+24를 계산하면 51이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 51+5를 계산하면 56이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","27+24 = 51이고 51+5 = 56 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「27+24=51」, 「51+5=56」처럼 따로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#18','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C6',3,'mc','auto','「26+38=□+6」에서 준서는 「26+38은 64이니까 □는 64야!」라고 했어요. 준서의 생각이 틀린 까닭은 무엇인가요?',ARRAY['M4-1-u6-X04','M4-1-u6-X03','M4-1-u6-X01']::text[],true,'{"seq":18,"concept":"M4-1-u6-C6","difficulty":3,"kind":"mc","stem":"「26+38=□+6」에서 준서는 「26+38은 64이니까 □는 64야!」라고 했어요. 준서의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 64이면 □+6은 70이 되어 64인 26+38과 크기가 달라져요","correct":true},{"t":"26+38은 64가 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+6)가 64가 되어야 해요.","준서처럼 □에 64를 넣으면 □+6 = 70이에요.","바른 □는 64 − 6 = 58이에요."],"variant_rule":{"alt":[{"stem":"「32+31=□+5」에서 민서는 「32+31은 63이니까 □는 63이야!」라고 했어요. 민서의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 63이면 □+5는 68이 되어 63인 32+31과 크기가 달라져요","correct":true},{"t":"32+31은 63이 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+5)가 63이 되어야 해요.","민서처럼 □에 63을 넣으면 □+5 = 68이에요.","바른 □는 63 − 5 = 58이에요."],"asset":null},{"stem":"「42+46=□+7」에서 도윤이는 「42+46은 88이니까 □는 88이야!」라고 했어요. 도윤의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 88이면 □+7은 95가 되어 88인 42+46과 크기가 달라져요","correct":true},{"t":"42+46은 88이 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+7)가 88이 되어야 해요.","도윤처럼 □에 88을 넣으면 □+7 = 95예요.","바른 □는 88 − 7 = 81이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_a#19','math',4,1,'u6','','g4_1_math_u6_review_a','unit_review','M4-1-u6-C8',3,'mc','auto','같은 수 배열표에서 지아는 「가로로 10씩 커져.」, 준서는 「↘ 방향으로 110씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?',ARRAY['M4-1-u6-X09']::text[],true,'{"seq":19,"concept":"M4-1-u6-C8","difficulty":3,"kind":"mc","stem":"같은 수 배열표에서 지아는 「가로로 10씩 커져.」, 준서는 「↘ 방향으로 110씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 준서의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 지아의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 10씩, 아래로는 100씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 100 + 10 = 110씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[100,110,120,130,140],[200,210,220,230,240],[300,310,320,330,340],[400,410,420,430,440]]},"variant_rule":{"alt":[{"stem":"같은 수 배열표에서 준서는 「가로로 5씩 커져.」, 민서는 「↘ 방향으로 105씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 민서의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 준서의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 5씩, 아래로는 100씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 100 + 5 = 105씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[305,310,315,320,325],[405,410,415,420,425],[505,510,515,520,525],[605,610,615,620,625]]}},{"stem":"같은 수 배열표에서 민서는 「가로로 200씩 커져.」, 도윤이는 「↘ 방향으로 1200씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 도윤의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 민서의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 200씩, 아래로는 1000씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 1000 + 200 = 1200씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[1200,1400,1600,1800,2000],[2200,2400,2600,2800,3000],[3200,3400,3600,3800,4000],[4200,4400,4600,4800,5000]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
