INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#15','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C14',2,'mc','auto','덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X15']::text[],true,'{"seq":15,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"13+15=28","correct":true},{"t":"11+13=24","mis":"M4-1-u6-X13"},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"13+14=27","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 13, 더하는 수는 15예요.","그래서 「13+15=28」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"],["다섯째","11+13","=","24"]]}},{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"17+19=36","correct":true},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"19+21=40","mis":"M4-1-u6-X13"},{"t":"17+18=35","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 17, 더하는 수는 19예요.","그래서 「17+19=36」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"],["다섯째","13+15","=","28"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#16','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C15',2,'sa','auto','날개 수가 첫째부터 「4, 8, 12, 16…」으로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u6-C15","difficulty":2,"kind":"sa","stem":"날개 수가 첫째부터 「4, 8, 12, 16…」으로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["24"],"explanation":["날개가 4개씩 늘어나요.","넷째 16개에서 2번 더 늘어나요.","16 + 4 × 2 = 24 — 24개예요."],"variant_rule":{"alt":[{"stem":"날개 수가 첫째부터 「3, 9, 15, 21…」로 늘어나는 배열이에요. 일곱째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["날개가 6개씩 늘어나요.","넷째 21개에서 3번 더 늘어나요.","21 + 6 × 3 = 39 — 39개예요."],"asset":null},{"stem":"날개 수가 첫째부터 「2, 8, 14, 20…」으로 늘어나는 배열이에요. 여덟째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["날개가 6개씩 늘어나요.","넷째 20개에서 4번 더 늘어나요.","20 + 6 × 4 = 44 — 44개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#17','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C4',3,'mc','auto','서윤이가 계산한 차례대로 「46+20=66+2=68」이라고 썼어요. 이 식은 옳을까요?',ARRAY['M4-1-u6-X02','M4-1-u6-X04']::text[],true,'{"seq":17,"concept":"M4-1-u6-C4","difficulty":3,"kind":"mc","stem":"서윤이가 계산한 차례대로 「46+20=66+2=68」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 46+20은 66인데, 66+2인 68과는 크기가 달라서","correct":true},{"t":"옳아요 — 46+20을 계산하면 66이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 66+2를 계산하면 68이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","46+20 = 66이고 66+2 = 68 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「46+20=66」, 「66+2=68」처럼 따로 써요."],"variant_rule":{"alt":[{"stem":"시우가 계산한 차례대로 「27+24=51+5=56」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 27+24는 51인데, 51+5인 56과는 크기가 달라서","correct":true},{"t":"옳아요 — 27+24를 계산하면 51이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 51+5를 계산하면 56이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","27+24 = 51이고 51+5 = 56 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「27+24=51」, 「51+5=56」처럼 따로 써요."],"asset":null},{"stem":"은우가 계산한 차례대로 「40+13=53+5=58」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 40+13은 53인데, 53+5인 58과는 크기가 달라서","correct":true},{"t":"옳아요 — 40+13을 계산하면 53이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 53+5를 계산하면 58이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","40+13 = 53이고 53+5 = 58 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「40+13=53」, 「53+5=58」처럼 따로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#18','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C6',3,'mc','auto','「32+31=□+5」에서 민서는 「32+31은 63이니까 □는 63이야!」라고 했어요. 민서의 생각이 틀린 까닭은 무엇인가요?',ARRAY['M4-1-u6-X04','M4-1-u6-X03','M4-1-u6-X01']::text[],true,'{"seq":18,"concept":"M4-1-u6-C6","difficulty":3,"kind":"mc","stem":"「32+31=□+5」에서 민서는 「32+31은 63이니까 □는 63이야!」라고 했어요. 민서의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 63이면 □+5는 68이 되어 63인 32+31과 크기가 달라져요","correct":true},{"t":"32+31은 63이 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+5)가 63이 되어야 해요.","민서처럼 □에 63을 넣으면 □+5 = 68이에요.","바른 □는 63 − 5 = 58이에요."],"variant_rule":{"alt":[{"stem":"「42+46=□+7」에서 도윤이는 「42+46은 88이니까 □는 88이야!」라고 했어요. 도윤의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 88이면 □+7은 95가 되어 88인 42+46과 크기가 달라져요","correct":true},{"t":"42+46은 88이 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+7)가 88이 되어야 해요.","도윤처럼 □에 88을 넣으면 □+7 = 95예요.","바른 □는 88 − 7 = 81이에요."],"asset":null},{"stem":"「46+58=□+6」에서 서윤이는 「46+58은 104이니까 □는 104야!」라고 했어요. 서윤의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 104이면 □+6은 110이 되어 104인 46+58과 크기가 달라져요","correct":true},{"t":"46+58은 104가 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+6)가 104가 되어야 해요.","서윤처럼 □에 104를 넣으면 □+6 = 110이에요.","바른 □는 104 − 6 = 98이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#19','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C8',3,'mc','auto','같은 수 배열표에서 준서는 「가로로 5씩 커져.」, 민서는 「↘ 방향으로 105씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?',ARRAY['M4-1-u6-X09']::text[],true,'{"seq":19,"concept":"M4-1-u6-C8","difficulty":3,"kind":"mc","stem":"같은 수 배열표에서 준서는 「가로로 5씩 커져.」, 민서는 「↘ 방향으로 105씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 민서의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 준서의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 5씩, 아래로는 100씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 100 + 5 = 105씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[305,310,315,320,325],[405,410,415,420,425],[505,510,515,520,525],[605,610,615,620,625]]},"variant_rule":{"alt":[{"stem":"같은 수 배열표에서 민서는 「가로로 200씩 커져.」, 도윤이는 「↘ 방향으로 1200씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 도윤의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 민서의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 200씩, 아래로는 1000씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 1000 + 200 = 1200씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[1200,1400,1600,1800,2000],[2200,2400,2600,2800,3000],[3200,3400,3600,3800,4000],[4200,4400,4600,4800,5000]]}},{"stem":"같은 수 배열표에서 도윤이는 「가로로 25씩 커져.」, 서윤이는 「↘ 방향으로 125씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 서윤의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 도윤의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 25씩, 아래로는 100씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 100 + 25 = 125씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[200,225,250,275,300],[300,325,350,375,400],[400,425,450,475,500],[500,525,550,575,600]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#20','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C11',3,'mc','auto','사각형 16개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.',ARRAY['M4-1-u6-X13','M4-1-u6-X11']::text[],true,'{"seq":20,"concept":"M4-1-u6-C11","difficulty":3,"kind":"mc","stem":"사각형 16개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"다섯째","correct":true},{"t":"넷째","mis":"M4-1-u6-X13"},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 4개이고 3개씩 늘어나요.","4부터 3씩 세어 봐요 — 4, 7, 10, 13, 16.","16은 5번째에 나오니 다섯째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[1,3],[2,3],[2,4],[1,4]]},{"p":[[0,3],[1,3],[1,4],[0,4]]},{"p":[[2,3],[3,3],[3,4],[2,4]]},{"p":[[1,2],[2,2],[2,3],[1,3]]},{"p":[[7,3],[8,3],[8,4],[7,4]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[5,3],[6,3],[6,4],[5,4]]},{"p":[[8,3],[9,3],[9,4],[8,4]]},{"p":[[9,3],[10,3],[10,4],[9,4]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[15,3],[16,3],[16,4],[15,4]]},{"p":[[14,3],[15,3],[15,4],[14,4]]},{"p":[[13,3],[14,3],[14,4],[13,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[17,3],[18,3],[18,4],[17,4]]},{"p":[[18,3],[19,3],[19,4],[18,4]]},{"p":[[15,2],[16,2],[16,3],[15,3]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,0],[16,0],[16,1],[15,1]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형 25개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 5개이고 4개씩 늘어나요.","5부터 4씩 세어 봐요 — 5, 9, 13, 17, 21, 25.","25는 6번째에 나오니 여섯째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[1,5],[2,5],[2,6],[1,6]]},{"p":[[2,5],[3,5],[3,6],[2,6]]},{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[1,6],[2,6],[2,7],[1