INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#21','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C13',3,'mc','auto','곱셈식 배열에서 계산 결과가 8888886(8이 6개 뒤에 6)인 식은 몇째 식인가요?',ARRAY['M4-1-u6-X16','M4-1-u6-X13']::text[],true,'{"seq":21,"concept":"M4-1-u6-C13","difficulty":3,"kind":"mc","stem":"곱셈식 배열에서 계산 결과가 8888886(8이 6개 뒤에 6)인 식은 몇째 식인가요?","options":[{"t":"여섯째","correct":true},{"t":"일곱째","mis":"M4-1-u6-X16"},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"넷째","mis":"M4-1-u6-X13"}],"explanation":["첫째 81, 둘째 882, 셋째 8883 — 몇째와 같은 수만큼 8이 있고 끝에 몇째의 수가 붙어요.","8888886은 8이 6개 뒤에 6이 붙은 수예요.","그래서 여섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","9×9","=","81"],["둘째","98×9","=","882"],["셋째","987×9","=","8883"],["…","?×9","=","8888886"]]},"variant_rule":{"alt":[{"stem":"곱셈식 배열에서 계산 결과가 88888887(8이 7개 뒤에 7)인 식은 몇째 식인가요?","options":[{"t":"일곱째","correct":true},{"t":"여덟째","mis":"M4-1-u6-X16"},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"다섯째","mis":"M4-1-u6-X13"}],"explanation":["첫째 81, 둘째 882, 셋째 8883 — 몇째와 같은 수만큼 8이 있고 끝에 몇째의 수가 붙어요.","88888887은 8이 7개 뒤에 7이 붙은 수예요.","그래서 일곱째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","9×9","=","81"],["둘째","98×9","=","882"],["셋째","987×9","=","8883"],["…","?×9","=","88888887"]]}},{"stem":"곱셈식 배열에서 계산 결과가 888885(8이 5개 뒤에 5)인 식은 몇째 식인가요?","options":[{"t":"다섯째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X16"},{"t":"넷째","mis":"M4-1-u6-X13"},{"t":"셋째","mis":"M4-1-u6-X13"}],"explanation":["첫째 81, 둘째 882, 셋째 8883 — 몇째와 같은 수만큼 8이 있고 끝에 몇째의 수가 붙어요.","888885는 8이 5개 뒤에 5가 붙은 수예요.","그래서 다섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","9×9","=","81"],["둘째","98×9","=","882"],["셋째","987×9","=","8883"],["…","?×9","=","888885"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#22','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C14',3,'mc','auto','「70×4=10×28」은 양쪽에 연산이 있는 배열의 몇째 식인가요?',ARRAY['M4-1-u6-X13']::text[],true,'{"seq":22,"concept":"M4-1-u6-C14","difficulty":3,"kind":"mc","stem":"「70×4=10×28」은 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"여덟째","correct":true},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"아홉째","mis":"M4-1-u6-X13"},{"t":"여섯째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 21부터 7씩 커져요.","21에서 70이 되려면 7씩 7번 커져야 해요.","첫째에서 7번 커졌으니 여덟째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","21×4","=","3×28"],["둘째","28×4","=","4×28"]]},"variant_rule":{"alt":[{"stem":"「80×5=20×20」은 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"아홉째","correct":true},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"열째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 16부터 8씩 커져요.","16에서 80이 되려면 8씩 8번 커져야 해요.","첫째에서 8번 커졌으니 아홉째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","16×5","=","4×20"],["둘째","24×5","=","6×20"]]}},{"stem":"「99×4=33×12」는 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"열째","correct":true},{"t":"아홉째","mis":"M4-1-u6-X13"},{"t":"열한째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 18부터 9씩 커져요.","18에서 99가 되려면 9씩 9번 커져야 해요.","첫째에서 9번 커졌으니 열째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","18×4","=","6×12"],["둘째","27×4","=","9×12"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#23','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C5',4,'mc','auto','「59−14=63−10」은 옳은 식일까요? 계산하지 않고 판단해 보세요.',ARRAY['M4-1-u6-X05','M4-1-u6-X01']::text[],true,'{"seq":23,"concept":"M4-1-u6-C5","difficulty":4,"kind":"mc","stem":"「59−14=63−10」은 옳은 식일까요? 계산하지 않고 판단해 보세요.","options":[{"t":"옳지 않아요 — 빼어지는 수는 4 커지고 빼는 수는 4 작아져서 차가 8 커져요","correct":true},{"t":"옳아요 — 한쪽이 커진 만큼 다른 쪽이 작아졌어요","mis":"M4-1-u6-X05"},{"t":"옳아요 — 짝이 되는 수의 차가 모두 4예요","mis":"M4-1-u6-X05"},{"t":"옳지 않아요 — 등호 양쪽이 모두 뺄셈이라서","mis":"M4-1-u6-X01"}],"explanation":["뺄셈에서는 덧셈의 「커진 만큼 작아지면 같다」가 맞지 않아요.","빼어지는 수가 커지고 빼는 수가 작아지면 차는 더 커져요.","59−14 = 45, 63−10 = 53 — 옳지 않은 식이에요."],"variant_rule":{"alt":[{"stem":"「92−32=94−34」는 옳은 식일까요? 계산하지 않고 판단해 보세요.","options":[{"t":"옳아요 — 빼어지는 수와 빼는 수가 똑같이 2 커지면 차는 그대로예요","correct":true},{"t":"옳지 않아요 — 빼는 수가 커졌으니 다른 쪽은 작아져야 해요","mis":"M4-1-u6-X05"},{"t":"옳지 않아요 — 양쪽 수가 모두 달라요","mis":"M4-1-u6-X04"},{"t":"옳아요 — 양쪽에 모두 뺄셈이 있어서","mis":"M4-1-u6-X04"}],"explanation":["뺄셈은 덧셈과 달라요.","92 → 94, 32 → 34 — 둘 다 2 커지면 차이는 그대로예요.","92−32 = 60, 94−34 = 60 — 옳은 식이에요."],"asset":null},{"stem":"「75−38=78−35」는 옳은 식일까요? 계산하지 않고 판단해 보세요.","options":[{"t":"옳지 않아요 — 빼어지는 수는 3 커지고 빼는 수는 3 작아져서 차가 6 커져요","correct":true},{"t":"옳아요 — 한쪽이 커진 만큼 다른 쪽이 작아졌어요","mis":"M4-1-u6-X05"},{"t":"옳아요 — 짝이 되는 수의 차가 모두 3이에요","mis":"M4-1-u6-X05"},{"t":"옳지 않아요 — 등호 양쪽이 모두 뺄셈이라서","mis":"M4-1-u6-X01"}],"explanation":["뺄셈에서는 덧셈의 「커진 만큼 작아지면 같다」가 맞지 않아요.","빼어지는 수가 커지고 빼는 수가 작아지면 차는 더 커져요.","75−38 = 37, 78−35 = 43 — 옳지 않은 식이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#24','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C12',4,'sa','auto','종이 빨대로 만든 배열의 개수가 첫째부터 3, 7, 13, 21…로 늘어나요. 이렇게 계속 늘어나면 여섯째 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u6-C12","difficulty":4,"kind":"sa","stem":"종이 빨대로 만든 배열의 개수가 첫째부터 3, 7, 13, 21…로 늘어나요. 이렇게 계속 늘어나면 여섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["43"],"explanation":["늘어난 수는 4, 6, 8 — 2씩 커져요.","이어서 10, 12만큼 늘어나요.","여섯째 모양은 43개예요."],"variant_rule":{"alt":[{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 3, 9, 18, 30…로 늘어나요. 이렇게 계속 늘어나면 다섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["45"],"explanation":["늘어난 수는 6, 9, 12 — 3씩 커져요.","이어서 15만큼 늘어나요.","다섯째 모양은 45개예요."],"asset":null},{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 1, 4, 9, 16…로 늘어나요. 이렇게 계속 늘어나면 여섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["늘어난 수는 3, 5, 7 — 2씩 커져요.","이어서 9, 11만큼 늘어나요.","여섯째 모양은 36개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_b#25','math',4,1,'u6','','g4_1_math_u6_review_b','unit_review','M4-1-u6-C7',4,'essay','teacher','수의 배열 「1600, 1300, 1000, ?, 400, 100」에서 ?에 알맞은 수를 구하고, 찾은 규칙이 맞는지 검토하는 방법까지 써 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u6-C7","difficulty":4,"kind":"essay","stem":"수의 배열 「1600, 1300, 1000, ?, 400, 100」에서 ?에 알맞은 수를 구하고, 찾은 규칙이 맞는지 검토하는 방법까지 써 보세요.","answer_guide":{"answer":"예: 이웃한 두 수의 차가 300이므로 300씩 작아지는 규칙이다. ?는 1000−300=700이다. 1600→1300→1000→700→400→100 모든 수에 300씩 작아지는지 적용해 보면 다 맞으므로 규칙이 맞다.","scoring_points":["300씩 작아지는 규칙을 찾았는가","?를 700으로 구했는가","배열의 모든 수에 적용해 검토한다고 썼는가"]},"explanation":["1600 → 1300: 300 작아져요.","1000 − 300 = 700.","모든 수에 적용해 확인해요."],"asset":{"type":"numgrid","rows":[["첫째","둘째","셋째","넷째","다섯째","여섯째"],[1600,1300,1000,null,400,100]],"q":[1,3]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#1','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C3',1,'mc','auto','등호(=)와 같은 무리의 기호, 곧 두 양의 크기를 비교하는 기호는 어느 것인가요?',ARRAY['M4-1-u6-X01']::text[],true,'{"seq":1,"concept":"M4-1-u6-C3","difficulty":1,"kind":"mc","stem":"등호(=)와 같은 무리의 기호, 곧 두 양의 크기를 비교하는 기호는 어느 것인가요?","options":[{"t":">","correct":true},{"t":"+","mis":"M4-1-u6-X01"},{"t":"×","mis":"M4-1-u6-X01"},{"t":"÷","mis":"M4-1-u6-X01"}],"explanation":["등호(=)는 >, < 처럼 두 양의 크기를 비교하는 기호예요.","등호는 양쪽의 크기가 같다는 뜻이에요.","답이 어느 쪽에 있든, 양쪽이 모두 식이든 크기만 같으면 옳은 식이에요."],"variant_rule":{"alt":[{"stem":"등호(=)에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"등호 양쪽의 크기가 같으면 어떤 모양의 식이든 옳아요.","correct":true},{"t":"등호 오른쪽에는 반드시 답만 써요.","mis":"M4-1-u6-X01"},{"t":"등호 왼쪽에는 반드시 계산식을 써요.","mis":"M4-1-u6-X01"},{"t":"계산이 없는 식에는 등호를 쓸 수 없어요.","mis":"M4-1-u6-X01"}],"explanation":["등호(=)는 >, < 처럼 두 양의 크기를 비교하는 기호예요.","등호는 양쪽의 크기가 같다는 뜻이에요.","답이 어느 쪽에 있든, 양쪽이 모두 식이든 크기만 같으면 옳은 식이에요."],"asset":null},{"stem":"저울의 양쪽을 등호(=)로 나타낼 수 있는 때는 언제인가요?","options":[{"t":"저울이 수평일 때","correct":true},{"t":"왼쪽이 더 무거울 때","mis":"M4-1-u6-X04"},{"t":"오른쪽에 블록이 더 많을 때","mis":"M4-1-u6-X04"},{"t":"양쪽에 같은 수가 적혀 있을 때","mis":"M4-1-u6-X04"}],"explanation":["등호(=)는 >, < 처럼 두 양의 크기를 비교하는 기호예요.","등호는 양쪽의 크기가 같다는 뜻이에요.","답이 어느 쪽에 있든, 양쪽이 모두 식이든 크기만 같으면 옳은 식이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#2','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C1',1,'mc','auto','수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X10','M4-1-u6-X08']::text[],true,'{"seq":2,"concept":"M4-1-u6-C1","difficulty":1,"kind":"mc","stem":"수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"20씩 커져요","correct":true},{"t":"2씩 커져요","mis":"M4-1-u6-X10"},{"t":"20배씩 커져요","mis":"M4-1-u6-X08"},{"t":"20씩 작아져요","mis":"M4-1-u6-X08"}],"explanation":["가로줄을 따라 이웃한 두 수의 차를 구해 봐요.","40에서 60 — 20만큼 커졌어요.","다른 줄에서도 똑같으니 오른쪽으로 20씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[40,60,80,100,120],[42,62,82,102,122],[44,64,84,104,124],[46,66,86,106,126]]},"variant_rule":{"alt":[{"stem":"수 배열표에서 아래쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"20씩 커져요","correct":true},{"t":"40씩 커져요","mis":"M4-1-u6-X10"},{"t":"20배씩 커져요","mis":"M4-1-u6-X08"},{"t":"20씩 작아져요","mis":"M4-1-u6-X08"}],"explanation":["세로줄을 따라 이웃한 두 수의 차를 구해 봐요.","600에서 620 — 20만큼 커졌어요.","다른 줄에서도 똑같으니 아래쪽으로 20씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[600,640,680,720,760],[620,660,700,740,780],[640,680,720,760,800],[660,700,740,780,820]]}},{"stem":"이번에는 다른 그림이에요. 수 배열표에서 오른쪽으로 갈 때의 규칙은 무엇인가요?","options":[{"t":"2씩 커져요","correct":true},{"t":"4씩 커져요","mis":"M4-1-u6-X10"},{"t":"2배씩 커져요","mis":"M4-1-u6-X08"},{"t":"2씩 작아져요","mis":"M4-1-u6-X08"}],"explanation":["가로줄을 따라 이웃한 두 수의 차를 구해 봐요.","3에서 5 — 2만큼 커졌어요.","다른 줄에서도 똑같으니 오른쪽으로 2씩 커지는 규칙이에요."],"asset":{"type":"numgrid","rows":[[3,5,7,9,11],[7,9,11,13,15],[11,13,15,17,19],[15,17,19,21,23]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#3','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C4',1,'mc','auto','계산하지 않고 식이 옳은지 판단하는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X04','M4-1-u6-X01']::text[],true,'{"seq":3,"concept":"M4-1-u6-C4","difficulty":1,"kind":"mc","stem":"계산하지 않고 식이 옳은지 판단하는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"양쪽 수의 관계를 비교해요.","correct":true},{"t":"수가 더 큰 쪽이 옳다고 해요.","mis":"M4-1-u6-X04"},{"t":"등호가 가운데 있으면 옳다고 해요.","mis":"M4-1-u6-X01"},{"t":"양쪽 수의 개수가 같으면 옳다고 해요.","mis":"M4-1-u6-X04"}],"explanation":["식이 옳은지는 등호 양쪽의 크기가 같은지로 판단해요.","양쪽을 각각 계산하거나, 양쪽 수의 관계를 비교하거나, 수 모형으로 견줄 수 있어요.","한쪽만 계산하거나 겉모양만 보면 알 수 없어요."],"variant_rule":{"alt":[{"stem":"식이 옳은지 판단하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"양쪽에 같은 수가 들어 있으면 옳다고 해요.","correct":true},{"t":"양쪽을 각각 계산해서 비교해요.","mis":"M4-1-u6-X22"},{"t":"계산하지 않고 양쪽 수의 관계를 비교해요.","mis":"M4-1-u6-X22"},{"t":"식을 바꿔 써서 양쪽 모양을 같게 해 봐요.","mis":"M4-1-u6-X22"}],"explanation":["식이 옳은지는 등호 양쪽의 크기가 같은지로 판단해요.","양쪽을 각각 계산하거나, 양쪽 수의 관계를 비교하거나, 수 모형으로 견줄 수 있어요.","한쪽만 계산하거나 겉모양만 보면 알 수 없어요."],"asset":null},{"stem":"식이 옳은지 판단하는 방법으로 알맞지 않은 것은 어느 것인가요?","options":[{"t":"등호 왼쪽만 계산해 보면 돼요.","correct":true},{"t":"양쪽을 각각 계산해서 비교해요.","mis":"M4-1-u6-X22"},{"t":"양쪽 수의 관계를 비교해요.","mis":"M4-1-u6-X22"},{"t":"수 모형으로 양쪽 크기를 비교해요.","mis":"M4-1-u6-X22"}],"explanation":["식이 옳은지는 등호 양쪽의 크기가 같은지로 판단해요.","양쪽을 각각 계산하거나, 양쪽 수의 관계를 비교하거나, 수 모형으로 견줄 수 있어요.","한쪽만 계산하거나 겉모양만 보면 알 수 없어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
