INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#15','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C14',2,'mc','auto','덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X15']::text[],true,'{"seq":15,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"],["다섯째","11+13","=","24"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"17+19=36","correct":true},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"19+21=40","mis":"M4-1-u6-X13"},{"t":"17+18=35","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 17, 더하는 수는 19예요.","그래서 「17+19=36」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"],["다섯째","13+15","=","28"]]}},{"stem":"덧셈식 배열의 여덟째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","여덟째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#16','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C15',2,'sa','auto','날개 수가 첫째부터 「3, 9, 15, 21…」로 늘어나는 배열이에요. 일곱째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u6-C15","difficulty":2,"kind":"sa","stem":"날개 수가 첫째부터 「3, 9, 15, 21…」로 늘어나는 배열이에요. 일곱째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["39"],"explanation":["날개가 6개씩 늘어나요.","넷째 21개에서 3번 더 늘어나요.","21 + 6 × 3 = 39 — 39개예요."],"variant_rule":{"alt":[{"stem":"날개 수가 첫째부터 「2, 8, 14, 20…」으로 늘어나는 배열이에요. 여덟째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["날개가 6개씩 늘어나요.","넷째 20개에서 4번 더 늘어나요.","20 + 6 × 4 = 44 — 44개예요."],"asset":null},{"stem":"날개 수가 첫째부터 「2, 4, 6, 8…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["날개가 2개씩 늘어나요.","넷째 8개에서 1번 더 늘어나요.","8 + 2 × 1 = 10 — 10개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#17','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C4',3,'mc','auto','시우가 계산한 차례대로 「27+24=51+5=56」이라고 썼어요. 이 식은 옳을까요?',ARRAY['M4-1-u6-X02','M4-1-u6-X04']::text[],true,'{"seq":17,"concept":"M4-1-u6-C4","difficulty":3,"kind":"mc","stem":"시우가 계산한 차례대로 「27+24=51+5=56」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 27+24는 51인데, 51+5인 56과는 크기가 달라서","correct":true},{"t":"옳아요 — 27+24를 계산하면 51이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 51+5를 계산하면 56이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","27+24 = 51이고 51+5 = 56 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「27+24=51」, 「51+5=56」처럼 따로 써요."],"variant_rule":{"alt":[{"stem":"은우가 계산한 차례대로 「40+13=53+5=58」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 40+13은 53인데, 53+5인 58과는 크기가 달라서","correct":true},{"t":"옳아요 — 40+13을 계산하면 53이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 53+5를 계산하면 58이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","40+13 = 53이고 53+5 = 58 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「40+13=53」, 「53+5=58」처럼 따로 써요."],"asset":null},{"stem":"하랑이가 계산한 차례대로 「51+15=66+7=73」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 51+15는 66인데, 66+7인 73과는 크기가 달라서","correct":true},{"t":"옳아요 — 51+15를 계산하면 66이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 66+7을 계산하면 73이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","51+15 = 66이고 66+7 = 73 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「51+15=66」, 「66+7=73」처럼 따로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#18','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C6',3,'mc','auto','「42+46=□+7」에서 도윤이는 「42+46은 88이니까 □는 88이야!」라고 했어요. 도윤의 생각이 틀린 까닭은 무엇인가요?',ARRAY['M4-1-u6-X04','M4-1-u6-X03','M4-1-u6-X01']::text[],true,'{"seq":18,"concept":"M4-1-u6-C6","difficulty":3,"kind":"mc","stem":"「42+46=□+7」에서 도윤이는 「42+46은 88이니까 □는 88이야!」라고 했어요. 도윤의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 88이면 □+7은 95가 되어 88인 42+46과 크기가 달라져요","correct":true},{"t":"42+46은 88이 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+7)가 88이 되어야 해요.","도윤처럼 □에 88을 넣으면 □+7 = 95예요.","바른 □는 88 − 7 = 81이에요."],"variant_rule":{"alt":[{"stem":"「46+58=□+6」에서 서윤이는 「46+58은 104이니까 □는 104야!」라고 했어요. 서윤의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 104이면 □+6은 110이 되어 104인 46+58과 크기가 달라져요","correct":true},{"t":"46+58은 104가 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+6)가 104가 되어야 해요.","서윤처럼 □에 104를 넣으면 □+6 = 110이에요.","바른 □는 104 − 6 = 98이에요."],"asset":null},{"stem":"「37+47=□+8」에서 시우는 「37+47은 84이니까 □는 84야!」라고 했어요. 시우의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 84이면 □+8은 92가 되어 84인 37+47과 크기가 달라져요","correct":true},{"t":"37+47은 84가 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+8)가 84가 되어야 해요.","시우처럼 □에 84를 넣으면 □+8 = 92예요.","바른 □는 84 − 8 = 76이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_c#19','math',4,1,'u6','','g4_1_math_u6_review_c','unit_review','M4-1-u6-C8',3,'mc','auto','같은 수 배열표에서 민서는 「가로로 200씩 커져.」, 도윤이는 「↘ 방향으로 1200씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?',ARRAY['M4-1-u6-X09']::text[],true,'{"seq":19,"concept":"M4-1-u6-C8","difficulty":3,"kind":"mc","stem":"같은 수 배열표에서 민서는 「가로로 200씩 커져.」, 도윤이는 「↘ 방향으로 1200씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 도윤의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 민서의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 200씩, 아래로는 1000씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 1000 + 200 = 1200씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[1200,1400,1600,1800,2000],[2200,2400,2600,2800,3000],[3200,3400,3600,3800,4000],[4200,4400,4600,4800,5000]]},"variant_rule":{"alt":[{"stem":"같은 수 배열표에서 도윤이는 「가로로 25씩 커져.」, 서윤이는 「↘ 방향으로 125씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 서윤의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 도윤의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 25씩, 아래로는 100씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 100 + 25 = 125씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[200,225,250,275,300],[300,325,350,375,400],[400,425,450,475,500],[500,525,550,575,600]]}},{"stem":"같은 수 배열표에서 서윤이는 「가로로 50씩 커져.」, 시우는 「↘ 방향으로 1050씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 시우의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 서윤의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 50씩, 아래로는 1000씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 1000 + 50 = 1050씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[1200,1250,1300,1350,1400],[2200,2250,2300,2350,2400],[3200,3250,3300,3350,3400],[4200,4250,4300,4350,4400]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
