— 8, 10, 12, 14, 16, 18, 20.","20은 7번째에 나오니 일곱째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[2,2],[3,2],[3,3],[2,3]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[5,0],[6,0],[6,1],[5,1]]},{"p":[[5,1],[6,1],[6,2],[5,2]]},{"p":[[5,2],[6,2],[6,3],[5,3]]},{"p":[[8,0],[9,0],[9,1],[8,1]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[11,0],[12,0],[12,1],[11,1]]},{"p":[[11,1],[12,1],[12,2],[11,2]]},{"p":[[11,2],[12,2],[12,3],[11,3]]},{"p":[[15,0],[16,0],[16,1],[15,1]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,2],[16,2],[16,3],[15,3]]},{"p":[[12,0],[13,0],[13,1],[12,1]]},{"p":[[12,1],[13,1],[13,2],[12,2]]},{"p":[[13,0],[14,0],[14,1],[13,1]]},{"p":[[13,1],[14,1],[14,2],[13,2]]},{"p":[[14,0],[15,0],[15,1],[14,1]]},{"p":[[14,1],[15,1],[15,2],[14,2]]}],"u":16}},{"stem":"사각형 15개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"아홉째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 3개이고 2개씩 늘어나요.","3부터 2씩 세어 봐요 — 3, 5, 7, 9, 11, 13, 15.","15는 7번째에 나오니 일곱째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EX