INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#5','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C9',1,'mc','auto','사각형으로 만든 가로 모양 배열이에요. 왼쪽부터 차례로 첫째, 둘째, 셋째, 넷째 모양이에요. 규칙으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X08','M4-1-u6-X11']::text[],true,'{"seq":5,"concept":"M4-1-u6-C9","difficulty":1,"kind":"mc","stem":"사각형으로 만든 가로 모양 배열이에요. 왼쪽부터 차례로 첫째, 둘째, 셋째, 넷째 모양이에요. 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"사각형이 2개씩 늘어나요","correct":true},{"t":"사각형이 2배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"사각형이 2개씩 줄어들어요","mis":"M4-1-u6-X08"},{"t":"사각형이 3개씩 늘어나요","mis":"M4-1-u6-X11"}],"explanation":["사각형 수를 세면 3, 5, 7, 9예요.","이웃한 두 모양의 차가 모두 2예요.","그래서 사각형이 2개씩 늘어나는 규칙이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]},{"p":[[12,0],[13,0],[13,1],[12,1]]},{"p":[[12,1],[13,1],[13,2],[12,2]]},{"p":[[12,2],[13,2],[13,3],[12,3]]},{"p":[[13,1],[14,1],[14,2],[13,2]]},{"p":[[13,2],[14,2],[14,3],[13,3]]},{"p":[[14,1],[15,1],[15,2],[14,2]]},{"p":[[14,2],[15,2],[15,3],[14,3]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,2],[16,2],[16,3],[15,3]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형으로 만든 십자 모양 배열이에요. 왼쪽부터 차례로 첫째, 둘째, 셋째, 넷째 모양이에요. 규칙으로 알맞은 것은 어느 것인가요?","options":[{"t":"사각형이 4개씩 늘어나요","correct":true},{"t":"사각형이 4배씩 늘어나요","mis":"M4-1-u6-X08"},{"t":"사각형이 4개씩 줄어들어요","mis":"M4-1-u6-X08"},{"t":"사각형이 6개씩 늘어나요","mis":"M4-1-u6-X11"}],"explanation":["사각형 수를 세면 4,