INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#7','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C13',1,'mc','auto','곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?',ARRAY['M4-1-u6-X08','M4-1-u6-X07','M4-1-u6-X17']::text[],true,'{"seq":7,"concept":"M4-1-u6-C13","difficulty":1,"kind":"mc","stem":"곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"2와 2 사이에 4가 1개씩 늘어나요","correct":true},{"t":"결과가 2배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 2200씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 242, 2442, 24442, 244442.","2와 2 사이의 4가 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×2","=","242"],["둘째","1221×2","=","2442"],["셋째","12221×2","=","24442"]]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"4와 4 사이에 8이 1개씩 늘어나요","correct":true},{"t":"결과가 4배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 4400씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 484, 4884, 48884, 488884.","4와 4 사이의 8이 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×4","=","484"],["둘째","1221×4","=","4884"],["셋째","12221×4","=","48884"],["넷째","122221×4","=","488884"]]}},{"stem":"이번에는 다른 그림이에요. 곱셈식 배열에서 계산 결과의 규칙은 무엇인가요?","options":[{"t":"3과 3 사이에 6이 1개씩 늘어나요","correct":true},{"t":"결과가 3배씩 커져요","mis":"M4-1-u6-X08"},{"t":"결과가 3300씩 커져요","mis":"M4-1-u6-X07"},{"t":"결과의 자리 수가 그대로예요","mis":"M4-1-u6-X17"}],"explanation":["결과를 차례로 보면 363, 3663, 36663, 366663.","3과 3 사이의 6이 하나씩 늘어나고 자리 수도 하나씩 늘어요.","처음 두 결과의 차만 보고 「얼마씩 커진다」고 하면 다음 결과와 맞지 않아요."],"asset":{"type":"expr_grid","rows":[["첫째","121×3","=","363"],["둘째","1221×3","=","3663"],["셋째","12221×3","=","36663"],["넷째","122221×3","=","366663"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#8','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C15',1,'mc','auto','팔 한 개는 12g이에요. 팔 5개와 바퀴 6개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?',ARRAY['M4-1-u6-X20']::text[],true,'{"seq":8,"concept":"M4-1-u6-C15","difficulty":1,"kind":"mc","stem":"팔 한 개는 12g이에요. 팔 5개와 바퀴 6개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"10g","correct":true},{"t":"60g","mis":"M4-1-u6-X20"},{"t":"12g","mis":"M4-1-u6-X20"},{"t":"20g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 5개는 12+12+12+12+12 = 60g이에요.","바퀴 6개가 60g이니 바퀴 1개는 60 ÷ 6 = 10g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 5개","icon":"🔧"},"r":{"name":"바퀴 6개","icon":"⚙️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"팔 한 개는 10g이에요. 팔 3개와 바퀴 2개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"15g","correct":true},{"t":"30g","mis":"M4-1-u6-X20"},{"t":"10g","mis":"M4-1-u6-X20"},{"t":"20g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 3개는 10+10+10 = 30g이에요.","바퀴 2개가 30g이니 바퀴 1개는 30 ÷ 2 = 15g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 3개","icon":"🔧"},"r":{"name":"바퀴 2개","icon":"⚙️"},"down":"eq"}]}},{"stem":"팔 한 개는 12g이에요. 팔 2개와 바퀴 3개가 수평이에요. 바퀴 1개의 무게는 몇 g인가요?","options":[{"t":"8g","correct":true},{"t":"24g","mis":"M4-1-u6-X20"},{"t":"12g","mis":"M4-1-u6-X20"},{"t":"16g","mis":"M4-1-u6-X20"}],"explanation":["저울이 수평이면 양쪽 무게가 같아요.","팔 2개는 12+12 = 24g이에요.","바퀴 3개가 24g이니 바퀴 1개는 24 ÷ 3 = 8g이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"팔 2개","icon":"🔧"},"r":{"name":"바퀴 3개","icon":"⚙️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#9','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C2',2,'sa','auto','저울이 수평을 이루고 있어요. 「□+27=18+30」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":9,"concept":"M4-1-u6-C2","difficulty":2,"kind":"sa","stem":"저울이 수평을 이루고 있어요. 「□+27=18+30」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["수평이면 양쪽의 크기가 같아요.","오른쪽 18+30 = 48이에요.","□+27 전체가 48이 되려면 □ = 48 − 27 = 21이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"□+27","icon":"⚖️"},"r":{"name":"18+30","icon":"⚖️"},"down":"eq"}]},"variant_rule":{"alt":[{"stem":"저울이 수평을 이루고 있어요. 「40+□=30×2」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["20"],"explanation":["수평이면 양쪽의 크기가 같아요.","오른쪽 30×2 = 60이에요.","40+□ 전체가 60이 되려면 □ = 60 − 40 = 20이에요."],"asset":{"type":"balance","scales":[{"l":{"name":"40+□","icon":"⚖️"},"r":{"name":"30×2","icon":"⚖️"},"down":"eq"}]}},{"stem":"저울이 수평을 이루고 있어요. 「□+25=20×3」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["35"],"explanation":["수평이면 양쪽의 크기가 같아요.","오른쪽 20×3 = 60이에요.","□+25 전체가 60이 되려면 □ = 60 − 25 = 35예요."],"asset":{"type":"balance","scales":[{"l":{"name":"□+25","icon":"⚖️"},"r":{"name":"20×3","icon":"⚖️"},"down":"eq"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#10','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C5',2,'mc','auto','「44+82=46+80」에서 44는 46보다 2 작고 82는 80보다 2 커요. 이 식은 어떨까요?',ARRAY['M4-1-u6-X04','M4-1-u6-X05']::text[],true,'{"seq":10,"concept":"M4-1-u6-C5","difficulty":2,"kind":"mc","stem":"「44+82=46+80」에서 44는 46보다 2 작고 82는 80보다 2 커요. 이 식은 어떨까요?","options":[{"t":"옳아요 — 한쪽이 2 큰 만큼 다른 쪽이 2 작아서 크기가 같아요","correct":true},{"t":"옳지 않아요 — 양쪽의 수가 서로 달라요","mis":"M4-1-u6-X04"},{"t":"옳지 않아요 — 2만큼 차이가 나요","mis":"M4-1-u6-X05"},{"t":"계산해 보기 전에는 절대 알 수 없어요","mis":"M4-1-u6-X04"}],"explanation":["짝이 되는 두 수의 변화를 함께 봐요.","44와 46은 2 차이, 82와 80도 2 차이인데 방향이 반대예요.","커진 만큼 작아졌으니 양쪽 크기가 같아요 — 옳은 식이에요."],"variant_rule":{"alt":[{"stem":"「18+37=15+40」에서 18은 15보다 3 크고 37은 40보다 3 작아요. 이 식은 어떨까요?","options":[{"t":"옳아요 — 한쪽이 3 큰 만큼 다른 쪽이 3 작아서 크기가 같아요","correct":true},{"t":"옳지 않아요 — 양쪽의 수가 서로 달라요","mis":"M4-1-u6-X04"},{"t":"옳지 않아요 — 3만큼 차이가 나요","mis":"M4-1-u6-X05"},{"t":"계산해 보기 전에는 절대 알 수 없어요","mis":"M4-1-u6-X04"}],"explanation":["짝이 되는 두 수의 변화를 함께 봐요.","18과 15는 3 차이, 37과 40도 3 차이인데 방향이 반대예요.","커진 만큼 작아졌으니 양쪽 크기가 같아요 — 옳은 식이에요."],"asset":null},{"stem":"「24+42=26+40」에서 24는 26보다 2 작고 42는 40보다 2 커요. 이 식은 어떨까요?","options":[{"t":"옳아요 — 한쪽이 2 큰 만큼 다른 쪽이 2 작아서 크기가 같아요","correct":true},{"t":"옳지 않아요 — 양쪽의 수가 서로 달라요","mis":"M4-1-u6-X04"},{"t":"옳지 않아요 — 2만큼 차이가 나요","mis":"M4-1-u6-X05"},{"t":"계산해 보기 전에는 절대 알 수 없어요","mis":"M4-1-u6-X04"}],"explanation":["짝이 되는 두 수의 변화를 함께 봐요.","24와 26은 2 차이, 42와 40도 2 차이인데 방향이 반대예요.","커진 만큼 작아졌으니 양쪽 크기가 같아요 — 옳은 식이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#11','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C6',2,'sa','auto','「□+26=14+18」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":11,"concept":"M4-1-u6-C6","difficulty":2,"kind":"sa","stem":"「□+26=14+18」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["14+18 = 32예요.","□가 든 쪽 전체가 32가 되어야 해요.","□ = 32 − 26 = 6이에요."],"variant_rule":{"alt":[{"stem":"「57+46=□+20」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["83"],"explanation":["57+46 = 103이에요.","□가 든 쪽 전체가 103이 되어야 해요.","□ = 103 − 20 = 83이에요."],"asset":null},{"stem":"「14+20=28+□」에서 □에 알맞은 수는 무엇인가요? 숫자로 쓰세요.","answer":["6"],"explanation":["14+20 = 34예요.","□가 든 쪽 전체가 34가 되어야 해요.","□ = 34 − 28 = 6이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#12','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C7',2,'sa','auto','수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.','{}'::text[],true,'{"seq":12,"concept":"M4-1-u6-C7","difficulty":2,"kind":"sa","stem":"수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["18"],"explanation":["162 → 54 처럼 앞의 수를 3으로 나눈 몫이 다음 수예요.","162, 54, 6, 2는 모두 3으로 나누면 다음 수가 돼요.","54 ÷ 3 = 18 — ?는 18이에요."],"asset":{"type":"numgrid","rows":[["첫째","둘째","셋째","넷째","다섯째"],[162,54,null,6,2]],"q":[1,2]},"variant_rule":{"alt":[{"stem":"이번에는 다른 그림이에요. 수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["128"],"explanation":["256 → … → 64 — 얼마씩 빼는 게 아니라 나누는 규칙이에요.","256, 64, 32, 16은 모두 2로 나누면 다음 수가 돼요.","256 ÷ 2 = 128 — ?는 128이에요."],"asset":{"type":"numgrid","rows":[["첫째","둘째","셋째","넷째","다섯째"],[256,null,64,32,16]],"q":[1,1]}},{"stem":"이번에는 다른 그림이에요. 수의 배열에서 규칙을 찾아 ?에 알맞은 수를 구하세요. 숫자로 쓰세요.","answer":["10"],"explanation":["810 → 270 처럼 앞의 수를 3으로 나눈 몫이 다음 수예요.","810, 270, 90, 30은 모두 3으로 나누면 다음 수가 돼요.","30 ÷ 3 = 10 — ?는 10이에요."],"asset":{"type":"numgrid","rows":[["첫째","둘째","셋째","넷째","다섯째"],[810,270,90,30,null]],"q":[1,4]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#13','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C10',2,'mc','auto','피라미드 모양 쌓기나무 배열의 여섯째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?',ARRAY['M4-1-u6-X15','M4-1-u6-X13']::text[],true,'{"seq":13,"concept":"M4-1-u6-C10","difficulty":2,"kind":"mc","stem":"피라미드 모양 쌓기나무 배열의 여섯째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5+7+9+11","correct":true},{"t":"1+2+3+4+5+6","mis":"M4-1-u6-X15"},{"t":"6+6+6+6+6+6","mis":"M4-1-u6-X15"},{"t":"1+3+5+7+9","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","여섯째 모양은 6층 — 1+3+5+7+9+11.","1+3+5+7+9+11 = 36개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]},"variant_rule":{"alt":[{"stem":"피라미드 모양 쌓기나무 배열의 셋째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5","correct":true},{"t":"1+2+3","mis":"M4-1-u6-X15"},{"t":"3+3+3","mis":"M4-1-u6-X15"},{"t":"1+3","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","셋째 모양은 3층 — 1+3+5.","1+3+5 = 9개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}},{"stem":"피라미드 모양 쌓기나무 배열의 넷째 모양을 식으로 바르게 나타낸 것은 어느 것인가요?","options":[{"t":"1+3+5+7","correct":true},{"t":"1+2+3+4","mis":"M4-1-u6-X15"},{"t":"4+4+4+4","mis":"M4-1-u6-X15"},{"t":"1+3+5","mis":"M4-1-u6-X13"}],"explanation":["맨 위 1개에서 시작해 아래로 3개, 5개, 7개…씩 늘어나요.","넷째 모양은 4층 — 1+3+5+7.","1+3+5+7 = 16개예요."],"asset":{"type":"stack","stages":[[[0,0,0,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[1,0,1,"y"]],[[0,0,0,0],[1,0,0,0],[2,0,0,0],[3,0,0,0],[4,0,0,0],[1,0,1,0],[2,0,1,0],[3,0,1,0],[2,0,2,"y"]]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#14','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C12',2,'mc','auto','도윤이와 서윤이가 만든 사각형 배열이에요(왼쪽 셋은 도윤, 오른쪽 셋은 서윤의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?',ARRAY['M4-1-u6-X14','M4-1-u6-X09']::text[],true,'{"seq":14,"concept":"M4-1-u6-C12","difficulty":2,"kind":"mc","stem":"도윤이와 서윤이가 만든 사각형 배열이에요(왼쪽 셋은 도윤, 오른쪽 셋은 서윤의 첫째·둘째·셋째). 모양은 다르지만 개수는 둘 다 3, 5, 7이에요. 어떻게 판단하나요?","options":[{"t":"개수가 같게 늘어나니 같은 규칙이에요","correct":true},{"t":"모양이 다르니 규칙도 달라요","mis":"M4-1-u6-X14"},{"t":"한 사람은 반드시 틀렸어요","mis":"M4-1-u6-X09"},{"t":"모양이 다르면 견줄 수 없어요","mis":"M4-1-u6-X14"}],"explanation":["두 배열 모두 3, 5, 7 — 2개씩 늘어나요.","모양은 달라도 개수가 같게 변해요.","그래서 같은 규칙으로 만든 다른 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,3],[1,3],[1,4],[0,4]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[1,3],[2,3],[2,4],[1,4]]},{"p":[[4,3],[5,3],[5,4],[4,4]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[5,3],[6,3],[6,4],[5,4]]},{"p":[[6,3],[7,3],[7,4],[6,4]]},{"p":[[9,3],[10,3],[10,4],[9,4]]},{"p":[[9,2],[10,2],[10,3],[9,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,0],[10,0],[10,1],[9,1]]},{"p":[[10,3],[11,3],[11,4],[10,4]]},{"p":[[11,3],[12,3],[12,4],[11,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]},{"p":[[16,5],[17,5],[17,6],[16,6]]},{"p":[[16,4],[17,4],[17,5],[16,5]]},{"p":[[16,6],[17,6],[17,7],[16,7]]},{"p":[[19,4],[20,4],[20,5],[19,5]]},{"p":[[19,3],[20,3],[20,4],[19,4]]},{"p":[[19,2],[20,2],[20,3],[19,3]]},{"p":[[19,5],[20,5],[20,6],[19,6]]},{"p":[[19,6],[20,6],[20,7],[19,7]]},{"p":[[22,3],[23,3],[23,4],[22,4]]},{"p":[[22,2],[23,2],[23,3],[22,3]]},{"p":[[22,1],[23,1],[23,2],[22,2]]},{"p":[[22,0],[23,0],[23,1],[22,1]]},{"p":[[22,4],[23,4],[23,5],[22,5]]},{"p":[[22,5],[23,5],[23,6],[22,6]]},{"p":[[22,6],[23,6],[23,7],[22,7]]}],"u":12},"variant_rule":{"a