INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#15','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C14',2,'mc','auto','덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?',ARRAY['M4-1-u6-X13','M4-1-u6-X15']::text[],true,'{"seq":15,"concept":"M4-1-u6-C14","difficulty":2,"kind":"mc","stem":"덧셈식 배열의 일곱째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"17+19=36","correct":true},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"19+21=40","mis":"M4-1-u6-X13"},{"t":"17+18=35","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","일곱째 식의 더해지는 수는 17, 더하는 수는 19예요.","그래서 「17+19=36」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","5+7","=","12"],["둘째","7+9","=","16"],["셋째","9+11","=","20"],["넷째","11+13","=","24"],["다섯째","13+15","=","28"]]},"variant_rule":{"alt":[{"stem":"덧셈식 배열의 여덟째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"15+17=32","correct":true},{"t":"13+15=28","mis":"M4-1-u6-X13"},{"t":"17+19=36","mis":"M4-1-u6-X13"},{"t":"15+16=31","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","여덟째 식의 더해지는 수는 15, 더하는 수는 17이에요.","그래서 「15+17=32」예요."],"asset":{"type":"expr_grid","rows":[["첫째","1+3","=","4"],["둘째","3+5","=","8"],["셋째","5+7","=","12"],["넷째","7+9","=","16"],["다섯째","9+11","=","20"]]}},{"stem":"덧셈식 배열의 여덟째 식으로 알맞은 것은 어느 것인가요?","options":[{"t":"17+19=36","correct":true},{"t":"15+17=32","mis":"M4-1-u6-X13"},{"t":"19+21=40","mis":"M4-1-u6-X13"},{"t":"17+18=35","mis":"M4-1-u6-X15"}],"explanation":["더해지는 수도 2씩, 더하는 수도 2씩 커져요.","여덟째 식의 더해지는 수는 17, 더하는 수는 19예요.","그래서 「17+19=36」이에요."],"asset":{"type":"expr_grid","rows":[["첫째","3+5","=","8"],["둘째","5+7","=","12"],["셋째","7+9","=","16"],["넷째","9+11","=","20"],["다섯째","11+13","=","24"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#16','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C15',2,'sa','auto','날개 수가 첫째부터 「2, 8, 14, 20…」으로 늘어나는 배열이에요. 여덟째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":16,"concept":"M4-1-u6-C15","difficulty":2,"kind":"sa","stem":"날개 수가 첫째부터 「2, 8, 14, 20…」으로 늘어나는 배열이에요. 여덟째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["44"],"explanation":["날개가 6개씩 늘어나요.","넷째 20개에서 4번 더 늘어나요.","20 + 6 × 4 = 44 — 44개예요."],"variant_rule":{"alt":[{"stem":"날개 수가 첫째부터 「2, 4, 6, 8…」로 늘어나는 배열이에요. 다섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["10"],"explanation":["날개가 2개씩 늘어나요.","넷째 8개에서 1번 더 늘어나요.","8 + 2 × 1 = 10 — 10개예요."],"asset":null},{"stem":"날개 수가 첫째부터 「3, 6, 9, 12…」로 늘어나는 배열이에요. 여섯째 모양을 만들 때 필요한 날개는 몇 개인가요? 숫자로 쓰세요.","answer":["18"],"explanation":["날개가 3개씩 늘어나요.","넷째 12개에서 2번 더 늘어나요.","12 + 3 × 2 = 18 — 18개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#17','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C4',3,'mc','auto','은우가 계산한 차례대로 「40+13=53+5=58」이라고 썼어요. 이 식은 옳을까요?',ARRAY['M4-1-u6-X02','M4-1-u6-X04']::text[],true,'{"seq":17,"concept":"M4-1-u6-C4","difficulty":3,"kind":"mc","stem":"은우가 계산한 차례대로 「40+13=53+5=58」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 40+13은 53인데, 53+5인 58과는 크기가 달라서","correct":true},{"t":"옳아요 — 40+13을 계산하면 53이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 53+5를 계산하면 58이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","40+13 = 53이고 53+5 = 58 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「40+13=53」, 「53+5=58」처럼 따로 써요."],"variant_rule":{"alt":[{"stem":"하랑이가 계산한 차례대로 「51+15=66+7=73」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 51+15는 66인데, 66+7인 73과는 크기가 달라서","correct":true},{"t":"옳아요 — 51+15를 계산하면 66이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 66+7을 계산하면 73이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","51+15 = 66이고 66+7 = 73 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「51+15=66」, 「66+7=73」처럼 따로 써요."],"asset":null},{"stem":"지아가 계산한 차례대로 「30+27=57+6=63」이라고 썼어요. 이 식은 옳을까요?","options":[{"t":"옳지 않아요 — 30+27은 57인데, 57+6인 63과는 크기가 달라서","correct":true},{"t":"옳아요 — 30+27을 계산하면 57이니까","mis":"M4-1-u6-X02"},{"t":"옳아요 — 57+6을 계산하면 63이니까","mis":"M4-1-u6-X02"},{"t":"옳지 않아요 — 식이 너무 길어서","mis":"M4-1-u6-X04"}],"explanation":["등호로 이은 양쪽은 모두 크기가 같아야 해요.","30+27 = 57이고 57+6 = 63 — 두 값이 달라요.","계산한 결과를 등호로 이어 쓰면 안 돼요 — 「30+27=57」, 「57+6=63」처럼 따로 써요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#18','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C6',3,'mc','auto','「46+58=□+6」에서 서윤이는 「46+58은 104이니까 □는 104야!」라고 했어요. 서윤의 생각이 틀린 까닭은 무엇인가요?',ARRAY['M4-1-u6-X04','M4-1-u6-X03','M4-1-u6-X01']::text[],true,'{"seq":18,"concept":"M4-1-u6-C6","difficulty":3,"kind":"mc","stem":"「46+58=□+6」에서 서윤이는 「46+58은 104이니까 □는 104야!」라고 했어요. 서윤의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 104이면 □+6은 110이 되어 104인 46+58과 크기가 달라져요","correct":true},{"t":"46+58은 104가 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+6)가 104가 되어야 해요.","서윤처럼 □에 104를 넣으면 □+6 = 110이에요.","바른 □는 104 − 6 = 98이에요."],"variant_rule":{"alt":[{"stem":"「37+47=□+8」에서 시우는 「37+47은 84이니까 □는 84야!」라고 했어요. 시우의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 84이면 □+8은 92가 되어 84인 37+47과 크기가 달라져요","correct":true},{"t":"37+47은 84가 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+8)가 84가 되어야 해요.","시우처럼 □에 84를 넣으면 □+8 = 92예요.","바른 □는 84 − 8 = 76이에요."],"asset":null},{"stem":"「44+34=□+4」에서 은우는 「44+34는 78이니까 □는 78이야!」라고 했어요. 은우의 생각이 틀린 까닭은 무엇인가요?","options":[{"t":"□가 78이면 □+4는 82가 되어 78인 44+34와 크기가 달라져요","correct":true},{"t":"44+34는 78이 아니에요","mis":"M4-1-u6-X04"},{"t":"□에는 두 자리 수를 넣을 수 없어요","mis":"M4-1-u6-X03"},{"t":"등호 오른쪽에는 □가 올 수 없어요","mis":"M4-1-u6-X01"}],"explanation":["□가 든 쪽 전체(□+4)가 78이 되어야 해요.","은우처럼 □에 78을 넣으면 □+4 = 82예요.","바른 □는 78 − 4 = 74예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#19','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C8',3,'mc','auto','같은 수 배열표에서 도윤이는 「가로로 25씩 커져.」, 서윤이는 「↘ 방향으로 125씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?',ARRAY['M4-1-u6-X09']::text[],true,'{"seq":19,"concept":"M4-1-u6-C8","difficulty":3,"kind":"mc","stem":"같은 수 배열표에서 도윤이는 「가로로 25씩 커져.」, 서윤이는 「↘ 방향으로 125씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 서윤의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 도윤의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 25씩, 아래로는 100씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 100 + 25 = 125씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[200,225,250,275,300],[300,325,350,375,400],[400,425,450,475,500],[500,525,550,575,600]]},"variant_rule":{"alt":[{"stem":"같은 수 배열표에서 서윤이는 「가로로 50씩 커져.」, 시우는 「↘ 방향으로 1050씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 시우의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 서윤의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 50씩, 아래로는 1000씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 1000 + 50 = 1050씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[1200,1250,1300,1350,1400],[2200,2250,2300,2350,2400],[3200,3250,3300,3350,3400],[4200,4250,4300,4350,4400]]}},{"stem":"같은 수 배열표에서 시우는 「가로로 2씩 커져.」, 은우는 「↘ 방향으로 12씩 커져.」라고 했어요. 바르게 판단한 것은 어느 것인가요?","options":[{"t":"방향이 다르면 규칙도 달라요 — 둘 다 맞아요","correct":true},{"t":"규칙은 하나뿐이라서 한 명은 틀렸어요","mis":"M4-1-u6-X09"},{"t":"수가 더 큰 은우의 규칙만 맞아요","mis":"M4-1-u6-X09"},{"t":"먼저 말한 시우의 규칙만 맞아요","mis":"M4-1-u6-X09"}],"explanation":["가로로는 2씩, 아래로는 10씩 커져요.","↘ 방향은 아래로 한 칸 + 오른쪽으로 한 칸이라 10 + 2 = 12씩 커져요.","방향과 기준이 다르면 규칙도 달라요 — 둘 다 맞아요."],"asset":{"type":"numgrid","rows":[[14,16,18,20,22],[24,26,28,30,32],[34,36,38,40,42],[44,46,48,50,52]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#20','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C11',3,'mc','auto','사각형 20개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.',ARRAY['M4-1-u6-X13','M4-1-u6-X11']::text[],true,'{"seq":20,"concept":"M4-1-u6-C11","difficulty":3,"kind":"mc","stem":"사각형 20개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"열째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 8개이고 2개씩 늘어나요.","8부터 2씩 세어 봐요 — 8, 10, 12, 14, 16, 18, 20.","20은 7번째에 나오니 일곱째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[2,0],[3,0],[3,1],[2,1]]},{"p":[[2,1],[3,1],[3,2],[2,2]]},{"p":[[2,2],[3,2],[3,3],[2,3]]},{"p":[[1,0],[2,0],[2,1],[1,1]]},{"p":[[1,1],[2,1],[2,2],[1,2]]},{"p":[[5,0],[6,0],[6,1],[5,1]]},{"p":[[5,1],[6,1],[6,2],[5,2]]},{"p":[[5,2],[6,2],[6,3],[5,3]]},{"p":[[8,0],[9,0],[9,1],[8,1]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[6,0],[7,0],[7,1],[6,1]]},{"p":[[6,1],[7,1],[7,2],[6,2]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[11,0],[12,0],[12,1],[11,1]]},{"p":[[11,1],[12,1],[12,2],[11,2]]},{"p":[[11,2],[12,2],[12,3],[11,3]]},{"p":[[15,0],[16,0],[16,1],[15,1]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,2],[16,2],[16,3],[15,3]]},{"p":[[12,0],[13,0],[13,1],[12,1]]},{"p":[[12,1],[13,1],[13,2],[12,2]]},{"p":[[13,0],[14,0],[14,1],[13,1]]},{"p":[[13,1],[14,1],[14,2],[13,2]]},{"p":[[14,0],[15,0],[15,1],[14,1]]},{"p":[[14,1],[15,1],[15,2],[14,2]]}],"u":16},"variant_rule":{"alt":[{"stem":"사각형 15개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"아홉째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 3개이고 2개씩 늘어나요.","3부터 2씩 세어 봐요 — 3, 5, 7, 9, 11, 13, 15.","15는 7번째에 나오니 일곱째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[0,0],[1,0],[1,1],[0,1]]},{"p":[[0,1],[1,1],[1,2],[0,2]]},{"p":[[0,2],[1,2],[1,3],[0,3]]},{"p":[[3,0],[4,0],[4,1],[3,1]]},{"p":[[3,1],[4,1],[4,2],[3,2]]},{"p":[[3,2],[4,2],[4,3],[3,3]]},{"p":[[4,1],[5,1],[5,2],[4,2]]},{"p":[[4,2],[5,2],[5,3],[4,3]]},{"p":[[7,0],[8,0],[8,1],[7,1]]},{"p":[[7,1],[8,1],[8,2],[7,2]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[8,1],[9,1],[9,2],[8,2]]},{"p":[[8,2],[9,2],[9,3],[8,3]]},{"p":[[9,1],[10,1],[10,2],[9,2]]},{"p":[[9,2],[10,2],[10,3],[9,3]]}],"u":16}},{"stem":"사각형 24개로 만든 모양은 몇째 모양인가요? 왼쪽부터 차례로 첫째, 둘째, 셋째 모양이에요.","options":[{"t":"여섯째","correct":true},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X11"}],"explanation":["첫째가 4개이고 4개씩 늘어나요.","4부터 4씩 세어 봐요 — 4, 8, 12, 16, 20, 24.","24는 6번째에 나오니 여섯째 모양이에요."],"asset":{"type":"tiles","pieces":[{"p":[[2,5],[3,5],[3,6],[2,6]]},{"p":[[0,5],[1,5],[1,6],[0,6]]},{"p":[[1,6],[2,6],[2,7],[1,7]]},{"p":[[1,4],[2,4],[2,5],[1,5]]},{"p":[[8,4],[9,4],[9,5],[8,5]]},{"p":[[9,4],[10,4],[10,5],[9,5]]},{"p":[[6,4],[7,4],[7,5],[6,5]]},{"p":[[5,4],[6,4],[6,5],[5,5]]},{"p":[[7,5],[8,5],[8,6],[7,6]]},{"p":[[7,6],[8,6],[8,7],[7,7]]},{"p":[[7,3],[8,3],[8,4],[7,4]]},{"p":[[7,2],[8,2],[8,3],[7,3]]},{"p":[[16,3],[17,3],[17,4],[16,4]]},{"p":[[17,3],[18,3],[18,4],[17,4]]},{"p":[[18,3],[19,3],[19,4],[18,4]]},{"p":[[14,3],[15,3],[15,4],[14,4]]},{"p":[[13,3],[14,3],[14,4],[13,4]]},{"p":[[12,3],[13,3],[13,4],[12,4]]},{"p":[[15,4],[16,4],[16,5],[15,5]]},{"p":[[15,5],[16,5],[16,6],[15,6]]},{"p":[[15,6],[16,6],[16,7],[15,7]]},{"p":[[15,2],[16,2],[16,3],[15,3]]},{"p":[[15,1],[16,1],[16,2],[15,2]]},{"p":[[15,0],[16,0],[16,1],[15,1]]}],"u":16}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading,