INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#21','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C13',3,'mc','auto','곱셈식 배열에서 계산 결과가 888885(8이 5개 뒤에 5)인 식은 몇째 식인가요?',ARRAY['M4-1-u6-X16','M4-1-u6-X13']::text[],true,'{"seq":21,"concept":"M4-1-u6-C13","difficulty":3,"kind":"mc","stem":"곱셈식 배열에서 계산 결과가 888885(8이 5개 뒤에 5)인 식은 몇째 식인가요?","options":[{"t":"다섯째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X16"},{"t":"넷째","mis":"M4-1-u6-X13"},{"t":"셋째","mis":"M4-1-u6-X13"}],"explanation":["첫째 81, 둘째 882, 셋째 8883 — 몇째와 같은 수만큼 8이 있고 끝에 몇째의 수가 붙어요.","888885는 8이 5개 뒤에 5가 붙은 수예요.","그래서 다섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","9×9","=","81"],["둘째","98×9","=","882"],["셋째","987×9","=","8883"],["…","?×9","=","888885"]]},"variant_rule":{"alt":[{"stem":"곱셈식 배열에서 계산 결과가 888888888(8이 9개)인 식은 몇째 식인가요?","options":[{"t":"여덟째","correct":true},{"t":"아홉째","mis":"M4-1-u6-X16"},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"여섯째","mis":"M4-1-u6-X13"}],"explanation":["첫째 81, 둘째 882, 셋째 8883 — 몇째와 같은 수만큼 8이 있고 끝에 몇째의 수가 붙어요.","888888888은 8이 8개 뒤에 8이 붙은 수예요.","그래서 여덟째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","9×9","=","81"],["둘째","98×9","=","882"],["셋째","987×9","=","8883"],["…","?×9","=","888888888"]]}},{"stem":"곱셈식 배열에서 계산 결과가 8888886(8이 6개 뒤에 6)인 식은 몇째 식인가요?","options":[{"t":"여섯째","correct":true},{"t":"일곱째","mis":"M4-1-u6-X16"},{"t":"다섯째","mis":"M4-1-u6-X13"},{"t":"넷째","mis":"M4-1-u6-X13"}],"explanation":["첫째 81, 둘째 882, 셋째 8883 — 몇째와 같은 수만큼 8이 있고 끝에 몇째의 수가 붙어요.","8888886은 8이 6개 뒤에 6이 붙은 수예요.","그래서 여섯째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","9×9","=","81"],["둘째","98×9","=","882"],["셋째","987×9","=","8883"],["…","?×9","=","8888886"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading