INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#22','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C14',3,'mc','auto','「99×4=33×12」는 양쪽에 연산이 있는 배열의 몇째 식인가요?',ARRAY['M4-1-u6-X13']::text[],true,'{"seq":22,"concept":"M4-1-u6-C14","difficulty":3,"kind":"mc","stem":"「99×4=33×12」는 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"열째","correct":true},{"t":"아홉째","mis":"M4-1-u6-X13"},{"t":"열한째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 18부터 9씩 커져요.","18에서 99가 되려면 9씩 9번 커져야 해요.","첫째에서 9번 커졌으니 열째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","18×4","=","6×12"],["둘째","27×4","=","9×12"]]},"variant_rule":{"alt":[{"stem":"「75×6=15×30」은 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"일곱째","correct":true},{"t":"여섯째","mis":"M4-1-u6-X13"},{"t":"여덟째","mis":"M4-1-u6-X13"},{"t":"다섯째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 15부터 10씩 커져요.","15에서 75가 되려면 10씩 6번 커져야 해요.","첫째에서 6번 커졌으니 일곱째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","15×6","=","3×30"],["둘째","25×6","=","5×30"]]}},{"stem":"「54×5=18×15」는 양쪽에 연산이 있는 배열의 몇째 식인가요?","options":[{"t":"여덟째","correct":true},{"t":"일곱째","mis":"M4-1-u6-X13"},{"t":"아홉째","mis":"M4-1-u6-X13"},{"t":"여섯째","mis":"M4-1-u6-X13"}],"explanation":["왼쪽에서 곱해지는 수는 12부터 6씩 커져요.","12에서 54가 되려면 6씩 7번 커져야 해요.","첫째에서 7번 커졌으니 여덟째 식이에요."],"asset":{"type":"expr_grid","rows":[["첫째","12×5","=","4×15"],["둘째","18×5","=","6×15"]]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#23','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C5',4,'mc','auto','「75−38=78−35」는 옳은 식일까요? 계산하지 않고 판단해 보세요.',ARRAY['M4-1-u6-X05','M4-1-u6-X01']::text[],true,'{"seq":23,"concept":"M4-1-u6-C5","difficulty":4,"kind":"mc","stem":"「75−38=78−35」는 옳은 식일까요? 계산하지 않고 판단해 보세요.","options":[{"t":"옳지 않아요 — 빼어지는 수는 3 커지고 빼는 수는 3 작아져서 차가 6 커져요","correct":true},{"t":"옳아요 — 한쪽이 커진 만큼 다른 쪽이 작아졌어요","mis":"M4-1-u6-X05"},{"t":"옳아요 — 짝이 되는 수의 차가 모두 3이에요","mis":"M4-1-u6-X05"},{"t":"옳지 않아요 — 등호 양쪽이 모두 뺄셈이라서","mis":"M4-1-u6-X01"}],"explanation":["뺄셈에서는 덧셈의 「커진 만큼 작아지면 같다」가 맞지 않아요.","빼어지는 수가 커지고 빼는 수가 작아지면 차는 더 커져요.","75−38 = 37, 78−35 = 43 — 옳지 않은 식이에요."],"variant_rule":{"alt":[{"stem":"「56−27=59−30」은 옳은 식일까요? 계산하지 않고 판단해 보세요.","options":[{"t":"옳아요 — 빼어지는 수와 빼는 수가 똑같이 3 커지면 차는 그대로예요","correct":true},{"t":"옳지 않아요 — 빼는 수가 커졌으니 다른 쪽은 작아져야 해요","mis":"M4-1-u6-X05"},{"t":"옳지 않아요 — 양쪽 수가 모두 달라요","mis":"M4-1-u6-X04"},{"t":"옳아요 — 양쪽에 모두 뺄셈이 있어서","mis":"M4-1-u6-X04"}],"explanation":["뺄셈은 덧셈과 달라요.","56 → 59, 27 → 30 — 둘 다 3 커지면 차이는 그대로예요.","56−27 = 29, 59−30 = 29 — 옳은 식이에요."],"asset":null},{"stem":"「84−12=88−8」은 옳은 식일까요? 계산하지 않고 판단해 보세요.","options":[{"t":"옳지 않아요 — 빼어지는 수는 4 커지고 빼는 수는 4 작아져서 차가 8 커져요","correct":true},{"t":"옳아요 — 한쪽이 커진 만큼 다른 쪽이 작아졌어요","mis":"M4-1-u6-X05"},{"t":"옳아요 — 짝이 되는 수의 차가 모두 4예요","mis":"M4-1-u6-X05"},{"t":"옳지 않아요 — 등호 양쪽이 모두 뺄셈이라서","mis":"M4-1-u6-X01"}],"explanation":["뺄셈에서는 덧셈의 「커진 만큼 작아지면 같다」가 맞지 않아요.","빼어지는 수가 커지고 빼는 수가 작아지면 차는 더 커져요.","84−12 = 72, 88−8 = 80 — 옳지 않은 식이에요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#24','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C12',4,'sa','auto','종이 빨대로 만든 배열의 개수가 첫째부터 1, 4, 9, 16…로 늘어나요. 이렇게 계속 늘어나면 여섯째 모양은 몇 개인가요? 숫자로 쓰세요.','{}'::text[],true,'{"seq":24,"concept":"M4-1-u6-C12","difficulty":4,"kind":"sa","stem":"종이 빨대로 만든 배열의 개수가 첫째부터 1, 4, 9, 16…로 늘어나요. 이렇게 계속 늘어나면 여섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["36"],"explanation":["늘어난 수는 3, 5, 7 — 2씩 커져요.","이어서 9, 11만큼 늘어나요.","여섯째 모양은 36개예요."],"variant_rule":{"alt":[{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 2, 6, 12, 20…로 늘어나요. 이렇게 계속 늘어나면 다섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["30"],"explanation":["늘어난 수는 4, 6, 8 — 2씩 커져요.","이어서 10만큼 늘어나요.","다섯째 모양은 30개예요."],"asset":null},{"stem":"종이 빨대로 만든 배열의 개수가 첫째부터 1, 3, 6, 10…로 늘어나요. 이렇게 계속 늘어나면 여섯째 모양은 몇 개인가요? 숫자로 쓰세요.","answer":["21"],"explanation":["늘어난 수는 2, 3, 4 — 1씩 커져요.","이어서 5, 6만큼 늘어나요.","여섯째 모양은 21개예요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_1_math_u6_review_d#25','math',4,1,'u6','','g4_1_math_u6_review_d','unit_review','M4-1-u6-C13',4,'essay','teacher','뺄셈식 배열 「783−22=761, 783−122=661, 783−222=561」에서 규칙을 찾아 넷째와 다섯째 식을 쓰고, 계산 결과의 규칙을 설명해 보세요.','{}'::text[],false,'{"seq":25,"concept":"M4-1-u6-C13","difficulty":4,"kind":"essay","stem":"뺄셈식 배열 「783−22=761, 783−122=661, 783−222=561」에서 규칙을 찾아 넷째와 다섯째 식을 쓰고, 계산 결과의 규칙을 설명해 보세요.","answer_guide":{"answer":"예: 빼는 수가 100씩 커지므로 결과는 100씩 작아진다. 넷째 식은 783−322=461, 다섯째 식은 783−422=361이다.","scoring_points":["빼는 수가 100씩 커진다고 썼는가","넷째 783−322=461, 다섯째 783−422=361 을 바르게 썼는가","결과가 100씩 작아진다고 설명했는가"]},"explanation":["빼는 수: 22, 122, 222 — 100씩 커져요.","결과: 761, 661, 561 — 100씩 작아져요.","넷째 461, 다섯째 361."],"asset":{"type":"expr_grid","rows":[["첫째","783−22","=","761"],["둘째","783−122","=","661"],["셋째","783−222","=","561"]]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
